import React, { useState, useEffect } from 'react';
import { dbService, Timestamp } from '../services/firebase';
import { UserProfile } from '../types';
import { 
  Building2, Ban, Trash2, Search, DollarSign, Clock, ShieldAlert, Eraser, Loader2
} from 'lucide-react';

const OfficeManagement: React.FC = () => {
  const [offices, setOffices] = useState<UserProfile[]>([]);
  const [search, setSearch] = useState('');
  const [isWiping, setIsWiping] = useState(false);

  useEffect(() => {
    const unsub = dbService.watchNetwork((data) => {
      const sorted = [...data].sort((a: any, b: any) => 
        (a.officeName || "").localeCompare(b.officeName || "")
      );
      setOffices(sorted as UserProfile[]);
    });
    return () => unsub();
  }, []);

  // FUNÇÃO: EXCLUIR TODOS OS TESTES EM PARALELO (NA HORA)
  const handleWipeAllTrials = async () => {
    const trials = offices.filter(o => 
      o.subscriptionStatus === 'TRIAL' && 
      o.email !== "giufarlosdias@hotmail.com"
    );

    if (trials.length === 0) return;

    if (confirm(`NUCLEO DE SEGURANÇA: Deseja apagar DEFINITIVAMENTE todos os ${trials.length} terminais em TESTE agora?`)) {
      setIsWiping(true);
      try {
        // Execução em paralelo para performance máxima
        await Promise.all(trials.map(office => dbService.del('users', office.uid)));
      } catch (e) {
        console.error("Erro na limpeza em massa", e);
      } finally {
        setIsWiping(false);
      }
    }
  };

  const handleConfirmPayment = async (uid: string) => {
    const nextExpiry = new Date();
    nextExpiry.setDate(nextExpiry.getDate() + 30);

    // Atualização direta sem travar o fluxo
    dbService.update('users', uid, { 
      subscriptionStatus: 'PAID',
      status: 'active',
      subscriptionExpiresAt: Timestamp.fromDate(nextExpiry)
    }).catch(() => alert("Erro ao sincronizar pagamento."));
  };

  const handleToggleBlock = async (uid: string, currentStatus: string) => {
    const nextStatus = currentStatus === 'active' ? 'blocked' : 'active';
    dbService.update('users', uid, { status: nextStatus });
  };

  // EXCLUSÃO NA HORA: Sem confirm individual para agilizar a limpeza manual
  const handleDelete = async (uid: string) => {
    // Dispara a exclusão. O onSnapshot do Firestore removerá do UI instantaneamente (Optimistic)
    dbService.del('users', uid).catch(() => alert("Falha ao remover terminal."));
  };

  const filtered = offices.filter(o => 
    o.email?.toLowerCase().includes(search.toLowerCase()) || 
    o.officeName?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-12 animate-fade-in pb-20">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
          <h2 className="text-4xl font-black text-white italic tracking-tighter text-glow-cyan leading-none uppercase">Gestão de Rede Nexus</h2>
          <p className="text-slate-500 font-bold text-sm tracking-widest uppercase mt-4 italic opacity-70">Monitoramento e Faturamento de Terminais.</p>
        </div>

        <div className="flex flex-wrap gap-4 w-full lg:w-auto">
          <button 
            onClick={handleWipeAllTrials}
            disabled={isWiping}
            className="flex-1 lg:flex-none bg-rose-500/10 border border-rose-500/30 text-rose-500 px-6 py-4 rounded-2xl hover:bg-rose-500 hover:text-white transition-all font-black text-[10px] uppercase flex items-center justify-center gap-3 disabled:opacity-50"
          >
            {isWiping ? <Loader2 className="animate-spin" size={18}/> : <Eraser size={18}/>} 
            {isWiping ? 'Limpando...' : 'Excluir Todos os Testes'}
          </button>

          <div className="flex-1 lg:flex-none bg-[#1a0a2e] p-2 rounded-2xl flex items-center gap-4 border border-white/5 focus-within:border-cyan-400/50 transition-all">
            <Search className="ml-4 text-slate-500" size={18} />
            <input 
              placeholder="Localizar terminal..." 
              className="bg-transparent border-0 outline-none p-4 text-white font-bold w-full lg:w-64 placeholder:text-slate-700"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
        </div>
      </div>

      <div className="space-y-4">
        {filtered.map(office => (
          <div key={office.uid} className="nexus-card p-8 border border-white/5 flex flex-col lg:flex-row items-center justify-between gap-6 hover:border-cyan-400/40 transition-all box-glow-orange animate-fade-in">
             <div className="flex items-center gap-8 w-full lg:w-auto">
               <div className={`w-16 h-16 rounded-2xl flex items-center justify-center border transition-all ${office.subscriptionStatus === 'PAID' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.3)]' : 'bg-amber-500/10 border-amber-500/30 text-amber-400'}`}>
                 <Building2 size={32} />
               </div>
               <div>
                 <div className="flex items-center gap-4 flex-wrap">
                   <h4 className="text-xl font-black text-white italic tracking-tight uppercase">{office.officeName}</h4>
                   <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${office.subscriptionStatus === 'PAID' ? 'bg-emerald-500 text-black' : 'bg-amber-500 text-black'}`}>
                     {office.subscriptionStatus === 'PAID' ? 'ASSINATURA ATIVA' : 'PERÍODO TRIAL'}
                   </span>
                   {office.status === 'blocked' && (
                     <span className="bg-rose-600 text-white px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest animate-pulse">BLOQUEADO</span>
                   )}
                 </div>
                 <div className="flex items-center gap-4 mt-2">
                   <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{office.email}</p>
                   <span className="w-1 h-1 bg-slate-800 rounded-full"></span>
                   <p className="text-[10px] font-black text-cyan-400 uppercase tracking-widest flex items-center gap-2">
                     <Clock size={12} /> Expira: {office.subscriptionExpiresAt?.toDate().toLocaleDateString('pt-BR')}
                   </p>
                 </div>
               </div>
             </div>

             <div className="flex items-center gap-3 w-full lg:w-auto justify-end">
                <button 
                  type="button"
                  onClick={() => handleConfirmPayment(office.uid)}
                  className="flex items-center gap-3 px-6 py-4 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500 hover:text-black border border-emerald-500/20"
                >
                  <DollarSign size={16}/> +30 Dias
                </button>

                <button 
                  type="button"
                  onClick={() => handleToggleBlock(office.uid, office.status)}
                  className={`p-4 rounded-xl transition-all border ${office.status === 'active' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20 hover:bg-amber-500 hover:text-black' : 'bg-cyan-500/10 text-cyan-500 border-cyan-500/20 hover:bg-cyan-500 hover:text-black'}`}
                  title={office.status === 'active' ? 'Bloquear Acesso' : 'Desbloquear Acesso'}
                >
                  <Ban size={20}/>
                </button>

                <button 
                  type="button"
                  disabled={office.email === "giufarlosdias@hotmail.com"}
                  onClick={() => handleDelete(office.uid)}
                  className="p-4 bg-white/5 text-slate-700 hover:bg-rose-600 hover:text-white border border-white/5 rounded-xl transition-all disabled:opacity-0"
                  title="Excluir Definitivamente"
                >
                  <Trash2 size={20}/>
                </button>
             </div>
          </div>
        ))}

        {filtered.length === 0 && (
          <div className="py-40 text-center flex flex-col items-center">
            <ShieldAlert size={80} className="text-white/5 mb-8" />
            <p className="text-slate-700 font-black uppercase tracking-[0.6em] italic">Rede de Terminais Vazia.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default OfficeManagement;

import React, { useState, useEffect } from 'react';
import { dbService } from '../services/firebase';
import { UserProfile } from '../types';
import { Search, Loader2, RefreshCw, Trash2, ShieldAlert, UserCheck, Ban, Calendar } from 'lucide-react';
import { Timestamp } from 'firebase/firestore';

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const unsub = dbService.watchNetwork((data) => {
      setUsers(data as UserProfile[]);
      setIsLoading(false);
    });
    return () => unsub();
  }, []);

  const handleToggleBlock = async (user: UserProfile) => {
    const newStatus = user.status === 'blocked' ? 'active' : 'blocked';
    dbService.update('users', user.uid, { status: newStatus });
  };

  const handleExtendTrial = async (user: UserProfile) => {
    const newDate = new Date();
    newDate.setMonth(newDate.getMonth() + 1);
    dbService.update('users', user.uid, { subscriptionExpiresAt: Timestamp.fromDate(newDate) });
  };

  const handleDelete = async (uid: string) => {
    dbService.del('users', uid).catch(() => alert("Erro ao excluir."));
  };

  const filteredUsers = users.filter(u => u.email.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-10 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-rose-500 rounded-2xl flex items-center justify-center shadow-lg shadow-rose-500/30">
            <ShieldAlert size={32} className="text-white" />
          </div>
          <div>
            <h2 className="text-4xl font-black text-white italic tracking-tighter text-glow-rose leading-none uppercase">Console Master</h2>
            <p className="text-slate-500 font-bold text-sm tracking-wide uppercase opacity-70">Controle Global da Rede Nexus.</p>
          </div>
        </div>
        <div className="bg-white/5 px-6 py-4 rounded-2xl border border-white/10">
          <p className="text-[9px] font-black text-cyan-400 uppercase tracking-widest mb-1">Operadores Ativos</p>
          <p className="text-2xl font-black text-white italic">{users.length}</p>
        </div>
      </div>

      <div className="bg-[#1a0a2e]/80 p-6 rounded-3xl border border-rose-500/20 flex items-center gap-4">
        <Search className="text-rose-500/50" size={24} />
        <input 
          placeholder="Localizar terminal operacional..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="flex-1 bg-transparent outline-none font-black text-white placeholder:text-slate-700 text-xl" 
        />
      </div>

      <div className="nexus-card overflow-hidden bg-[#0f041a]/90">
        <div className="overflow-x-auto">
          <table className="w-full text-left min-w-[900px]">
            <thead>
              <tr className="bg-rose-500/5">
                <th className="px-8 py-6 text-[10px] font-black text-rose-400 uppercase tracking-widest opacity-60">Operador</th>
                <th className="px-8 py-6 text-[10px] font-black text-rose-400 uppercase tracking-widest opacity-60">Expiração</th>
                <th className="px-8 py-6 text-[10px] font-black text-rose-400 uppercase tracking-widest opacity-60">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-rose-400 uppercase tracking-widest opacity-60 text-right">Controle</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {isLoading ? (
                <tr><td colSpan={4} className="py-20 text-center"><Loader2 className="animate-spin mx-auto text-rose-500" /></td></tr>
              ) : filteredUsers.map(user => (
                <tr key={user.uid} className="hover:bg-rose-500/5 transition-all group">
                  <td className="px-8 py-8">
                    <p className="font-black text-white text-lg tracking-tight">{user.email}</p>
                    <p className="text-[8px] font-bold text-slate-600 uppercase tracking-widest">ID: {user.uid.substring(0,10)}</p>
                  </td>
                  <td className="px-8 py-8 text-slate-400 text-sm font-bold flex items-center gap-3">
                    <Calendar size={14} className="text-rose-400/40" />
                    {user.subscriptionExpiresAt?.toDate().toLocaleDateString('pt-BR')}
                  </td>
                  <td className="px-8 py-8">
                     <span className={`px-4 py-1.5 rounded-lg text-[8px] font-black uppercase border ${user.status === 'active' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' : 'bg-rose-500/10 text-rose-500 border-rose-500/20'}`}>
                       {user.status === 'active' ? 'OPERACIONAL' : 'BLOQUEADO'}
                     </span>
                  </td>
                  <td className="px-8 py-8 text-right">
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => handleExtendTrial(user)} className="p-3 bg-emerald-500/10 text-emerald-500 rounded-xl hover:bg-emerald-500 hover:text-black transition-all" title="Estender Acesso"><RefreshCw size={18} /></button>
                      <button onClick={() => handleToggleBlock(user)} className={`p-3 rounded-xl transition-all ${user.status === 'blocked' ? 'bg-cyan-500/10 text-cyan-500 hover:bg-cyan-500 hover:text-black' : 'bg-rose-500/10 text-rose-500 hover:bg-rose-500 hover:text-white'}`} title="Bloquear/Desbloquear">{user.status === 'blocked' ? <UserCheck size={18} /> : <Ban size={18} />}</button>
                      {user.role !== 'super-admin' && (
                        <button onClick={() => handleDelete(user.uid)} className="p-3 bg-white/5 text-slate-500 rounded-xl hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={18} /></button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AdminView;

import React, { useState, useEffect } from 'react';
import { ShoppingCart, Plus, Minus, Trash2, Search, X, Loader2, Zap, Smartphone, User, Edit2, ChevronDown, ChevronUp, Calendar, CheckCircle, MessageCircle } from 'lucide-react';
import { Order, Product, Customer, OrderItem, UserProfile, Installment } from '../types';
import { dbService, Timestamp } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [guestData, setGuestData] = useState({ name: '', phone: '' });
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1' });
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);

  useEffect(() => {
    if (selectedCustomerId) {
      const c = customers.find(cust => cust.id === selectedCustomerId);
      if (c) setGuestData({ name: c.name, phone: c.phone || '' });
    } else {
      setGuestData({ name: '', phone: '' });
    }
  }, [selectedCustomerId, customers]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type as any }];
    });
  };

  const addManualToCart = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha dados do item.");
    setCart(prev => [...prev, {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: 'PRODUCT'
    }]);
    setManualItem({ name: '', price: '', qty: '1' });
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Carrinho vazio.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const installmentDetails: Installment[] = Array.from({ length: installments }).map((_, idx) => {
        const dueDate = new Date();
        dueDate.setMonth(dueDate.getMonth() + idx);
        return {
          id: `inst-${Date.now()}-${idx}`,
          value: total / installments,
          status: 'PENDING',
          dueDate: Timestamp.fromDate(dueDate)
        };
      });

      const orderData: any = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: 'PAID',
        paymentMethod,
        installments,
        installmentDetails,
        guestName: guestData.name.toUpperCase() || 'VENDA RÁPIDA',
        guestPhone: guestData.phone
      };

      await dbService.add('orders', userId, orderData);
      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
      setGuestData({ name: '', phone: '' });
      setInstallments(1);
    } catch (e) { alert('Falha ao processar.'); } finally { setIsProcessing(false); }
  };

  const sendInstallmentReminder = (order: Order, inst: Installment, index: number) => {
    const phone = order.guestPhone?.replace(/\D/g, '');
    if (!phone) return alert("Telefone não cadastrado para este cliente.");

    const dueDate = inst.dueDate?.toDate ? inst.dueDate.toDate().toLocaleDateString('pt-BR') : 'A combinar';
    const msg = encodeURIComponent(
      `Olá ${order.guestName}!\n\nLembrete de pagamento da *Parcela ${index + 1}* referente à sua compra no valor de *R$ ${inst.value.toFixed(2)}*.\n\n📅 Vencimento: ${dueDate}\n💳 Status: ${inst.status === 'PAID' ? 'PAGO' : 'PENDENTE'}\n\n_Enviado via ${profile.officeName}_`
    );
    window.open(`https://wa.me/55${phone}?text=${msg}`, '_blank');
  };

  const updateInstallment = async (order: Order, instId: string, updates: Partial<Installment>) => {
    const newDetails = order.installmentDetails?.map(inst => 
      inst.id === instId ? { ...inst, ...updates } : inst
    );
    const newTotal = newDetails?.reduce((s, i) => s + i.value, 0) || order.total;
    await dbService.update('orders', order.id, { installmentDetails: newDetails, total: newTotal });
  };

  const removeInstallment = async (order: Order, instId: string) => {
    if (!confirm("Excluir esta parcela permanentemente?")) return;
    const newDetails = order.installmentDetails?.filter(inst => inst.id !== instId);
    const newTotal = newDetails?.reduce((s, i) => s + i.value, 0) || 0;
    await dbService.update('orders', order.id, { installmentDetails: newDetails, total: newTotal });
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20 px-2 lg:px-0">
      <div className="flex justify-between items-center">
        <h2 className="text-3xl lg:text-4xl font-black text-white italic tracking-tighter text-glow-cyan">Vendas PdV</h2>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-radiant px-6 py-3 rounded-xl flex items-center gap-2 text-[10px]"><Plus size={16}/> NOVA VENDA</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="nexus-card p-6 border-cyan-400/20 bg-cyan-400/5 box-glow-orange">
              <div className="flex gap-2">
                <input placeholder="Item..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 p-3 rounded-lg" />
                <input placeholder="R$" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-20 p-3 rounded-lg" />
                <button onClick={addManualToCart} className="bg-cyan-400 text-black px-4 rounded-lg font-black"><Plus/></button>
              </div>
            </div>
            <div className="bg-white/5 p-4 rounded-2xl border border-white/5 flex items-center gap-3">
              <Search className="text-cyan-400" size={18}/>
              <input placeholder="Filtrar catálogo..." className="bg-transparent flex-1 outline-none text-white font-bold text-sm" value={search} onChange={e => setSearch(e.target.value)} />
            </div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-3 max-h-[300px] overflow-y-auto pr-1">
              {products.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => addToCart(p)} className="nexus-card p-4 text-left hover:border-cyan-400/30 transition-all">
                   <p className="font-black text-white text-[10px] truncate uppercase">{p.name}</p>
                   <p className="text-cyan-400 font-black text-sm mt-1">R$ {p.price.toFixed(2)}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-6 h-fit border-orange-400/30">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-terminal font-black text-sm text-glow-orange uppercase">Checkout</h3>
              <button onClick={() => setIsCreating(false)}><X className="text-slate-500"/></button>
            </div>
            <div className="space-y-6">
              <div className="space-y-4 bg-black/30 p-4 rounded-2xl border border-white/5">
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full p-3 rounded-xl text-[10px] uppercase font-bold">
                  <option value="">-- CLIENTE AVULSO --</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
                <input placeholder="NOME DO CLIENTE" value={guestData.name} onChange={e => setGuestData({...guestData, name: e.target.value})} className="w-full p-3 rounded-xl text-[10px] uppercase font-bold" />
                <input placeholder="WHATSAPP" value={guestData.phone} onChange={e => setGuestData({...guestData, phone: e.target.value})} className="w-full p-3 rounded-xl text-[10px] font-bold" />
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest">Parcelas</label>
                <select value={installments} onChange={e => setInstallments(parseInt(e.target.value))} className="w-full p-4 rounded-xl text-xs">
                  {[1,2,3,4,5,6,10,12,24].map(n => <option key={n} value={n}>{n}x</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-2">
                {['PIX', 'CASH', 'CREDIT_CARD', 'DEFERRED'].map(m => (
                  <button key={m} onClick={() => setPaymentMethod(m as any)} className={`p-3 rounded-lg border text-[8px] font-black ${paymentMethod === m ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}>{m}</button>
                ))}
              </div>
              <div className="pt-6 border-t border-white/5">
                <div className="flex justify-between items-end mb-6">
                   <span className="text-slate-500 text-[10px] font-black uppercase">Total</span>
                   <span className="text-3xl font-black text-white italic text-glow-cyan">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || cart.length === 0} onClick={finalize} className="btn-radiant w-full py-5 rounded-xl font-black text-[12px] flex justify-center gap-2">
                  {isProcessing ? <Loader2 className="animate-spin" size={16}/> : <Zap size={16}/>} FINALIZAR VENDA
                </button>
              </div>
            </div>
