                    <div>
                      <p className="text-[8px] font-mono text-slate-500 uppercase tracking-widest">#{o.id.substring(0,6)} • {o.paymentMethod}</p>
                      <p className="text-lg font-black text-white italic tracking-tight uppercase">{o.guestName || 'Venda Rápida'}</p>
                    </div>
                    <div className="flex items-center gap-6">
                       <p className="text-2xl font-black text-cyan-400 italic text-glow-cyan">R$ {o.total.toFixed(2)}</p>
                       {isExpanded ? <ChevronUp className="text-slate-500"/> : <ChevronDown className="text-slate-500"/>}
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="p-8 bg-black/30 border-t border-white/5 animate-fade-in space-y-10">
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
