                             <div className="bg-white/5 p-4 rounded-xl border border-white/10 mb-6">
                                <p className="text-white font-black uppercase text-sm">{o.guestName}</p>
                                <p className="text-[10px] text-slate-400 font-bold mt-1 flex items-center gap-2"><Smartphone size={10}/> {o.guestPhone || 'Sem telefone'}</p>
                             </div>

                             <h4 className="text-[10px] font-black text-cyan-400 uppercase tracking-widest mb-4 flex items-center gap-2"><ShoppingCart size={14}/> Itens</h4>
                             <div className="space-y-3">
                                {o.items.map((item, idx) => (
                                  <div key={idx} className="flex justify-between text-xs p-3 bg-white/5 rounded-xl border border-white/5">
                                     <span className="text-white font-bold uppercase">{item.quantity}x {item.nameAtTime}</span>
                                     <span className="text-slate-400 font-black">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</span>
                                  </div>
                                ))}
                             </div>
                          </div>

                          <div>
                             <h4 className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-6 flex items-center gap-2"><Calendar size={14}/> Cronograma de Parcelas</h4>
                             <div className="space-y-4">
                                {(o.installmentDetails || []).map((inst, idx) => (
                                  <div key={inst.id} className="flex flex-col gap-3 p-4 bg-white/5 rounded-2xl border border-white/5 transition-all hover:border-orange-500/30 group">
                                     <div className="flex justify-between items-center">
                                        <span className="text-[9px] font-black text-slate-500 uppercase">PARCELA {idx+1} • {inst.dueDate?.toDate ? inst.dueDate.toDate().toLocaleDateString('pt-BR') : 'Sem data'}</span>
                                        <div className="flex gap-2">
                                          <button onClick={() => sendInstallmentReminder(o, inst, idx)} className="flex items-center gap-2 bg-emerald-500/10 text-emerald-500 px-3 py-1 rounded-lg text-[8px] font-black uppercase hover:bg-emerald-500 hover:text-black transition-all">
                                             <MessageCircle size={12}/> Cobrar
                                          </button>
                                          <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase ${inst.status === 'PAID' ? 'bg-emerald-500 text-black' : 'bg-amber-500 text-black'}`}>
                                            {inst.status === 'PAID' ? 'PAGO' : 'PENDENTE'}
                                          </span>
                                        </div>
                                     </div>
                                     <div className="flex items-center gap-4">
                                        <div className="relative flex-1">
                                          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-500">R$</span>
                                          <input 
                                            type="number" 
                                            value={inst.value} 
                                            onChange={(e) => updateInstallment(o, inst.id, { value: parseFloat(e.target.value) })}
                                            className="w-full bg-black/40 border border-white/5 pl-8 pr-4 py-2 rounded-xl text-white font-black text-sm outline-none focus:border-orange-500"
                                          />
                                        </div>
                                        <div className="flex gap-2">
                                           <button onClick={() => updateInstallment(o, inst.id, { status: inst.status === 'PAID' ? 'PENDING' : 'PAID' })} className={`p-3 rounded-xl transition-all ${inst.status === 'PAID' ? 'bg-amber-500/10 text-amber-500' : 'bg-emerald-500/10 text-emerald-500'}`}>
                                              {inst.status === 'PAID' ? <X size={16}/> : <CheckCircle size={16}/>}
                                           </button>
                                           <button onClick={() => removeInstallment(o, inst.id)} className="p-3 bg-rose-500/10 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all">
                                              <Trash2 size={16}/>
                                           </button>
                                        </div>
                                     </div>
                                  </div>
                                ))}
                             </div>
                          </div>
                       </div>
                    </div>
                  )}
               </div>
             );
           })}
        </div>
      )}
    </div>
  );
};

export default OrdersView;

import React, { useState } from 'react';
import { FileText, Plus, Minus, Trash2, Search, X, Loader2, Zap, Smartphone, Calendar, FileType, Briefcase, User, Download, MessageCircle, ChevronDown, ChevronUp } from 'lucide-react';
import { Quote, Product, Customer, OrderItem, UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface QuotesViewProps {
  quotes: Quote[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const QuotesView: React.FC<QuotesViewProps> = ({ quotes, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [items, setItems] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [guestData, setGuestData] = useState({ name: '', phone: '' });
  const [installments, setInstallments] = useState(1);
  const [validUntil, setValidUntil] = useState('');
  const [notes, setNotes] = useState('');
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1', type: 'SERVICE' as any });
  const [expandedQuoteId, setExpandedQuoteId] = useState<string | null>(null);

  const addItem = (product: Product) => {
    setItems(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type as any }];
    });
  };

  const updateQty = (id: string, delta: number) => {
    setItems(prev => prev.map(item => {
      if (item.productId === id) return { ...item, quantity: Math.max(1, item.quantity + delta) };
      return item;
    }));
  };

  const addManualItem = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha a descrição e o valor.");
    setItems(prev => [...prev, {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: manualItem.type
    }]);
    setManualItem({ name: '', price: '', qty: '1', type: 'SERVICE' });
  };

  const generatePDFAndShare = (quote: Quote) => {
    const customerName = quote.customerId === 'GUEST' ? (quote as any).guestName : quote.customerName;
    const customerPhone = (quote as any).guestPhone || '';

    const printWindow = window.open('', '_blank');
    if (printWindow) {
      const html = `
        <html>
        <head>
          <title>Orçamento #${quote.id}</title>
          <style>
            body { font-family: sans-serif; padding: 40px; color: #333; line-height: 1.6; }
            .header { border-bottom: 3px solid #00f3ff; padding-bottom: 20px; margin-bottom: 30px; }
            .office-name { font-size: 28px; font-weight: 800; color: #000; text-transform: uppercase; }
            .items-table { width: 100%; border-collapse: collapse; margin-top: 30px; }
            .items-table th { background: #f8fafc; padding: 15px; text-align: left; font-size: 12px; text-transform: uppercase; color: #64748b; }
            .items-table td { border-bottom: 1px solid #e2e8f0; padding: 15px; font-size: 14px; }
            .total-row { font-size: 24px; font-weight: 900; text-align: right; margin-top: 40px; border-top: 2px solid #000; padding-top: 20px; }
            .notes { margin-top: 50px; padding: 20px; background: #f1f5f9; border-radius: 10px; font-size: 13px; }
          </style>
        </head>
        <body onload="window.print()">
          <div class="header">
            <div class="office-name">${profile.officeName}</div>
            <div>${profile.address || 'Terminal Operacional Nexus'}</div>
            <div>Contato: ${profile.phone || ''}</div>
          </div>
          <h1>PROPOSTA COMERCIAL #${quote.id.substring(0,8).toUpperCase()}</h1>
          <p><strong>Cliente:</strong> ${customerName}</p>
          <p><strong>Identificação:</strong> ${customerPhone}</p>
          <p><strong>Emissão:</strong> ${new Date().toLocaleDateString('pt-BR')}</p>
          <p><strong>Validade da Proposta:</strong> ${new Date(quote.validUntil).toLocaleDateString('pt-BR')}</p>

          <table class="items-table">
            <thead>
              <tr><th>Item/Serviço</th><th>Tipo</th><th>Qtd</th><th>Unitário</th><th>Subtotal</th></tr>
            </thead>
            <tbody>
              ${quote.items.map(i => `
                <tr>
                  <td><strong>${i.nameAtTime}</strong></td>
                  <td>${i.type}</td>
                  <td>${i.quantity}</td>
                  <td>R$ ${i.priceAtTime.toFixed(2)}</td>
                  <td>R$ ${(i.priceAtTime * i.quantity).toFixed(2)}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>

          <div class="total-row">VALOR TOTAL: R$ ${quote.total.toFixed(2)}</div>
          <p><strong>Condição de Pagamento:</strong> Parcelado em ${ (quote as any).installments || 1 }x</p>

          <div class="notes"><strong>Observações Técnicas:</strong><br>${quote.notes || 'Nenhuma observação adicional.'}</div>
          <div style="margin-top: 40px; text-align: center; font-size: 10px; color: #94a3b8;">Documento gerado eletronicamente via Nexus OS 2.0 Elite</div>
        </body>
        </html>
      `;
      printWindow.document.write(html);
      printWindow.document.close();
    }
  };

  const sendWhatsAppQuote = (quote: Quote) => {
    const customerName = quote.customerId === 'GUEST' ? (quote as any).guestName : quote.customerName;
    const customerPhone = (quote as any).guestPhone?.replace(/\D/g, '') || '';
    if (!customerPhone) return alert("Telefone do cliente não encontrado.");

    let msg = `*📄 PROPOSTA COMERCIAL - ${profile.officeName}*\n\n`;
    msg += `*Olá ${customerName}!* Segue o detalhamento do seu orçamento:\n\n`;
    quote.items.forEach(i => {
      msg += `• ${i.quantity}x ${i.nameAtTime} - R$ ${(i.priceAtTime * i.quantity).toFixed(2)}\n`;
    });
    msg += `\n*TOTAL: R$ ${quote.total.toFixed(2)}*\n`;
    msg += `*Parcelamento:* ${(quote as any).installments || 1}x\n`;
    msg += `*Validade:* ${new Date(quote.validUntil).toLocaleDateString('pt-BR')}\n\n`;
    msg += `_Deseja prosseguir com a aprovação?_`;

    window.open(`https://wa.me/55${customerPhone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const finalize = async () => {
    if (items.length === 0 || !validUntil) return alert('Selecione itens e validade.');
    if (!selectedCustomerId && !guestData.name) return alert('Identifique o cliente.');

    setIsProcessing(true);
    try {
      const total = items.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const customer = customers.find(c => c.id === selectedCustomerId);

      const quoteData = {
        customerId: selectedCustomerId || 'GUEST',
        customerName: customer?.name || guestData.name.toUpperCase(),
        guestName: guestData.name.toUpperCase(),
        guestPhone: guestData.phone,
        items,
        total,
        status: 'SENT',
        validUntil,
        notes,
        installments: installments
      };

      await dbService.add('quotes', userId, quoteData);
      setIsCreating(false);
      setItems([]);
      setSelectedCustomerId('');
      setGuestData({ name: '', phone: '' });
      setValidUntil('');
      setNotes('');
    } catch (e) { alert('Erro ao salvar.'); } finally { setIsProcessing(false); }
  };

  return (
    <div className="space-y-12 animate-fade-in pb-24">
