                <div className="flex justify-between items-end mb-6">
                   <span className="text-slate-500 text-[10px] font-black uppercase">Subtotal</span>
                   <span className="text-3xl font-black text-white italic text-glow-purple">R$ {items.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || items.length === 0} onClick={finalize} className="w-full bg-purple-600 text-white py-5 rounded-2xl font-black text-sm flex justify-center gap-3 hover:bg-purple-500 transition-all box-glow-purple">
