import { dbService } from '../services/firebase';

interface ExpensesViewProps {
  expenses: Expense[];
  userId: string;
  profile: UserProfile;
}

const ExpensesView: React.FC<ExpensesViewProps> = ({ expenses, userId, profile }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({ description: '', amount: '', category: 'Operacional' });

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await dbService.add('expenses', userId, {
        description: formData.description,
        amount: parseFloat(formData.amount),
        category: formData.category
      });
      setIsModalOpen(false);
      setFormData({ description: '', amount: '', category: 'Operacional' });
    } catch (err) { alert("Erro ao salvar."); } finally { setIsSaving(false); }
  };

  const sendWeeklyReport = () => {
    const lastWeek = new Date();
    lastWeek.setDate(lastWeek.getDate() - 7);

    // Compila todos os gastos dos últimos 7 dias na hora
    const recentExpenses = expenses.filter(e => {
        const date = e.createdAt?.toDate ? e.createdAt.toDate() : new Date();
        return date >= lastWeek;
    });

    if (recentExpenses.length === 0) return alert("Nenhum custo registrado nos últimos 7 dias para compor o relatório.");

    const total = recentExpenses.reduce((s, e) => s + e.amount, 0);

    let msg = `*📊 RELATÓRIO DE SAÍDAS NEXUS*\n`;
    msg += `*Terminal:* ${profile.officeName}\n`;
