    msg += `----------------------------------\n`;

    recentExpenses.forEach(e => {
        const d = e.createdAt?.toDate ? e.createdAt.toDate().toLocaleDateString('pt-BR') : '--/--';
        msg += `• [${d}] ${e.description.toUpperCase()} - R$ ${e.amount.toFixed(2)} (${e.category})\n`;
