    // Envia para o próprio WhatsApp do perfil
    const phone = profile.phone?.replace(/\D/g, '');
    if (!phone) return alert("Por favor, cadastre seu WhatsApp nas Configurações para receber o relatório.");

    window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(msg)}`, '_blank');
