            </div>
            <p className="text-slate-500 font-black text-xl uppercase tracking-widest opacity-40 italic">Nenhuma saída detectada.</p>
         </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl">
          <div className="nexus-card w-full max-w-xl p-8 lg:p-12 animate-fade-in border-rose-500/40">
            <div className="flex justify-between items-center mb-12">
              <h3 className="text-2xl lg:text-3xl font-black text-white italic text-rose-500 uppercase">Novo Registro de Custo</h3>
