            .items-table td { border-bottom: 1px solid #e2e8f0; padding: 15px; font-size: 14px; }
            .total-row { font-size: 24px; font-weight: 900; text-align: right; margin-top: 40px; border-top: 2px solid #000; padding-top: 20px; }
            .notes { margin-top: 50px; padding: 20px; background: #f1f5f9; border-radius: 10px; font-size: 13px; }
          </style>
        </head>
        <body onload="window.print()">
          <div class="header">
            <div class="office-name">${profile.officeName}</div>
            <div>${profile.address || 'Terminal Operacional Nexus'}</div>
            <div>Contato: ${profile.phone || ''}</div>
          </div>
          <h1>PROPOSTA COMERCIAL #${quote.id.substring(0,8).toUpperCase()}</h1>
          <p><strong>Cliente:</strong> ${customerName}</p>
          <p><strong>Identificação:</strong> ${customerPhone}</p>
          <p><strong>Emissão:</strong> ${new Date().toLocaleDateString('pt-BR')}</p>
