        total,
        status: 'SENT',
        validUntil,
        notes,
        installments: installments
      };

      await dbService.add('quotes', userId, quoteData);
      setIsCreating(false);
      setItems([]);
      setSelectedCustomerId('');
      setGuestData({ name: '', phone: '' });
      setValidUntil('');
      setNotes('');
