                       <div className="flex items-center gap-2">
                          <button onClick={() => updateQty(item.productId, -1)} className="p-1 bg-white/5 rounded text-white"><Minus size={10}/></button>
                          <span className="text-purple-400 font-black text-xs">{item.quantity}</span>
                          <button onClick={() => updateQty(item.productId, 1)} className="p-1 bg-white/5 rounded text-white"><Plus size={10}/></button>
                       </div>
                       <div className="text-white font-black text-xs">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="pt-6 border-t border-white/10">
                <div className="flex justify-between items-end mb-6">
                   <span className="text-slate-500 text-[10px] font-black uppercase">Subtotal</span>
                   <span className="text-3xl font-black text-white italic text-glow-purple">R$ {items.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || items.length === 0} onClick={finalize} className="w-full bg-purple-600 text-white py-5 rounded-2xl font-black text-sm flex justify-center gap-3 hover:bg-purple-500 transition-all box-glow-purple">
                  {isProcessing ? <Loader2 className="animate-spin"/> : <Zap size={18}/>} SALVAR PROPOSTA
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
           {quotes.map(q => {
             const isExpanded = expandedQuoteId === q.id;
             return (
               <div key={q.id} className="nexus-card overflow-hidden border-purple-500/20">
                  <div onClick={() => setExpandedQuoteId(isExpanded ? null : q.id)} className="p-8 flex justify-between items-center cursor-pointer hover:bg-white/5 transition-all">
                    <div>
                      <p className="text-[8px] font-mono text-slate-500 uppercase tracking-widest mb-1">ID: {q.id.substring(0,8).toUpperCase()}</p>
                      <h4 className="font-black text-white text-xl uppercase tracking-tight italic">{q.customerName}</h4>
                    </div>
                    <div className="flex items-center gap-6">
                       <p className="text-3xl font-black text-purple-400 italic text-glow-purple">R$ {q.total.toFixed(2)}</p>
                       {isExpanded ? <ChevronUp className="text-slate-500"/> : <ChevronDown className="text-slate-500"/>}
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="p-8 bg-black/40 border-t border-white/5 animate-fade-in space-y-10">
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                          <div className="space-y-6">
                             <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                                <h5 className="text-[10px] font-black text-purple-400 uppercase tracking-widest mb-4 flex items-center gap-2"><User size={14}/> Cliente</h5>
                                <p className="text-white font-black text-lg uppercase">{q.customerName}</p>
                                <p className="text-[10px] text-slate-400 font-bold mt-1">{(q as any).guestPhone || 'WhatsApp não vinculado'}</p>
                             </div>

                             <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                                <h5 className="text-[10px] font-black text-purple-400 uppercase tracking-widest mb-4 flex items-center gap-2"><ShoppingCart size={14}/> Itens Inclusos</h5>
                                <div className="space-y-3">
                                   {q.items.map((item, idx) => (
                                     <div key={idx} className="flex justify-between text-[11px] p-2 bg-black/20 rounded-lg">
                                        <span className="text-white font-bold">{item.quantity}x {item.nameAtTime}</span>
                                        <span className="text-purple-400 font-black">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</span>
                                     </div>
                                   ))}
                                </div>
                             </div>
                          </div>

                          <div className="flex flex-col justify-between">
                             <div className="space-y-4">
                                <div className="flex justify-between items-center text-[10px] font-black uppercase text-slate-500">
                                   <span>Condição: {(q as any).installments || 1}x Parcelas</span>
                                   <span>Válido até: {new Date(q.validUntil).toLocaleDateString('pt-BR')}</span>
                                </div>
                                <div className="p-4 bg-white/5 rounded-2xl border border-white/5 text-[11px] text-slate-400 italic">
                                   <strong>Notas Nexus:</strong> {q.notes || 'Nenhuma observação registrada.'}
                                </div>
                             </div>

                             <div className="grid grid-cols-2 gap-4 mt-10">
                                <button onClick={() => sendWhatsAppQuote(q)} className="flex items-center justify-center gap-3 bg-emerald-500/10 text-emerald-500 border border-emerald-500/30 p-5 rounded-2xl font-black uppercase text-[10px] hover:bg-emerald-500 hover:text-black transition-all">
                                   <MessageCircle size={18}/> Enviar Zap
                                </button>
                                <button onClick={() => generatePDFAndShare(q)} className="flex items-center justify-center gap-3 bg-cyan-500/10 text-cyan-500 border border-cyan-500/30 p-5 rounded-2xl font-black uppercase text-[10px] hover:bg-cyan-500 hover:text-black transition-all">
                                   <Download size={18}/> Baixar PDF
                                </button>
                                <button onClick={() => dbService.del('quotes', q.id)} className="col-span-2 flex items-center justify-center gap-3 bg-rose-500/5 text-rose-500/50 border border-rose-500/10 p-4 rounded-2xl font-black uppercase text-[10px] hover:bg-rose-500 hover:text-white transition-all">
                                   <Trash2 size={16}/> Excluir Orçamento
                                </button>
                             </div>
                          </div>
                       </div>
                    </div>
                  )}
               </div>
             );
           })}
        </div>
      )}
    </div>
  );
};

export default QuotesView;

import React, { useState, useEffect } from 'react';
import { ShoppingCart, Plus, Minus, Trash2, Search, X, Loader2, Zap, Smartphone, User, Edit2, ChevronDown, ChevronUp, Calendar, CheckCircle, MessageCircle } from 'lucide-react';
import { Order, Product, Customer, OrderItem, UserProfile, Installment } from '../types';
import { dbService, Timestamp } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [guestData, setGuestData] = useState({ name: '', phone: '' });
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1' });
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);

  useEffect(() => {
    if (selectedCustomerId) {
      const c = customers.find(cust => cust.id === selectedCustomerId);
      if (c) setGuestData({ name: c.name, phone: c.phone || '' });
    } else {
      setGuestData({ name: '', phone: '' });
    }
  }, [selectedCustomerId, customers]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type as any }];
    });
  };

  const addManualToCart = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha dados do item.");
    setCart(prev => [...prev, {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: 'PRODUCT'
    }]);
    setManualItem({ name: '', price: '', qty: '1' });
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Carrinho vazio.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const installmentDetails: Installment[] = Array.from({ length: installments }).map((_, idx) => {
        const dueDate = new Date();
        dueDate.setMonth(dueDate.getMonth() + idx);
        return {
          id: `inst-${Date.now()}-${idx}`,
          value: total / installments,
          status: 'PENDING',
          dueDate: Timestamp.fromDate(dueDate)
        };
      });

      const orderData: any = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: 'PAID',
        paymentMethod,
        installments,
        installmentDetails,
        guestName: guestData.name.toUpperCase() || 'VENDA RÁPIDA',
        guestPhone: guestData.phone
      };

      await dbService.add('orders', userId, orderData);
      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
      setGuestData({ name: '', phone: '' });
      setInstallments(1);
    } catch (e) { alert('Falha ao processar.'); } finally { setIsProcessing(false); }
  };

  const sendInstallmentReminder = (order: Order, inst: Installment, index: number) => {
    const phone = order.guestPhone?.replace(/\D/g, '');
    if (!phone) return alert("Telefone não cadastrado para este cliente.");

    const dueDate = inst.dueDate?.toDate ? inst.dueDate.toDate().toLocaleDateString('pt-BR') : 'A combinar';
    const msg = encodeURIComponent(
      `Olá ${order.guestName}!\n\nLembrete de pagamento da *Parcela ${index + 1}* referente à sua compra no valor de *R$ ${inst.value.toFixed(2)}*.\n\n📅 Vencimento: ${dueDate}\n💳 Status: ${inst.status === 'PAID' ? 'PAGO' : 'PENDENTE'}\n\n_Enviado via ${profile.officeName}_`
    );
    window.open(`https://wa.me/55${phone}?text=${msg}`, '_blank');
  };

  const updateInstallment = async (order: Order, instId: string, updates: Partial<Installment>) => {
    const newDetails = order.installmentDetails?.map(inst => 
      inst.id === instId ? { ...inst, ...updates } : inst
    );
    const newTotal = newDetails?.reduce((s, i) => s + i.value, 0) || order.total;
    await dbService.update('orders', order.id, { installmentDetails: newDetails, total: newTotal });
  };

  const removeInstallment = async (order: Order, instId: string) => {
    if (!confirm("Excluir esta parcela permanentemente?")) return;
    const newDetails = order.installmentDetails?.filter(inst => inst.id !== instId);
    const newTotal = newDetails?.reduce((s, i) => s + i.value, 0) || 0;
    await dbService.update('orders', order.id, { installmentDetails: newDetails, total: newTotal });
  };

  const handleDeleteOrder = async (orderId: string) => {
    if (confirm("Deseja EXCLUIR DEFINITIVAMENTE esta venda e todos os seus registros?")) {
      try {
        await dbService.del('orders', orderId);
      } catch (e) {
        alert("Erro ao remover venda.");
      }
    }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20 px-2 lg:px-0">
      <div className="flex justify-between items-center">
        <h2 className="text-3xl lg:text-4xl font-black text-white italic tracking-tighter text-glow-cyan">Vendas PdV</h2>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-radiant px-6 py-3 rounded-xl flex items-center gap-2 text-[10px]"><Plus size={16}/> NOVA VENDA</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="nexus-card p-6 border-cyan-400/20 bg-cyan-400/5 box-glow-orange">
              <div className="flex gap-2">
                <input placeholder="Item..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 p-3 rounded-lg" />
                <input placeholder="R$" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-20 p-3 rounded-lg" />
                <button onClick={addManualToCart} className="bg-cyan-400 text-black px-4 rounded-lg font-black"><Plus/></button>
              </div>
            </div>
            <div className="bg-white/5 p-4 rounded-2xl border border-white/5 flex items-center gap-3">
              <Search className="text-cyan-400" size={18}/>
              <input placeholder="Filtrar catálogo..." className="bg-transparent flex-1 outline-none text-white font-bold text-sm" value={search} onChange={e => setSearch(e.target.value)} />
            </div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-3 max-h-[300px] overflow-y-auto pr-1">
              {products.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => addToCart(p)} className="nexus-card p-4 text-left hover:border-cyan-400/30 transition-all">
                   <p className="font-black text-white text-[10px] truncate uppercase">{p.name}</p>
                   <p className="text-cyan-400 font-black text-sm mt-1">R$ {p.price.toFixed(2)}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-6 h-fit border-orange-400/30">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-terminal font-black text-sm text-glow-orange uppercase">Checkout</h3>
              <button onClick={() => setIsCreating(false)}><X className="text-slate-500"/></button>
            </div>
            <div className="space-y-6">
              <div className="space-y-4 bg-black/30 p-4 rounded-2xl border border-white/5">
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full p-3 rounded-xl text-[10px] uppercase font-bold">
                  <option value="">-- CLIENTE AVULSO --</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
                <input placeholder="NOME DO CLIENTE" value={guestData.name} onChange={e => setGuestData({...guestData, name: e.target.value})} className="w-full p-3 rounded-xl text-[10px] uppercase font-bold" />
                <input placeholder="WHATSAPP" value={guestData.phone} onChange={e => setGuestData({...guestData, phone: e.target.value})} className="w-full p-3 rounded-xl text-[10px] font-bold" />
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest">Parcelas</label>
                <select value={installments} onChange={e => setInstallments(parseInt(e.target.value))} className="w-full p-4 rounded-xl text-xs">
                  {[1,2,3,4,5,6,10,12,24].map(n => <option key={n} value={n}>{n}x</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-2">
                {['PIX', 'CASH', 'CREDIT_CARD', 'DEFERRED'].map(m => (
                  <button key={m} onClick={() => setPaymentMethod(m as any)} className={`p-3 rounded-lg border text-[8px] font-black ${paymentMethod === m ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}>{m}</button>
                ))}
              </div>
              <div className="pt-6 border-t border-white/5">
                <div className="flex justify-between items-end mb-6">
                   <span className="text-slate-500 text-[10px] font-black uppercase">Total</span>
                   <span className="text-3xl font-black text-white italic text-glow-cyan">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || cart.length === 0} onClick={finalize} className="btn-radiant w-full py-5 rounded-xl font-black text-[12px] flex justify-center gap-2">
                  {isProcessing ? <Loader2 className="animate-spin" size={16}/> : <Zap size={16}/>} FINALIZAR VENDA
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
           {orders.map(o => {
             const isExpanded = expandedOrderId === o.id;
             return (
               <div key={o.id} className="nexus-card overflow-hidden border-white/5 group">
                  <div onClick={() => setExpandedOrderId(isExpanded ? null : o.id)} className="p-6 flex justify-between items-center cursor-pointer hover:bg-white/5 transition-colors">
                    <div className="flex items-center gap-6">
                      <div>
                        <p className="text-[8px] font-mono text-slate-500 uppercase tracking-widest">#{o.id.substring(0,6)} • {o.paymentMethod}</p>
                        <div className="flex items-center gap-4">
                          <p className="text-lg font-black text-white italic tracking-tight uppercase">{o.guestName || 'Venda Rápida'}</p>
                          <button 
                            onClick={(e) => { e.stopPropagation(); handleDeleteOrder(o.id); }}
                            className="p-2 text-slate-800 hover:text-rose-500 transition-all opacity-0 group-hover:opacity-100"
                            title="Excluir Venda"
                          >
                            <Trash2 size={16}/>
                          </button>
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-6">
                       <p className="text-2xl font-black text-cyan-400 italic text-glow-cyan">R$ {o.total.toFixed(2)}</p>
                       {isExpanded ? <ChevronUp className="text-slate-500"/> : <ChevronDown className="text-slate-500"/>}
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="p-8 bg-black/30 border-t border-white/5 animate-fade-in space-y-10">
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                          <div>
                             <h4 className="text-[10px] font-black text-cyan-400 uppercase tracking-widest mb-4 flex items-center gap-2"><User size={14}/> Cliente</h4>
                             <div className="bg-white/5 p-4 rounded-xl border border-white/10 mb-6">
                                <p className="text-white font-black uppercase text-sm">{o.guestName}</p>
                                <p className="text-[10px] text-slate-400 font-bold mt-1 flex items-center gap-2"><Smartphone size={10}/> {o.guestPhone || 'Sem telefone'}</p>
                             </div>

                             <h4 className="text-[10px] font-black text-cyan-400 uppercase tracking-widest mb-4 flex items-center gap-2"><ShoppingCart size={14}/> Itens</h4>
                             <div className="space-y-3">
                                {o.items.map((item, idx) => (
                                  <div key={idx} className="flex justify-between text-xs p-3 bg-white/5 rounded-xl border border-white/5">
                                     <span className="text-white font-bold uppercase">{item.quantity}x {item.nameAtTime}</span>
                                     <span className="text-slate-400 font-black">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</span>
                                  </div>
                                ))}
                             </div>
                          </div>

                          <div>
                             <h4 className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-6 flex items-center gap-2"><Calendar size={14}/> Cronograma de Parcelas</h4>
                             <div className="space-y-4">
                                {(o.installmentDetails || []).map((inst, idx) => (
                                  <div key={inst.id} className="flex flex-col gap-3 p-4 bg-white/5 rounded-2xl border border-white/5 transition-all hover:border-orange-500/30 group">
                                     <div className="flex justify-between items-center">
                                        <span className="text-[9px] font-black text-slate-500 uppercase">PARCELA {idx+1} • {inst.dueDate?.toDate ? inst.dueDate.toDate().toLocaleDateString('pt-BR') : 'Sem data'}</span>
                                        <div className="flex gap-2">
                                          <button onClick={() => sendInstallmentReminder(o, inst, idx)} className="flex items-center gap-2 bg-emerald-500/10 text-emerald-500 px-3 py-1 rounded-lg text-[8px] font-black uppercase hover:bg-emerald-500 hover:text-black transition-all">
                                             <MessageCircle size={12}/> Cobrar
                                          </button>
                                          <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase ${inst.status === 'PAID' ? 'bg-emerald-500 text-black' : 'bg-amber-500 text-black'}`}>
                                            {inst.status === 'PAID' ? 'PAGO' : 'PENDENTE'}
                                          </span>
                                        </div>
                                     </div>
                                     <div className="flex items-center gap-4">
                                        <div className="relative flex-1">
                                          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-500">R$</span>
                                          <input 
                                            type="number" 
                                            value={inst.value} 
                                            onChange={(e) => updateInstallment(o, inst.id, { value: parseFloat(e.target.value) })}
                                            className="w-full bg-black/40 border border-white/5 pl-8 pr-4 py-2 rounded-xl text-white font-black text-sm outline-none focus:border-orange-500"
                                          />
                                        </div>
                                        <div className="flex gap-2">
                                           <button onClick={() => updateInstallment(o, inst.id, { status: inst.status === 'PAID' ? 'PENDING' : 'PAID' })} className={`p-3 rounded-xl transition-all ${inst.status === 'PAID' ? 'bg-amber-500/10 text-amber-500' : 'bg-emerald-500/10 text-emerald-500'}`}>
                                              {inst.status === 'PAID' ? <X size={16}/> : <CheckCircle size={16}/>}
                                           </button>
                                           <button onClick={() => removeInstallment(o, inst.id)} className="p-3 bg-rose-500/10 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all">
                                              <Trash2 size={16}/>
                                           </button>
                                        </div>
                                     </div>
                                  </div>
                                ))}
                             </div>
                          </div>
                       </div>
                    </div>
                  )}
               </div>
             );
           })}
        </div>
      )}
    </div>
  );
};

