import React, { useState, useEffect } from 'react';
import { dbService, Timestamp } from '../services/firebase';
import { UserProfile } from '../types';
import { 
  Building2, Ban, Trash2, Search, DollarSign, Clock, ShieldAlert, Eraser, Loader2, Zap, CheckCircle
} from 'lucide-react';

const OfficeManagement: React.FC = () => {
  const [offices, setOffices] = useState<UserProfile[]>([]);
  const [search, setSearch] = useState('');
  const [isWiping, setIsWiping] = useState(false);

  useEffect(() => {
    const unsub = dbService.watchNetwork((data) => {
      const sorted = [...data].sort((a: any, b: any) => 
        (a.officeName || "").localeCompare(b.officeName || "")
      );
      setOffices(sorted as UserProfile[]);
    });
    return () => unsub();
  }, []);

  const handleWipeAllTrials = async () => {
    const trials = offices.filter(o => 
      o.subscriptionStatus === 'TRIAL' && 
      o.email !== "giufarlosdias@hotmail.com"
    );

    if (trials.length === 0) return;

    if (confirm(`NUCLEO DE SEGURANÇA: Deseja apagar DEFINITIVAMENTE todos os ${trials.length} terminais em TESTE agora?`)) {
      setIsWiping(true);
      try {
        await Promise.all(trials.map(office => dbService.del('users', office.uid)));
      } catch (e) {
        console.error("Erro na limpeza em massa", e);
      } finally {
        setIsWiping(false);
      }
    }
  };

  const handleConfirmPayment = async (uid: string) => {
    const nextExpiry = new Date();
    nextExpiry.setDate(nextExpiry.getDate() + 30);

    dbService.update('users', uid, { 
      subscriptionStatus: 'PAID',
      status: 'active',
      subscriptionExpiresAt: Timestamp.fromDate(nextExpiry)
    }).catch(() => alert("Erro ao sincronizar pagamento."));
  };

  const handleToggleBlock = async (uid: string, currentStatus: string) => {
    const nextStatus = currentStatus === 'active' ? 'blocked' : 'active';
    dbService.update('users', uid, { status: nextStatus });
  };

  const handleDelete = async (uid: string) => {
    if (confirm("EXCLUIR TERMINAL: Esta ação é definitiva e apagará todos os dados deste escritório. Confirmar?")) {
      dbService.del('users', uid).catch(() => alert("Falha ao remover terminal."));
    }
  };

  const filtered = offices.filter(o => 
    o.email?.toLowerCase().includes(search.toLowerCase()) || 
    o.officeName?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-12 animate-fade-in pb-20">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
          <h2 className="text-4xl lg:text-6xl font-black text-white italic tracking-tighter text-glow-cyan leading-none uppercase">Terminais de Rede</h2>
          <p className="text-slate-500 font-bold text-sm tracking-widest uppercase mt-4 italic opacity-70 flex items-center gap-3">
             <ShieldAlert size={18} className="text-cyan-400"/> Gestão Centralizada de Acessos Nexus
          </p>
        </div>

        <div className="flex flex-wrap gap-4 w-full lg:w-auto">
          <button 
            onClick={handleWipeAllTrials}
            disabled={isWiping}
            className="flex-1 lg:flex-none bg-rose-500/10 border border-rose-500/30 text-rose-500 px-8 py-5 rounded-[2rem] hover:bg-rose-500 hover:text-white transition-all font-black text-[10px] uppercase flex items-center justify-center gap-3 disabled:opacity-50 box-glow-rose"
          >
            {isWiping ? <Loader2 className="animate-spin" size={18}/> : <Eraser size={18}/>} 
            {isWiping ? 'EXECUTANDO LIMPEZA...' : 'LIMPAR TODOS OS TESTES'}
          </button>

          <div className="flex-1 lg:flex-none bg-[#1a0a2e] p-2 rounded-[2rem] flex items-center gap-4 border border-white/5 focus-within:border-cyan-400/50 transition-all shadow-inner">
            <Search className="ml-6 text-slate-500" size={20} />
            <input 
              placeholder="Localizar terminal operacional..." 
              className="bg-transparent border-0 outline-none p-4 text-white font-black w-full lg:w-72 placeholder:text-slate-800 text-lg italic"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
        </div>
      </div>

      <div className="space-y-6">
        {filtered.map(office => (
          <div key={office.uid} className="nexus-card p-10 border border-white/5 flex flex-col xl:flex-row items-center justify-between gap-10 hover:border-cyan-400/40 transition-all box-glow-cyan animate-fade-in">
             <div className="flex items-center gap-10 w-full xl:w-auto">
               <div className={`w-24 h-24 rounded-[2rem] flex items-center justify-center border transition-all ${office.subscriptionStatus === 'PAID' ? 'bg-emerald-500/10 border-emerald-500/40 text-emerald-400 shadow-[0_0_30px_rgba(16,185,129,0.3)]' : office.subscriptionStatus === 'EXPIRED' ? 'bg-rose-500/10 border-rose-500/40 text-rose-500' : 'bg-amber-500/10 border-amber-500/40 text-amber-400'}`}>
                 <Building2 size={48} />
               </div>
               <div>
                 <div className="flex items-center gap-6 flex-wrap">
                   <h4 className="text-3xl font-black text-white italic tracking-tighter uppercase">{office.officeName}</h4>
                   <span className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg ${office.subscriptionStatus === 'PAID' ? 'bg-emerald-500 text-black' : office.subscriptionStatus === 'EXPIRED' ? 'bg-rose-600 text-white animate-pulse' : 'bg-amber-500 text-black'}`}>
                     {office.subscriptionStatus === 'PAID' ? 'ASSINATURA ATIVA' : office.subscriptionStatus === 'EXPIRED' ? 'EXPIRADO' : 'PERÍODO TRIAL'}
                   </span>
                   {office.status === 'blocked' && (
                     <span className="bg-white text-rose-600 border-2 border-rose-600 px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">BLOQUEADO</span>
                   )}
                 </div>
                 <div className="flex items-center gap-6 mt-4">
                   <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">{office.email}</p>
                   <span className="w-1.5 h-1.5 bg-slate-800 rounded-full"></span>
                   <p className={`text-xs font-black uppercase tracking-widest flex items-center gap-2 ${office.subscriptionStatus === 'EXPIRED' ? 'text-rose-500' : 'text-cyan-400'}`}>
                     <Clock size={16} /> EXPIRAÇÃO EM: {office.subscriptionExpiresAt?.toDate().toLocaleDateString('pt-BR')}
                   </p>
                 </div>
               </div>
             </div>

             <div className="flex flex-wrap items-center gap-4 w-full xl:w-auto justify-end">
                <button 
                  type="button"
                  onClick={() => handleConfirmPayment(office.uid)}
                  className="flex-1 sm:flex-none flex items-center justify-center gap-4 px-10 py-6 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all bg-emerald-500 text-black hover:bg-emerald-400 shadow-xl shadow-emerald-500/20 active:scale-95"
                >
                  <CheckCircle size={20}/> RENOVAR (+30 DIAS)
                </button>

                <button 
                  type="button"
                  onClick={() => handleToggleBlock(office.uid, office.status)}
                  className={`flex-1 sm:flex-none flex items-center justify-center gap-4 px-10 py-6 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all border-2 active:scale-95 ${office.status === 'active' ? 'bg-white/5 text-amber-500 border-amber-500 hover:bg-amber-500 hover:text-black' : 'bg-cyan-500 text-black border-cyan-500 hover:bg-cyan-400'}`}
                >
                  <Ban size={20}/> {office.status === 'active' ? 'BLOQUEAR TERMINAL' : 'DESBLOQUEAR'}
                </button>

                <button 
                  type="button"
                  disabled={office.email === "giufarlosdias@hotmail.com"}
                  onClick={() => handleDelete(office.uid)}
                  className="p-6 bg-rose-600/10 text-rose-600 border-2 border-rose-600/20 rounded-2xl hover:bg-rose-600 hover:text-white transition-all active:scale-95 disabled:opacity-0"
                  title="Excluir Definitivamente"
                >
                  <Trash2 size={24}/>
                </button>
             </div>
          </div>
        ))}

        {filtered.length === 0 && (
          <div className="py-40 text-center flex flex-col items-center">
            <div className="w-32 h-32 bg-white/5 rounded-full flex items-center justify-center border-2 border-dashed border-white/10 mb-10">
               <ShieldAlert size={64} className="text-slate-800" />
            </div>
            <p className="text-slate-700 font-black uppercase tracking-[0.8em] italic text-2xl">Rede Vazia.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default OfficeManagement;

