      <div className="space-y-6">
        {filtered.map(office => (
          <div key={office.uid} className="nexus-card p-10 border border-white/5 flex flex-col xl:flex-row items-center justify-between gap-10 hover:border-cyan-400/40 transition-all box-glow-cyan animate-fade-in">
             <div className="flex items-center gap-10 w-full xl:w-auto">
