import React, { useState, useEffect } from 'react';
import { ShoppingCart, Plus, Minus, Trash2, Search, X, Loader2, Zap, Smartphone, User, Edit2, ChevronDown, ChevronUp, Calendar, CheckCircle, MessageCircle } from 'lucide-react';
import { Order, Product, Customer, OrderItem, UserProfile, Installment } from '../types';
import { dbService, Timestamp } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [guestData, setGuestData] = useState({ name: '', phone: '' });
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1' });
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);

  useEffect(() => {
    if (selectedCustomerId) {
      const c = customers.find(cust => cust.id === selectedCustomerId);
      if (c) setGuestData({ name: c.name, phone: c.phone || '' });
    } else {
      setGuestData({ name: '', phone: '' });
    }
  }, [selectedCustomerId, customers]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type as any }];
    });
  };

  const addManualToCart = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha dados do item.");
    setCart(prev => [...prev, {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: 'PRODUCT'
    }]);
    setManualItem({ name: '', price: '', qty: '1' });
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Carrinho vazio.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const installmentDetails: Installment[] = Array.from({ length: installments }).map((_, idx) => {
        const dueDate = new Date();
        dueDate.setMonth(dueDate.getMonth() + idx);
        return {
          id: `inst-${Date.now()}-${idx}`,
          value: total / installments,
          status: 'PENDING',
          dueDate: Timestamp.fromDate(dueDate)
        };
      });

      const orderData: any = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: 'PAID',
        paymentMethod,
        installments,
        installmentDetails,
        guestName: guestData.name.toUpperCase() || 'VENDA RÁPIDA',
        guestPhone: guestData.phone
      };

      await dbService.add('orders', userId, orderData);
      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
      setGuestData({ name: '', phone: '' });
      setInstallments(1);
    } catch (e) { alert('Falha ao processar.'); } finally { setIsProcessing(false); }
  };

  const sendInstallmentReminder = (order: Order, inst: Installment, index: number) => {
    const phone = order.guestPhone?.replace(/\D/g, '');
    if (!phone) return alert("Telefone não cadastrado para este cliente.");

    const dueDate = inst.dueDate?.toDate ? inst.dueDate.toDate().toLocaleDateString('pt-BR') : 'A combinar';
    const msg = encodeURIComponent(
      `Olá ${order.guestName}!\n\nLembrete de pagamento da *Parcela ${index + 1}* referente à sua compra no valor de *R$ ${inst.value.toFixed(2)}*.\n\n📅 Vencimento: ${dueDate}\n💳 Status: ${inst.status === 'PAID' ? 'PAGO' : 'PENDENTE'}\n\n_Enviado via ${profile.officeName}_`
    );
    window.open(`https://wa.me/55${phone}?text=${msg}`, '_blank');
  };

  const updateInstallment = async (order: Order, instId: string, updates: Partial<Installment>) => {
    const newDetails = order.installmentDetails?.map(inst => 
      inst.id === instId ? { ...inst, ...updates } : inst
    );
    const newTotal = newDetails?.reduce((s, i) => s + i.value, 0) || order.total;
    await dbService.update('orders', order.id, { installmentDetails: newDetails, total: newTotal });
  };

  const removeInstallment = async (order: Order, instId: string) => {
    const newDetails = order.installmentDetails?.filter(inst => inst.id !== instId);
    const newTotal = newDetails?.reduce((s, i) => s + i.value, 0) || 0;
    await dbService.update('orders', order.id, { installmentDetails: newDetails, total: newTotal });
  };

  const handleDeleteOrder = async (orderId: string) => {
    try {
      await dbService.del('orders', orderId);
    } catch (e) {
      alert("Erro ao remover venda.");
    }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20 px-2 lg:px-0">
      <div className="flex justify-between items-center">
        <h2 className="text-3xl lg:text-4xl font-black text-white italic tracking-tighter text-glow-cyan">Vendas PdV</h2>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-radiant px-6 py-3 rounded-xl flex items-center gap-2 text-[10px]"><Plus size={16}/> NOVA VENDA</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="nexus-card p-6 border-cyan-400/20 bg-cyan-400/5 box-glow-orange">
              <div className="flex gap-2">
                <input placeholder="Item..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 p-3 rounded-lg bg-black/40 border border-white/10 text-white" />
                <input placeholder="R$" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-20 p-3 rounded-lg bg-black/40 border border-white/10 text-white" />
                <button onClick={addManualToCart} className="bg-cyan-400 text-black px-4 rounded-lg font-black"><Plus/></button>
              </div>
            </div>
            <div className="bg-white/5 p-4 rounded-2xl border border-white/5 flex items-center gap-3">
              <Search className="text-cyan-400" size={18}/>
              <input placeholder="Filtrar catálogo..." className="bg-transparent flex-1 outline-none text-white font-bold text-sm" value={search} onChange={e => setSearch(e.target.value)} />
            </div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-3 max-h-[300px] overflow-y-auto pr-1">
              {products.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => addToCart(p)} className="nexus-card p-4 text-left hover:border-cyan-400/30 transition-all">
                   <p className="font-black text-white text-[10px] truncate uppercase">{p.name}</p>
                   <p className="text-cyan-400 font-black text-sm mt-1">R$ {p.price.toFixed(2)}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-6 h-fit border-orange-400/30">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-terminal font-black text-sm text-glow-orange uppercase">Checkout</h3>
              <button onClick={() => setIsCreating(false)}><X className="text-slate-500"/></button>
            </div>
            <div className="space-y-6">
              <div className="space-y-4 bg-black/30 p-4 rounded-2xl border border-white/5">
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full p-3 rounded-xl text-[10px] uppercase font-bold bg-black border border-white/10 text-white">
                  <option value="">-- CLIENTE AVULSO --</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
                <input placeholder="NOME DO CLIENTE" value={guestData.name} onChange={e => setGuestData({...guestData, name: e.target.value})} className="w-full p-3 rounded-xl text-[10px] uppercase font-bold bg-black border border-white/10 text-white" />
                <input placeholder="WHATSAPP" value={guestData.phone} onChange={e => setGuestData({...guestData, phone: e.target.value})} className="w-full p-3 rounded-xl text-[10px] font-bold bg-black border border-white/10 text-white" />
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest">Parcelas</label>
                <select value={installments} onChange={e => setInstallments(parseInt(e.target.value))} className="w-full p-4 rounded-xl text-xs bg-black border border-white/10 text-white">
                  {[1,2,3,4,5,6,10,12,24].map(n => <option key={n} value={n}>{n}x</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-2">
                {['PIX', 'CASH', 'CREDIT_CARD', 'DEFERRED'].map(m => (
                  <button key={m} onClick={() => setPaymentMethod(m as any)} className={`p-3 rounded-lg border text-[8px] font-black transition-all ${paymentMethod === m ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}>{m}</button>
                ))}
              </div>
              <div className="pt-6 border-t border-white/5">
                <div className="flex justify-between items-end mb-6">
                   <span className="text-slate-500 text-[10px] font-black uppercase">Total</span>
                   <span className="text-3xl font-black text-white italic text-glow-cyan">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || cart.length === 0} onClick={finalize} className="btn-radiant w-full py-5 rounded-xl font-black text-[12px] flex justify-center gap-2">
                  {isProcessing ? <Loader2 className="animate-spin" size={16}/> : <Zap size={16}/>} FINALIZAR VENDA
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
           {orders.map(o => {
             const isExpanded = expandedOrderId === o.id;
             return (
               <div key={o.id} className="nexus-card overflow-hidden border-white/5 group transition-all">
                  <div onClick={() => setExpandedOrderId(isExpanded ? null : o.id)} className="p-6 flex justify-between items-center cursor-pointer hover:bg-white/5 transition-colors">
                    <div className="flex items-center gap-6">
                      <div>
                        <p className="text-[8px] font-mono text-slate-500 uppercase tracking-widest">#{o.id.substring(0,6)} • {o.paymentMethod}</p>
                        <div className="flex items-center gap-4">
                          <p className="text-lg font-black text-white italic tracking-tight uppercase">{o.guestName || 'Venda Rápida'}</p>
                          <button 
                            onClick={(e) => { e.stopPropagation(); handleDeleteOrder(o.id); }}
                            className="p-2.5 bg-rose-600/10 text-rose-500 border border-rose-500/20 rounded-xl hover:bg-rose-600 hover:text-white transition-all box-glow-rose"
                            title="Excluir Venda Imediatamente"
                          >
                            <Trash2 size={16}/>
                          </button>
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-6">
                       <p className="text-2xl font-black text-cyan-400 italic text-glow-cyan">R$ {o.total.toFixed(2)}</p>
                       {isExpanded ? <ChevronUp className="text-slate-500"/> : <ChevronDown className="text-slate-500"/>}
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="p-8 bg-black/30 border-t border-white/5 animate-fade-in space-y-10">
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                          <div>
                             <h4 className="text-[10px] font-black text-cyan-400 uppercase tracking-widest mb-4 flex items-center gap-2"><User size={14}/> Cliente</h4>
                             <div className="bg-white/5 p-4 rounded-xl border border-white/10 mb-6">
                                <p className="text-white font-black uppercase text-sm">{o.guestName}</p>
                                <p className="text-[10px] text-slate-400 font-bold mt-1 flex items-center gap-2"><Smartphone size={10}/> {o.guestPhone || 'Sem telefone'}</p>
                             </div>

                             <h4 className="text-[10px] font-black text-cyan-400 uppercase tracking-widest mb-4 flex items-center gap-2"><ShoppingCart size={14}/> Itens</h4>
                             <div className="space-y-3">
                                {o.items.map((item, idx) => (
                                  <div key={idx} className="flex justify-between text-xs p-3 bg-white/5 rounded-xl border border-white/5">
                                     <span className="text-white font-bold uppercase">{item.quantity}x {item.nameAtTime}</span>
                                     <span className="text-slate-400 font-black">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</span>
                                  </div>
                                ))}
                             </div>
                          </div>

                          <div>
                             <h4 className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-6 flex items-center gap-2"><Calendar size={14}/> Cronograma de Parcelas</h4>
                             <div className="space-y-4">
                                {(o.installmentDetails || []).map((inst, idx) => (
                                  <div key={inst.id} className="flex flex-col gap-3 p-4 bg-white/5 rounded-2xl border border-white/5 transition-all hover:border-orange-500/30 group">
                                     <div className="flex justify-between items-center">
                                        <span className="text-[9px] font-black text-slate-500 uppercase">PARCELA {idx+1} • {inst.dueDate?.toDate ? inst.dueDate.toDate().toLocaleDateString('pt-BR') : 'Sem data'}</span>
                                        <div className="flex gap-2">
                                          <button onClick={() => sendInstallmentReminder(o, inst, idx)} className="flex items-center gap-2 bg-emerald-500/10 text-emerald-500 px-3 py-1 rounded-lg text-[8px] font-black uppercase hover:bg-emerald-500 hover:text-black transition-all">
                                             <MessageCircle size={12}/> Cobrar
                                          </button>
                                          <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase ${inst.status === 'PAID' ? 'bg-emerald-500 text-black' : 'bg-amber-500 text-black'}`}>
                                            {inst.status === 'PAID' ? 'PAGO' : 'PENDENTE'}
                                          </span>
                                        </div>
                                     </div>
                                     <div className="flex items-center gap-4">
                                        <div className="relative flex-1">
                                          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-500">R$</span>
                                          <input 
                                            type="number" 
                                            value={inst.value} 
                                            onChange={(e) => updateInstallment(o, inst.id, { value: parseFloat(e.target.value) })}
                                            className="w-full bg-black/40 border border-white/5 pl-8 pr-4 py-2 rounded-xl text-white font-black text-sm outline-none focus:border-orange-500"
                                          />
                                        </div>
                                        <div className="flex gap-2">
                                           <button onClick={() => updateInstallment(o, inst.id, { status: inst.status === 'PAID' ? 'PENDING' : 'PAID' })} className={`p-3 rounded-xl transition-all ${inst.status === 'PAID' ? 'bg-amber-500/10 text-amber-500' : 'bg-emerald-500/10 text-emerald-500'}`}>
                                              {inst.status === 'PAID' ? <X size={16}/> : <CheckCircle size={16}/>}
                                           </button>
                                           <button onClick={() => removeInstallment(o, inst.id)} className="p-3 bg-rose-500/10 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all">
                                              <Trash2 size={16}/>
                                           </button>
                                        </div>
                                     </div>
                                  </div>
                                ))}
                             </div>
                          </div>
                       </div>
                    </div>
                  )}
               </div>
             );
           })}
        </div>
      )}
    </div>
  );
};

export default OrdersView;

import React, { useState } from 'react';
import { Plus, WalletMinimal, Trash2, X, Loader2, Zap, MessageCircle, Calendar } from 'lucide-react';
import { Expense, UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface ExpensesViewProps {
  expenses: Expense[];
  userId: string;
  profile: UserProfile;
}

const ExpensesView: React.FC<ExpensesViewProps> = ({ expenses, userId, profile }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({ description: '', amount: '', category: 'Operacional' });

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await dbService.add('expenses', userId, {
        description: formData.description,
        amount: parseFloat(formData.amount),
        category: formData.category
      });
      setIsModalOpen(false);
      setFormData({ description: '', amount: '', category: 'Operacional' });
    } catch (err) { alert("Erro ao salvar."); } finally { setIsSaving(false); }
  };

  const handleDelete = (id: string) => {
    dbService.del('expenses', id);
  };

  const sendWeeklyReport = () => {
    const lastWeek = new Date();
    lastWeek.setDate(lastWeek.getDate() - 7);

    const recentExpenses = expenses.filter(e => {
        const date = e.createdAt?.toDate ? e.createdAt.toDate() : new Date();
        return date >= lastWeek;
    });

    if (recentExpenses.length === 0) return alert("Nenhum custo registrado nos últimos 7 dias para compor o relatório.");

    const total = recentExpenses.reduce((s, e) => s + e.amount, 0);

    let msg = `*📊 RELATÓRIO DE SAÍDAS NEXUS*\n`;
    msg += `*Terminal:* ${profile.officeName}\n`;
    msg += `*Data Emissão:* ${new Date().toLocaleDateString('pt-BR')}\n`;
    msg += `*Período:* Últimos 7 dias operacionais\n`;
    msg += `----------------------------------\n`;

    recentExpenses.forEach(e => {
        const d = e.createdAt?.toDate ? e.createdAt.toDate().toLocaleDateString('pt-BR') : '--/--';
        msg += `• [${d}] ${e.description.toUpperCase()} - R$ ${e.amount.toFixed(2)} (${e.category})\n`;
    });

    msg += `----------------------------------\n`;
    msg += `*DRENAGEM TOTAL: R$ ${total.toFixed(2)}*\n\n`;
    msg += `_Este relatório foi sintetizado instantaneamente pelo núcleo Radiant OS._`;

    const phone = profile.phone?.replace(/\D/g, '');
    if (!phone) return alert("Por favor, cadastre seu WhatsApp nas Configurações para receber o relatório.");

    window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-12 animate-fade-in pb-20 px-2 lg:px-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
        <div>
          <h2 className="text-4xl lg:text-5xl font-black text-white tracking-tighter italic text-glow-cyan leading-none uppercase">Fluxos de Saída</h2>
          <p className="text-slate-500 font-bold mt-4 text-xs lg:text-xl tracking-wide uppercase opacity-70">Monitoramento responsivo de custos.</p>
        </div>
        <div className="flex flex-col sm:flex-row gap-4">
          <button onClick={sendWeeklyReport} className="bg-emerald-500/10 border border-emerald-500/30 text-emerald-500 px-6 py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-emerald-500 hover:text-black transition-all text-[10px] uppercase tracking-widest box-glow-cyan">
            <MessageCircle size={18} /> Relatório On-the-Fly
          </button>
          <button onClick={() => setIsModalOpen(true)} className="bg-rose-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 shadow-[0_0_30px_rgba(244,63,94,0.3)] hover:bg-rose-400 transition-all active:scale-95 text-[10px] uppercase tracking-widest box-glow-rose">
            <Plus size={20} /> Registrar Custo
          </button>
        </div>
      </div>

      <div className="hidden lg:block nexus-card overflow-hidden shadow-2xl border-white/5">
        <table className="w-full text-left min-w-[800px]">
          <thead>
            <tr className="bg-white/5">
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Descrição da Operação</th>
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Classificação</th>
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Drenagem de Crédito</th>
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60 text-right">Ação</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {expenses.map(exp => (
              <tr key={exp.id} className="hover:bg-white/5 transition-all group">
                <td className="px-10 py-10 font-black text-white text-2xl italic tracking-tighter uppercase">{exp.description}</td>
                <td className="px-10 py-10">
                  <span className="text-[10px] font-black px-5 py-2.5 rounded-2xl bg-white/5 text-slate-400 border border-white/10 uppercase tracking-[0.2em]">{exp.category}</span>
                </td>
                <td className="px-10 py-10 font-black text-rose-500 text-3xl tracking-tighter italic">R$ {exp.amount.toFixed(2)}</td>
                <td className="px-10 py-10 text-right">
                  <button onClick={() => handleDelete(exp.id)} className="p-4 bg-rose-600/10 text-rose-600 border border-rose-600/20 rounded-2xl hover:bg-rose-600 hover:text-white transition-all box-glow-rose" title="Excluir Imediatamente"><Trash2 size={24} /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="lg:hidden space-y-4">
        {expenses.map(exp => (
           <div key={exp.id} className="nexus-card p-6 border-white/5 space-y-4 group">
              <div className="flex justify-between items-start">
                 <div>
                    <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest mb-1">{exp.category}</p>
                    <h4 className="text-xl font-black text-white italic uppercase">{exp.description}</h4>
                 </div>
                 <button onClick={() => handleDelete(exp.id)} className="p-3 bg-rose-600/10 text-rose-600 border border-rose-600/20 rounded-xl hover:bg-rose-600 hover:text-white transition-all box-glow-rose">
                    <Trash2 size={18}/>
                 </button>
              </div>
              <div className="flex justify-between items-center pt-4 border-t border-white/5">
                 <p className="text-[10px] font-bold text-slate-600 uppercase flex items-center gap-2">
                    <Calendar size={12}/> {exp.createdAt?.toDate ? exp.createdAt.toDate().toLocaleDateString('pt-BR') : '--/--'}
                 </p>
                 <p className="text-2xl font-black text-rose-500 italic tracking-tighter">R$ {exp.amount.toFixed(2)}</p>
              </div>
           </div>
        ))}
      </div>

      {expenses.length === 0 && (
         <div className="py-40 text-center flex flex-col items-center">
            <div className="w-28 h-28 bg-white/5 rounded-[3rem] border-2 border-dashed border-white/10 flex items-center justify-center text-slate-700 mb-10">
              <WalletMinimal size={48} />
            </div>
            <p className="text-slate-500 font-black text-xl uppercase tracking-widest opacity-40 italic">Nenhuma saída detectada.</p>
         </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl">
          <div className="nexus-card w-full max-w-xl p-8 lg:p-12 animate-fade-in border-rose-500/40">
            <div className="flex justify-between items-center mb-12">
              <h3 className="text-2xl lg:text-3xl font-black text-white italic text-rose-500 uppercase">Novo Registro de Custo</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-12 h-12 flex items-center justify-center bg-white/5 rounded-2xl text-slate-400 hover:text-rose-500 transition-colors"><X size={32} /></button>
            </div>
            <form onSubmit={handleSave} className="space-y-6">
              <input required value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2rem] text-white font-bold placeholder:text-slate-700 outline-none focus:border-rose-500 transition-all text-xl" placeholder="Especificação do Gasto" />
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-rose-500 uppercase tracking-widest ml-2">Créditos R$</label>
                  <input required type="number" step="0.01" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2rem] text-white font-bold outline-none focus:border-rose-500 transition-all text-xl" />
                </div>
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-rose-500 uppercase tracking-widest ml-2">Protocolo</label>
                  <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2rem] text-white font-black italic outline-none focus:border-rose-500 transition-all text-lg appearance-none">
                    <option className="bg-[#0c0628]">OPERACIONAL</option>
                    <option className="bg-[#0c0628]">MANUTENÇÃO</option>
                    <option className="bg-[#0c0628]">MARKETING</option>
                    <option className="bg-[#0c0628]">INFRAESTRUTURA</option>
                    <option className="bg-[#0c0628]">OUTROS</option>
                  </select>
                </div>
              </div>
              <button disabled={isSaving} type="submit" className="w-full bg-rose-500 text-white py-6 lg:py-8 rounded-[2rem] lg:rounded-[2.5rem] font-black text-lg lg:text-xl shadow-[0_0_40px_rgba(244,63,94,0.4)] hover:bg-rose-400 transition-all mt-8 flex items-center justify-center gap-4 box-glow-rose">
                {isSaving ? <Loader2 className="animate-spin" size={28} /> : <Zap size={28} className="fill-current" />}
                CONFIRMAR DRENAGEM
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ExpensesView;

