export interface Quote {
  id: string;
  userId: string;
  customerId: string;
  customerName: string;
  items: OrderItem[];
  total: number;
  status: 'DRAFT' | 'SENT' | 'APPROVED' | 'REJECTED';
  validUntil: string;
  notes?: string;
  createdAt: any;
}

export interface Product {
  id: string;
  userId: string;
  name: string;
  description?: string;
  imageUrl?: string;
  price: number;
  stock: number;
  type: 'PRODUCT' | 'SERVICE';
  createdAt?: any;
}

export interface Customer {
  id: string;
  userId: string;
  name: string;
  email?: string;
  phone?: string;
  address?: string;
}

export interface OrderItem {
  productId: string;
  quantity: number;
  priceAtTime: number;
  nameAtTime: string;
  type: 'PRODUCT' | 'SERVICE' | 'LABOR';
}

export interface Installment {
  id: string;
  value: number;
  status: 'PENDING' | 'PAID';
  dueDate: any;
}

export interface Order {
  id: string;
  userId: string;
  customerId: string;
  items: OrderItem[];
  total: number;
  status: 'PAID' | 'PENDING' | 'QUOTE';
  paymentMethod: 'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED';
  installments?: number;
  installmentDetails?: Installment[];
  guestName?: string;
  guestPhone?: string;
  createdAt: any;
}

export interface Expense {
  id: string;
  userId: string;
  description: string;
  amount: number;
  category: string;
  createdAt: any;
}

export interface ServiceOrder {
  id: string;
  userId: string;
  customerId: string;
  customerName: string;
  equipment: string;
  description: string;
  status: 'OPEN' | 'IN_PROGRESS' | 'DONE' | 'CANCELLED';
