export type ViewState = 
  | 'DASHBOARD' | 'OFFICES' | 'STOCK' | 'SALES' 
  | 'SERVICE_ORDERS' | 'CUSTOMERS' | 'QUOTES' 
  | 'FINANCIAL' | 'AGENDA' | 'REFERRALS' | 'PROFILE';

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { ViewState, UserProfile, Order, Product, Customer, Expense, Quote } from './types';
import { Timestamp } from 'firebase/firestore';
import { 
  LayoutDashboard, Users, LogOut, Zap, Building2, Grid3X3, 
  ShoppingCart, Lock, FileText, Calendar, Package, Wrench, Wallet, UserCircle, Gift
} from 'lucide-react';

import LoginView from './views/LoginView';
import MasterDashboard from './views/MasterDashboard';
import OfficeManagement from './views/OfficeManagement';
import NexusHub from './views/NexusHub';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import SettingsView from './views/SettingsView';
import ReferralView from './views/ReferralView';
import QuotesView from './views/QuotesView';
import CalendarView from './views/CalendarView';
import ServiceOrdersView from './views/ServiceOrdersView';
import AdminDashboard from './views/AdminDashboard';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [loading, setLoading] = useState(true);

  const [orders, setOrders] = useState<Order[]>([]);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');

        const isMaster = u.email === "giufarlosdias@hotmail.com";
        if (isMaster) {
           const infiniteDate = new Date(2099, 11, 31);
           await dbService.update('users', u.uid, { 
             role: 'super-admin',
             subscriptionStatus: 'PAID',
             status: 'active',
             subscriptionExpiresAt: Timestamp.fromDate(infiniteDate)
           });
           p.role = 'super-admin';
           p.subscriptionStatus = 'PAID';
           p.status = 'active';
        }

        if (p.status === 'blocked') { alert("Terminal Bloqueado."); await signOut(auth); return; }

        setProfile(p as UserProfile);
        setUser(u);
        setView('DASHBOARD');

        if (p.role === 'admin' || p.role === 'super-admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('quotes', u.uid, (data) => setQuotes(data as Quote[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null); setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-black">
      <div className="relative">
        <div className="w-16 h-16 border-2 border-orange-500/20 rounded-full"></div>
        <div className="absolute top-0 left-0 w-16 h-16 border-t-2 border-orange-500 rounded-full animate-spin"></div>
        <Zap className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-orange-500 animate-pulse" size={24}/>
      </div>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';
  const salesCount = orders.filter(o => o.status === 'PAID').length;
  const needsPayment = !isSuper && salesCount >= 3 && profile?.subscriptionStatus !== 'PAID';

  const NavContent = () => (
    <div className="flex flex-row lg:flex-col items-center justify-around lg:justify-start w-full gap-2 px-4 lg:px-0">
      <button onClick={()=>setView('DASHBOARD')} title="Início" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full ${view==='DASHBOARD'?'active':''}`}><Grid3X3 size={24}/></button>
      <button onClick={()=>setView('SALES')} title="Vendas" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full ${view==='SALES'?'active':''}`}><ShoppingCart size={24}/></button>
      <button onClick={()=>setView('FINANCIAL')} title="Financeiro" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full ${view==='FINANCIAL'?'active':''}`}><Wallet size={24}/></button>
      {isSuper && <button onClick={()=>setView('OFFICES')} title="Escritórios" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full ${view==='OFFICES'?'active':''}`}><Building2 size={24}/></button>}
      <button onClick={()=>setView('PROFILE')} title="Perfil" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full ${view==='PROFILE'?'active':''}`}><UserCircle size={24}/></button>
      <button onClick={() => signOut(auth)} className="nav-btn p-3 lg:p-4 flex-1 lg:w-full text-red-500"><LogOut size={24}/></button>
    </div>
  );

  const renderView = () => {
    if (needsPayment && view !== 'PROFILE') {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-8 p-6 text-center animate-fade-in">
          <div className="w-20 h-20 bg-orange-600 rounded-3xl flex items-center justify-center shadow-lg"><Lock size={32} className="text-white"/></div>
          <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">Terminal em Espera</h2>
          <p className="text-slate-500 text-[11px] uppercase font-black tracking-widest max-w-xs">Identificamos atividade pendente de regularização.</p>
          <button onClick={() => setView('PROFILE')} className="text-orange-500 font-black uppercase text-[10px] tracking-[0.5em] mt-10">Regularizar no Perfil</button>
        </div>
      );
    }

    switch(view) {
      case 'DASHBOARD': 
        return <NexusHub setView={setView} profile={profile!} orders={orders} expenses={expenses} />;
      case 'OFFICES': 
        return isSuper ? <OfficeManagement superAdminProfile={profile!} /> : <NexusHub setView={setView} profile={profile!} orders={orders} expenses={expenses} />;
      case 'STOCK': return <ProductsView userId={user.uid} />;
      case 'SALES': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'SERVICE_ORDERS': return <ServiceOrdersView userId={user.uid} customers={customers} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} orders={orders} userId={user.uid} />;
      case 'QUOTES': return <QuotesView quotes={quotes} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'FINANCIAL': return <ExpensesView expenses={expenses} userId={user.uid} profile={profile!} />;
      case 'AGENDA': return <CalendarView profile={profile!} userId={user.uid} />;
      case 'REFERRALS': return <ReferralView profile={profile!} />;
      case 'PROFILE': return <SettingsView profile={profile!} />;
      default: return <NexusHub setView={setView} profile={profile!} orders={orders} expenses={expenses} />;
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen bg-black overflow-hidden selection:bg-orange-500/30">
      <div className="absolute inset-0 grid-bg opacity-30 pointer-events-none"></div>

      <aside className="hidden lg:flex w-20 border-r border-white/5 bg-black flex-col p-4 z-20 items-center justify-between">
        <div className="w-10 h-10 bg-orange-500 rounded-xl flex items-center justify-center shadow-lg mb-8">
           <Zap size={20} className="text-black fill-current"/>
        </div>
        <NavContent />
        <div className="h-10"></div>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-10 relative z-10 custom-scrollbar pb-24 lg:pb-10">
        <div className="max-w-7xl mx-auto">
          {renderView()}
        </div>
      </main>

      <nav className="lg:hidden fixed bottom-0 left-0 right-0 h-16 bg-black border-t border-white/10 flex items-center z-50 px-2">
        <NavContent />
      </nav>
    </div>
  );
};

export default App;

