import React, { useState, useEffect } from 'react';
import { dbService } from '../services/firebase';
import { Customer, ServiceOrder } from '../types';
import { Plus, Search, Trash2, Wrench, Clock, CheckCircle, X, Loader2, User } from 'lucide-react';

interface ServiceOrdersViewProps {
  userId: string;
  customers: Customer[];
}

const ServiceOrdersView: React.FC<ServiceOrdersViewProps> = ({ userId, customers }) => {
  const [orders, setOrders] = useState<ServiceOrder[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [search, setSearch] = useState('');

  const [formData, setFormData] = useState({
    customerId: '',
    equipment: '',
    description: '',
    cost: '',
    status: 'OPEN' as any
  });

  useEffect(() => {
    return dbService.sync('service_orders', userId, (data) => setOrders(data as ServiceOrder[]));
  }, [userId]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    const customer = customers.find(c => c.id === formData.customerId);
    try {
      await dbService.add('service_orders', userId, {
        ...formData,
        customerName: customer?.name || 'Cliente Avulso',
        cost: parseFloat(formData.cost || '0')
      });
      setIsModalOpen(false);
      setFormData({ customerId: '', equipment: '', description: '', cost: '', status: 'OPEN' });
    } catch (err) { alert("Erro ao salvar O.S."); } finally { setIsSaving(false); }
  };

  const updateStatus = (id: string, nextStatus: any) => {
    dbService.update('service_orders', id, { status: nextStatus });
  };

  const filtered = orders.filter(o => o.customerName.toLowerCase().includes(search.toLowerCase()) || o.equipment.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-10 animate-fade-in">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-4xl font-black text-white italic tracking-tighter text-glow uppercase">Ordem de Serviço</h2>
          <p className="text-slate-500 font-bold text-xs tracking-widest uppercase mt-2 opacity-70">Controle Técnico de Manutenção.</p>
        </div>
        <button onClick={() => setIsModalOpen(true)} className="btn-orange px-6 py-4 rounded-2xl flex items-center gap-2"><Plus size={18}/> NOVA O.S.</button>
      </div>

      <div className="bg-white/5 p-4 rounded-2xl border border-white/10 flex items-center gap-4">
        <Search className="text-orange-500" size={20} />
        <input placeholder="Localizar O.S. ou Equipamento..." className="bg-transparent flex-1 outline-none text-white font-bold" value={search} onChange={e=>setSearch(e.target.value)} />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {filtered.map(o => (
          <div key={o.id} className="nexus-card p-8 flex flex-col justify-between group">
            <div className="space-y-4">
               <div className="flex justify-between items-start">
                  <span className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase ${o.status==='DONE'?'bg-emerald-500 text-black':o.status==='OPEN'?'bg-orange-500 text-black':'bg-blue-500 text-black'}`}>
                    {o.status}
                  </span>
                  <button onClick={()=>dbService.del('service_orders', o.id)} className="text-slate-700 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={18}/></button>
               </div>
               <h4 className="text-2xl font-black text-white italic tracking-tighter uppercase">{o.equipment}</h4>
               <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><User size={12}/> {o.customerName}</p>
               <p className="text-sm text-slate-400 font-bold leading-relaxed">{o.description}</p>
            </div>
            <div className="pt-6 mt-6 border-t border-white/5 flex justify-between items-center">
               <p className="text-2xl font-black text-orange-500 italic">R$ {o.cost.toFixed(2)}</p>
               <div className="flex gap-2">
                 {o.status !== 'DONE' && <button onClick={()=>updateStatus(o.id, 'DONE')} className="p-3 bg-emerald-500/10 text-emerald-500 rounded-xl hover:bg-emerald-500 hover:text-black transition-all"><CheckCircle size={18}/></button>}
                 {o.status === 'OPEN' && <button onClick={()=>updateStatus(o.id, 'IN_PROGRESS')} className="p-3 bg-blue-500/10 text-blue-500 rounded-xl hover:bg-blue-500 hover:text-white transition-all"><Clock size={18}/></button>}
               </div>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
          <div className="nexus-card w-full max-w-xl p-10 border-orange-500/50">
            <div className="flex justify-between items-center mb-8">
               <h3 className="text-2xl font-black italic uppercase text-orange-500">Abertura de O.S.</h3>
               <button onClick={()=>setIsModalOpen(false)}><X className="text-slate-500"/></button>
            </div>
            <form onSubmit={handleSave} className="space-y-6">
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-500 uppercase ml-2">Cliente</label>
                 <select value={formData.customerId} onChange={e=>setFormData({...formData, customerId: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold" required>
                    <option value="">Selecione...</option>
                    {customers.map(c=><option key={c.id} value={c.id}>{c.name.toUpperCase()}</option>)}
                 </select>
               </div>
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-500 uppercase ml-2">Equipamento</label>
                 <input value={formData.equipment} onChange={e=>setFormData({...formData, equipment: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold" required />
               </div>
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-500 uppercase ml-2">Defeito / Descrição</label>
                 <textarea value={formData.description} onChange={e=>setFormData({...formData, description: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold h-24" required />
               </div>
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-500 uppercase ml-2">Orçamento Previsto R$</label>
                 <input type="number" step="0.01" value={formData.cost} onChange={e=>setFormData({...formData, cost: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold" required />
               </div>
               <button disabled={isSaving} type="submit" className="btn-orange w-full py-5 rounded-2xl flex items-center justify-center gap-3">
                 {isSaving ? <Loader2 className="animate-spin" /> : <Wrench size={18}/>} ABRIR ORDEM
               </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceOrdersView;

import React, { useState, useEffect } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { auth, dbService } from '../services/firebase';
import { Zap, Loader2, KeyRound, Mail, AlertCircle, MessageCircle } from 'lucide-react';

const LoginView: React.FC = () => {
  const [email, setEmail] = useState('');
  const [pass, setPass] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });
  const [refCode, setRefCode] = useState('');

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get('ref');
    if (code) setRefCode(code.toUpperCase());
  }, []);

  const handleResetPassword = async () => {
    if (!email) return setMessage({ text: 'Digite seu e-mail operacional primeiro.', type: 'error' });
    try {
      await dbService.resetPassword(email);
      setMessage({ text: 'Link de recuperação enviado ao seu e-mail.', type: 'success' });
    } catch (err) {
      setMessage({ text: 'Erro ao enviar link. Verifique o e-mail.', type: 'error' });
    }
  };

  const openWhatsAppSupport = () => {
    const msg = encodeURIComponent("Olá SuperAdmin Nexus! Preciso de suporte imediato em meu terminal operante. Identificação: " + (email || "Não informado"));
    window.open(`https://wa.me/5511910688022?text=${msg}`, '_blank');
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage({ text: '', type: '' });
    try {
      await signInWithEmailAndPassword(auth, email, pass);
    } catch (err: any) {
      if (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential') {
        try {
          const cred = await createUserWithEmailAndPassword(auth, email, pass);
          await dbService.initProfile(cred.user.uid, email, refCode);
        } catch (regErr: any) {
          setMessage({ text: 'Falha ao inicializar núcleo operacional.', type: 'error' });
        }
      } else {
        setMessage({ text: 'Erro de autenticação de rede.', type: 'error' });
      }
    } finally { setLoading(false); }
  };

  return (
    <div className="h-screen w-full flex items-center justify-center bg-black p-6 relative overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-20"></div>

      <div className="w-full max-w-sm nexus-card p-10 border-orange-500/20 shadow-2xl relative z-10 box-glow">
        <div className="text-center mb-10">
          <div className="w-16 h-16 bg-orange-500 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl rotate-3">
            <Zap size={32} className="text-black fill-current" />
          </div>
          <h1 className="font-terminal font-black text-2xl text-glow tracking-tighter italic uppercase leading-none">Nexus Radiant</h1>
          <p className="text-[9px] text-slate-500 font-bold uppercase tracking-[0.4em] mt-3">Elite Operating System</p>
        </div>

        <form onSubmit={submit} className="space-y-5">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-orange-500 uppercase tracking-widest ml-1">ID Operador</label>
            <div className="relative">
              <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-orange-500/30" size={18} />
              <input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-black border border-white/10 rounded-2xl pl-14 pr-6 py-4 text-white font-bold outline-none focus:border-orange-500 transition-all placeholder:text-slate-800" placeholder="operador@nexus.com" />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-orange-500 uppercase tracking-widest ml-1">Chave Mestra</label>
            <div className="relative">
              <KeyRound className="absolute left-5 top-1/2 -translate-y-1/2 text-orange-500/30" size={18} />
              <input required type="password" value={pass} onChange={e => setPass(e.target.value)} className="w-full bg-black border border-white/10 rounded-2xl pl-14 pr-6 py-4 text-white font-bold outline-none focus:border-orange-500 transition-all placeholder:text-slate-800" placeholder="••••••••" />
            </div>
          </div>

          <div className="flex justify-between items-center px-1 text-[9px] font-black uppercase tracking-widest">
            <button type="button" onClick={handleResetPassword} className="text-slate-600 hover:text-orange-500 transition-colors">Esqueci senha</button>
            <button type="button" onClick={openWhatsAppSupport} className="text-emerald-500 hover:text-emerald-400">Suporte</button>
          </div>

          <button disabled={loading} className="btn-orange w-full py-5 rounded-2xl flex items-center justify-center gap-4 mt-4">
            {loading ? <Loader2 className="animate-spin" size={20}/> : <span className="uppercase font-black tracking-widest">Acessar Terminal</span>}
          </button>
        </form>
      </div>
    </div>
  );
};

export default LoginView;

