interface ServiceOrdersViewProps {
  userId: string;
  customers: Customer[];
  profile: UserProfile;
}

const ServiceOrdersView: React.FC<ServiceOrdersViewProps> = ({ userId, customers, profile }) => {
  const [orders, setOrders] = useState<ServiceOrder[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [search, setSearch] = useState('');
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    customerId: '',
    equipment: '',
    equipmentBrand: '',
    equipmentModel: '',
    equipmentSerial: '',
    description: '',
    informedDefect: '',
    technicalDiagnosis: '',
    executedService: '',
    partsUsed: '',
    cost: '',
    paymentMethod: 'PIX',
    deliveryDeadline: '',
    warranty: '90 dias',
    notes: '',
    status: 'OPEN' as any
  });

  useEffect(() => {
    return dbService.sync('service_orders', userId, (data) => setOrders(data as ServiceOrder[]));
  }, [userId]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    const customer = customers.find(c => c.id === formData.customerId);
    try {
      await dbService.add('service_orders', userId, {
        ...formData,
        customerName: customer?.name || 'Cliente Avulso',
        customerCpfCnpj: customer?.cpfCnpj || '',
        customerPhone: customer?.phone || '',
        customerAddress: customer?.address || '',
        cost: parseFloat(formData.cost || '0')
      });
      setIsModalOpen(false);
      resetForm();
    } catch (err) { alert("Erro ao salvar O.S."); } finally { setIsSaving(false); }
  };

  const resetForm = () => {
    setFormData({
      customerId: '',
      equipment: '',
      equipmentBrand: '',
      equipmentModel: '',
      equipmentSerial: '',
      description: '',
      informedDefect: '',
      technicalDiagnosis: '',
      executedService: '',
      partsUsed: '',
      cost: '',
      paymentMethod: 'PIX',
      deliveryDeadline: '',
      warranty: '90 dias',
      notes: '',
      status: 'OPEN'
