                        <input type="text" value={formData.warranty} onChange={e=>setFormData({...formData, warranty: e.target.value})} className="w-full p-3 rounded-xl bg-black border border-white/10 text-white text-xs" placeholder="Ex: 90 dias" />
                      </div>
                   </div>
                 </div>

                 {/* Seção Equipamento */}
                 <div className="space-y-4">
                    <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest">Equipamento / Produto</h5>
                    <input placeholder="Nome do Equipamento (Ex: iPhone 13)" value={formData.equipment} onChange={e=>setFormData({...formData, equipment: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold text-sm" required />
                    <div className="grid grid-cols-3 gap-2">
                       <input placeholder="Marca" value={formData.equipmentBrand} onChange={e=>setFormData({...formData, equipmentBrand: e.target.value})} className="p-3 rounded-xl bg-black border border-white/10 text-white text-xs" />
                       <input placeholder="Modelo" value={formData.equipmentModel} onChange={e=>setFormData({...formData, equipmentModel: e.target.value})} className="p-3 rounded-xl bg-black border border-white/10 text-white text-xs" />
                       <input placeholder="Série/IMEI" value={formData.equipmentSerial} onChange={e=>setFormData({...formData, equipmentSerial: e.target.value})} className="p-3 rounded-xl bg-black border border-white/10 text-white text-xs" />
                    </div>
                 </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 {/* Seção Defeito/Diagnóstico */}
                 <div className="space-y-4">
                    <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest">Descrição Técnica</h5>
                    <textarea placeholder="Defeito Informado pelo Cliente..." value={formData.informedDefect} onChange={e=>setFormData({...formData, informedDefect: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white text-sm h-20 resize-none" />
                    <textarea placeholder="Diagnóstico Preliminar do Técnico..." value={formData.technicalDiagnosis} onChange={e=>setFormData({...formData, technicalDiagnosis: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white text-sm h-20 resize-none" />
                 </div>

                 {/* Seção Execução/Financeiro */}
                 <div className="space-y-4">
                    <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest">Execução e Valores</h5>
                    <textarea placeholder="Descrição dos Serviços e Peças..." value={formData.description} onChange={e=>setFormData({...formData, description: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white text-sm h-20 resize-none" required />
                    <div className="grid grid-cols-2 gap-4">
                       <div className="space-y-1">
                          <label className="text-[8px] font-black text-slate-600 uppercase ml-2">Valor Previsto R$</label>
                          <input type="number" step="0.01" value={formData.cost} onChange={e=>setFormData({...formData, cost: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-black text-lg" required />
                       </div>
                       <div className="space-y-1">
                          <label className="text-[8px] font-black text-slate-600 uppercase ml-2">Forma de Pagto</label>
                          <select value={formData.paymentMethod} onChange={e=>setFormData({...formData, paymentMethod: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold text-sm">
                             <option value="PIX">PIX</option>
                             <option value="DINHEIRO">DINHEIRO</option>
                             <option value="CARTÃO CRÉDITO">CARTÃO CRÉDITO</option>
                             <option value="CARTÃO DÉBITO">CARTÃO DÉBITO</option>
                          </select>
                       </div>
                    </div>
                 </div>
               </div>

               <button disabled={isSaving} type="submit" className="btn-orange w-full py-6 rounded-2xl flex items-center justify-center gap-3 text-lg">
                 {isSaving ? <Loader2 className="animate-spin" /> : <Wrench size={24}/>} GERAR ORDEM DE SERVIÇO
               </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

