import React, { useState, useMemo } from 'react';
import { Plus, Search, Mail, Phone, MapPin, Edit2, Trash2, X, UserCheck, Loader2, Printer, FileText, ChevronDown, ChevronUp, Smartphone, Briefcase, CreditCard, ShieldCheck } from 'lucide-react';
import { Customer, Order } from '../types';
import { dbService } from '../services/firebase';

interface CustomersViewProps {
  customers: Customer[];
  orders: Order[];
  userId: string;
}

const CustomersView: React.FC<CustomersViewProps> = ({ customers, orders, userId }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const initialForm = {
    name: '', email: '', phone: '', whatsapp: '', address: '',
    cpfCnpj: '', rg: '', birthDate: '', maritalStatus: 'Não Informado',
    street: '', number: '', neighborhood: '', city: '', state: '', zip: '', complement: '',
    profession: '', company: '', role: '', income: '',
    clientType: 'PF' as 'PF' | 'PJ', assignedRep: '',
    preferredPayment: 'PIX', preferredTime: 'Manhã', preferredChannel: 'WhatsApp',
    notes: '', lgpdConsent: true
  };

  const [formData, setFormData] = useState(initialForm);

  const unifiedCustomers = useMemo(() => {
    const list = [...customers];
    orders.forEach(order => {
      const gName = (order as any).guestName;
      const gPhone = (order as any).guestPhone;
      if (gName && gName !== 'VENDA RÁPIDA') {
        const alreadyExists = list.some(c => 
          c.name.toLowerCase() === gName.toLowerCase() || 
          (c.phone && c.phone === gPhone)
        );
        if (!alreadyExists) {
          list.push({
            id: `venda-${order.id}`,
            userId: order.userId,
            name: gName,
            phone: gPhone,
            email: 'Origem: Venda PdV',
            registrationDate: order.createdAt
          } as Customer);
        }
      }
    });
    return list;
  }, [customers, orders]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const data = { ...formData, registrationDate: editingCustomer?.registrationDate || new Date() };
      if (editingCustomer && !editingCustomer.id.startsWith('venda-')) {
        await dbService.update('customers', editingCustomer.id, data);
      } else {
        await dbService.add('customers', userId, data);
      }
      setIsModalOpen(false);
      setEditingCustomer(null);
      setFormData(initialForm);
    } catch (err) { alert("Erro ao salvar cliente."); } finally { setIsSaving(false); }
  };

  const handleEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      name: customer.name || '',
      email: customer.email || '',
      phone: customer.phone || '',
      whatsapp: customer.whatsapp || '',
      address: customer.address || '',
      cpfCnpj: customer.cpfCnpj || '',
      rg: customer.rg || '',
      birthDate: customer.birthDate || '',
      maritalStatus: customer.maritalStatus || 'Não Informado',
      street: customer.street || '',
      number: customer.number || '',
      neighborhood: customer.neighborhood || '',
      city: customer.city || '',
      state: customer.state || '',
      zip: customer.zip || '',
      complement: customer.complement || '',
      profession: customer.profession || '',
      company: customer.company || '',
      role: customer.role || '',
      income: customer.income || '',
      clientType: customer.clientType || 'PF',
      assignedRep: customer.assignedRep || '',
      preferredPayment: customer.preferredPayment || 'PIX',
      preferredTime: customer.preferredTime || 'Manhã',
      preferredChannel: customer.preferredChannel || 'WhatsApp',
      notes: customer.notes || '',
      lgpdConsent: customer.lgpdConsent ?? true
    });
    setIsModalOpen(true);
  };

  const printFiche = (c: Customer) => {
    const printWindow = window.open('', '_blank');
    if (printWindow) {
      const customerOrders = orders.filter(o => o.customerId === c.id || (o as any).guestName === c.name);
      const totalSpent = customerOrders.reduce((s,o) => s + o.total, 0);

      const html = `
        <html>
        <head>
          <title>Ficha Cadastral - ${c.name}</title>
          <style>
            body { font-family: 'Segoe UI', sans-serif; padding: 40px; color: #333; line-height: 1.4; font-size: 11px; }
            .header { text-align: center; border-bottom: 2px solid #ff8000; padding-bottom: 20px; margin-bottom: 20px; }
            .header h1 { color: #ff8000; text-transform: uppercase; margin: 0; font-size: 20px; }
            .section { margin-bottom: 15px; border: 1px solid #eee; border-radius: 8px; overflow: hidden; }
            .section-title { background: #fff5eb; padding: 8px 12px; font-weight: bold; border-bottom: 1px solid #eee; text-transform: uppercase; color: #ff8000; font-size: 10px; }
            .grid { display: grid; grid-template-columns: repeat(3, 1fr); padding: 12px; gap: 10px; }
            .field { margin-bottom: 5px; }
            .label { font-weight: bold; color: #666; display: block; font-size: 9px; }
            .value { font-size: 11px; color: #000; }
            .full-width { grid-column: span 3; }
            table { width: 100%; border-collapse: collapse; margin-top: 5px; }
            table th { background: #f9f9f9; padding: 6px; text-align: left; border: 1px solid #eee; font-size: 9px; }
            table td { padding: 6px; border: 1px solid #eee; font-size: 10px; }
            .footer { text-align: center; margin-top: 30px; font-size: 8px; color: #999; border-top: 1px solid #eee; padding-top: 10px; }
            @media print { .no-print { display: none; } }
          </style>
        </head>
        <body onload="window.print()">
          <div class="header">
            <h1>Ficha Cadastral de Cliente</h1>
            <p>ID: ${c.id.toUpperCase()}</p>
          </div>

          <div class="section">
            <div class="section-title">Dados Pessoais e Comerciais</div>
            <div class="grid">
              <div class="field"><span class="label">Nome Completo</span><span class="value">${c.name}</span></div>
              <div class="field"><span class="label">CPF / CNPJ</span><span class="value">${c.cpfCnpj || '---'}</span></div>
              <div class="field"><span class="label">RG</span><span class="value">${c.rg || '---'}</span></div>
              <div class="field"><span class="label">Data Nasc.</span><span class="value">${c.birthDate || '---'}</span></div>
              <div class="field"><span class="label">Estado Civil</span><span class="value">${c.maritalStatus || '---'}</span></div>
              <div class="field"><span class="label">Tipo Cliente</span><span class="value">${c.clientType || 'PF'}</span></div>
              <div class="field"><span class="label">Atendente Resp.</span><span class="value">${c.assignedRep || '---'}</span></div>
            </div>
          </div>

          <div class="section">
            <div class="section-title">Contato e Localização</div>
            <div class="grid">
              <div class="field"><span class="label">E-mail</span><span class="value">${c.email || '---'}</span></div>
              <div class="field"><span class="label">Telefone</span><span class="value">${c.phone || '---'}</span></div>
              <div class="field"><span class="label">WhatsApp</span><span class="value">${c.whatsapp || '---'}</span></div>
              <div class="field full-width"><span class="label">Endereço Completo</span><span class="value">${c.street || ''}, ${c.number || ''} ${c.complement ? `- ${c.complement}` : ''} - ${c.neighborhood || ''}, ${c.city || ''}/${c.state || ''} - CEP: ${c.zip || ''}</span></div>
            </div>
          </div>

          <div class="section">
            <div class="section-title">Dados Profissionais</div>
            <div class="grid">
              <div class="field"><span class="label">Profissão</span><span class="value">${c.profession || '---'}</span></div>
              <div class="field"><span class="label">Empresa</span><span class="value">${c.company || '---'}</span></div>
              <div class="field"><span class="label">Cargo</span><span class="value">${c.role || '---'}</span></div>
              <div class="field"><span class="label">Renda Aprox.</span><span class="value">${c.income || '---'}</span></div>
            </div>
          </div>

          <div class="section">
            <div class="section-title">Preferências e Notas</div>
            <div class="grid">
              <div class="field"><span class="label">Pagamento Pref.</span><span class="value">${c.preferredPayment || '---'}</span></div>
              <div class="field"><span class="label">Horário Atend.</span><span class="value">${c.preferredTime || '---'}</span></div>
              <div class="field"><span class="label">Canal Pref.</span><span class="value">${c.preferredChannel || '---'}</span></div>
              <div class="field full-width"><span class="label">Observações Gerais</span><span class="value">${c.notes || 'Nenhuma observação.'}</span></div>
            </div>
          </div>

          <div class="section">
            <div class="section-title">Histórico de Atendimento / Compras</div>
            <table>
              <thead>
                <tr><th>Data</th><th>Serviço/Produto</th><th>Forma Pagto</th><th>Valor (R$)</th></tr>
              </thead>
              <tbody>
                ${customerOrders.length > 0 ? customerOrders.map(o => `
                  <tr>
                    <td>${o.createdAt?.toDate ? o.createdAt.toDate().toLocaleDateString('pt-BR') : '---'}</td>
                    <td>${o.items.map(i => i.nameAtTime).join(', ')}</td>
                    <td>${o.paymentMethod}</td>
                    <td>${o.total.toFixed(2)}</td>
                  </tr>
                `).join('') : '<tr><td colspan="4" style="text-align:center">Nenhum registro encontrado.</td></tr>'}
              </tbody>
            </table>
            <div style="padding: 10px; text-align: right; font-weight: bold; border-top: 1px solid #eee;">Volume Total: R$ ${totalSpent.toFixed(2)}</div>
          </div>

          <div style="margin-top: 30px; border: 1px solid #ddd; padding: 15px; border-radius: 8px;">
            <p><strong>Autorização LGPD:</strong> [ ${c.lgpdConsent ? 'X' : ' '} ] O cliente consente expressamente com o tratamento de seus dados pessoais para fins de cadastro, atendimento e comunicações comerciais, nos termos da Lei Geral de Proteção de Dados (Lei nº 13.709/2018).</p>
            <div style="margin-top: 40px; display: grid; grid-template-columns: 1fr 1fr; gap: 40px; text-align: center;">
              <div style="border-top: 1px solid #000; padding-top: 5px;">Assinatura do Cliente</div>
              <div style="border-top: 1px solid #000; padding-top: 5px;">Responsável pelo Atendimento</div>
            </div>
          </div>

          <div class="footer">Gerado via Facindemais OS 3.1 - ${new Date().toLocaleString()}</div>
        </body>
        </html>
      `;
      printWindow.document.write(html);
      printWindow.document.close();
    }
  };

  const filtered = unifiedCustomers.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (c.phone && c.phone.includes(searchTerm)) ||
    (c.cpfCnpj && c.cpfCnpj.includes(searchTerm))
  );

  return (
    <div className="space-y-12 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
        <div>
          <h2 className="text-4xl font-black text-white tracking-tighter italic text-glow uppercase">Central de Clientes</h2>
          <p className="text-slate-500 font-bold mt-4 text-xs tracking-widest uppercase opacity-70">Sincronização Elite de Identidades.</p>
        </div>
        <button onClick={() => { setEditingCustomer(null); setFormData(initialForm); setIsModalOpen(true); }} className="btn-orange px-8 py-4 rounded-2xl flex items-center gap-4 active:scale-95 transition-all shadow-lg">
          <Plus size={24} /> NOVA FICHA
        </button>
      </div>

      <div className="bg-white/5 p-4 rounded-2xl border border-white/10 flex items-center gap-4 focus-within:border-orange-500/50 transition-all">
        <Search className="text-orange-500/50" size={24} />
        <input 
          type="text" 
          placeholder="Localizar por nome, telefone ou CPF/CNPJ..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="flex-1 bg-transparent outline-none font-bold text-white placeholder:text-slate-700" 
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filtered.map(customer => {
          const isExp = expandedId === customer.id;
          return (
            <div key={customer.id} className="nexus-card overflow-hidden group">
              <div className="p-6 flex flex-col gap-4">
                <div className="flex justify-between items-start">
                   <div className="w-14 h-14 rounded-2xl bg-orange-500/10 border border-orange-500/20 flex items-center justify-center font-black text-2xl text-orange-500">
                     {customer.name.charAt(0).toUpperCase()}
                   </div>
                   <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-all">
                     <button onClick={() => printFiche(customer)} className="p-2.5 bg-white/5 text-slate-400 rounded-xl hover:text-white"><Printer size={16}/></button>
                     <button onClick={() => handleEdit(customer)} className="p-2.5 bg-white/5 text-slate-400 rounded-xl hover:text-orange-500"><Edit2 size={16}/></button>
                     {!customer.id.startsWith('venda-') && (
                        <button onClick={() => { if(confirm('Excluir?')) dbService.del('customers', customer.id); }} className="p-2.5 bg-rose-500/10 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white"><Trash2 size={16}/></button>
                     )}
                   </div>
                </div>
                <div>
                   <h3 className="font-black text-white text-lg tracking-tight uppercase truncate">{customer.name}</h3>
                   <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">{customer.cpfCnpj || 'CPF/CNPJ NÃO INFORMADO'}</p>
                </div>
                <div className="space-y-2 border-t border-white/5 pt-4">
                  <div className="flex items-center gap-3 text-[10px] font-bold text-slate-400 uppercase">
                    <Smartphone size={14} className="text-orange-500" /> {customer.phone || 'SEM TELEFONE'}
                  </div>
                  <div className="flex items-center gap-3 text-[10px] font-bold text-slate-400 uppercase">
                    <Mail size={14} className="text-orange-500" /> {customer.email || 'SEM E-MAIL'}
                  </div>
                </div>
                <button onClick={() => setExpandedId(isExp ? null : customer.id)} className="w-full py-2 bg-white/5 rounded-lg text-[9px] font-black uppercase tracking-widest text-slate-500 hover:text-white transition-all">
                  {isExp ? <ChevronUp size={14} className="mx-auto" /> : <ChevronDown size={14} className="mx-auto" />}
                </button>
              </div>

              {isExp && (
                <div className="p-6 bg-black/40 border-t border-white/5 animate-fade-in space-y-4">
                   <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <span className="text-[8px] font-black text-orange-500 uppercase tracking-widest">Cidade/UF</span>
                        <p className="text-[10px] text-white font-bold">{customer.city || '---'}/{customer.state || '--'}</p>
                      </div>
                      <div className="space-y-1">
                        <span className="text-[8px] font-black text-orange-500 uppercase tracking-widest">Tipo</span>
                        <p className="text-[10px] text-white font-bold">{customer.clientType || 'PF'}</p>
                      </div>
                   </div>
                   <div className="space-y-1">
                      <span className="text-[8px] font-black text-orange-500 uppercase tracking-widest">Observações</span>
                      <p className="text-[10px] text-slate-400 leading-tight italic">{customer.notes || 'Nenhuma nota registrada.'}</p>
                   </div>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/90 backdrop-blur-md overflow-y-auto">
          <div className="nexus-card w-full max-w-5xl p-8 border-orange-500/50 my-auto">
            <div className="flex justify-between items-center mb-8 pb-4 border-b border-white/5">
              <h3 className="text-2xl font-black italic uppercase text-orange-500 flex items-center gap-4"><UserCheck /> Ficha Cadastral do Cliente</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/5 rounded-full text-slate-500"><X size={24} /></button>
            </div>

            <form onSubmit={handleSave} className="space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                {/* Dados Pessoais */}
                <div className="space-y-4">
                  <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest flex items-center gap-2"><FileText size={14}/> Dados Pessoais</h5>
                  <input required placeholder="Nome Completo" value={formData.name} onChange={e=>setFormData({...formData, name: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold text-xs" />
                  <div className="grid grid-cols-2 gap-2">
                    <input placeholder="CPF / CNPJ" value={formData.cpfCnpj} onChange={e=>setFormData({...formData, cpfCnpj: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                    <input placeholder="RG" value={formData.rg} onChange={e=>setFormData({...formData, rg: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <input type="date" placeholder="Nascimento" value={formData.birthDate} onChange={e=>setFormData({...formData, birthDate: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                    <select value={formData.maritalStatus} onChange={e=>setFormData({...formData, maritalStatus: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs">
                       <option>Solteiro(a)</option>
                       <option>Casado(a)</option>
                       <option>Divorciado(a)</option>
                       <option>Viúvo(a)</option>
                    </select>
                  </div>
                </div>

                {/* Contato e Endereço */}
                <div className="space-y-4">
                  <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest flex items-center gap-2"><MapPin size={14}/> Localização e Contato</h5>
                  <div className="grid grid-cols-2 gap-2">
                    <input placeholder="Telefone" value={formData.phone} onChange={e=>setFormData({...formData, phone: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                    <input placeholder="WhatsApp" value={formData.whatsapp} onChange={e=>setFormData({...formData, whatsapp: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                  </div>
                  <input placeholder="E-mail" value={formData.email} onChange={e=>setFormData({...formData, email: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                  <div className="grid grid-cols-3 gap-2">
                    <input placeholder="Rua" value={formData.street} onChange={e=>setFormData({...formData, street: e.target.value})} className="col-span-2 p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                    <input placeholder="Nº" value={formData.number} onChange={e=>setFormData({...formData, number: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <input placeholder="Bairro" value={formData.neighborhood} onChange={e=>setFormData({...formData, neighborhood: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                    <input placeholder="Cidade" value={formData.city} onChange={e=>setFormData({...formData, city: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                  </div>
                </div>

                {/* Profissional e Preferências */}
                <div className="space-y-4">
                  <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest flex items-center gap-2"><Briefcase size={14}/> Profissional e Preferências</h5>
                  <div className="grid grid-cols-2 gap-2">
                    <input placeholder="Profissão" value={formData.profession} onChange={e=>setFormData({...formData, profession: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                    <input placeholder="Renda Aprox." value={formData.income} onChange={e=>setFormData({...formData, income: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs" />
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <select value={formData.clientType} onChange={e=>setFormData({...formData, clientType: e.target.value as any})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs">
                       <option value="PF">Pessoa Física</option>
                       <option value="PJ">Pessoa Jurídica</option>
                    </select>
                    <select value={formData.preferredPayment} onChange={e=>setFormData({...formData, preferredPayment: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs">
                       <option>PIX</option>
                       <option>Cartão Crédito</option>
                       <option>Cartão Débito</option>
                       <option>Dinheiro</option>
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <select value={formData.preferredTime} onChange={e=>setFormData({...formData, preferredTime: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs">
                       <option>Manhã</option>
                       <option>Tarde</option>
                       <option>Noite</option>
                    </select>
                    <select value={formData.preferredChannel} onChange={e=>setFormData({...formData, preferredChannel: e.target.value})} className="p-4 rounded-xl bg-black border border-white/10 text-white text-xs">
                       <option>WhatsApp</option>
                       <option>E-mail</option>
                       <option>Telefone</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="space-y-4 border-t border-white/5 pt-6">
                <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest flex items-center gap-2"><ShieldCheck size={14}/> Observações e Segurança</h5>
                <textarea placeholder="Informações adicionais importantes sobre o cliente..." value={formData.notes} onChange={e=>setFormData({...formData, notes: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white text-xs h-20 resize-none" />
                <div className="flex items-center gap-3 bg-white/5 p-4 rounded-xl border border-white/5">
                   <input type="checkbox" checked={formData.lgpdConsent} onChange={e=>setFormData({...formData, lgpdConsent: e.target.checked})} className="w-4 h-4 accent-orange-500" />
                   <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tight">O cliente consente com o tratamento de seus dados pessoais nos termos da LGPD para fins de cadastro e atendimento.</p>
                </div>
              </div>

              <button disabled={isSaving} type="submit" className="btn-orange w-full py-6 rounded-2xl flex items-center justify-center gap-4 text-lg">
                {isSaving ? <Loader2 className="animate-spin" /> : <UserCheck size={28}/>} SALVAR FICHA CADASTRAL
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomersView;

export interface UserProfile {
  uid: string;
  email: string;
  role: 'super-admin' | 'admin';
  status: 'active' | 'blocked';
  subscriptionStatus: 'PAID' | 'EXPIRED' | 'TRIAL';
  officeName: string;
  phone?: string;
  address?: string;
  pixKey?: string;
  logoUrl?: string;
  cnpj?: string;
  createdAt: any;
  subscriptionExpiresAt: any;
