  userId: string;
  description: string;
  amount: number;
  category: string;
  createdAt: any;
}

export interface ServiceOrder {
  id: string;
  userId: string;
  customerId: string;
  customerName: string;
  customerCpfCnpj?: string;
  customerPhone?: string;
  customerAddress?: string;
  equipment: string;
  equipmentBrand?: string;
  equipmentModel?: string;
  equipmentSerial?: string;
  description: string;
  informedDefect?: string;
  technicalDiagnosis?: string;
  executedService?: string;
  partsUsed?: string;
  status: 'OPEN' | 'IN_PROGRESS' | 'DONE' | 'CANCELLED';
  cost: number;
  paymentMethod?: string;
  deliveryDeadline?: string;
  warranty?: string;
  notes?: string;
  createdAt: any;
}

export type ViewState = 
  | 'DASHBOARD' | 'OFFICES' | 'STOCK' | 'SALES' 
  | 'SERVICE_ORDERS' | 'CUSTOMERS' | 'QUOTES' 
  | 'FINANCIAL' | 'AGENDA' | 'REFERRALS' | 'PROFILE';

import React, { useState } from 'react';
import { FileText, Plus, Minus, Trash2, Search, X, Loader2, Zap, Smartphone, Calendar, Briefcase, User, Download, MessageCircle, ChevronDown, ChevronUp, ShoppingCart, ShieldCheck, CreditCard, Clock } from 'lucide-react';
import { Quote, Product, Customer, OrderItem, UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface QuotesViewProps {
  quotes: Quote[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const QuotesView: React.FC<QuotesViewProps> = ({ quotes, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [items, setItems] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [guestData, setGuestData] = useState({ name: '', phone: '', cpfCnpj: '' });
  const [paymentMethod, setPaymentMethod] = useState('PIX');
  const [installments, setInstallments] = useState(1);
  const [validUntil, setValidUntil] = useState('');
  const [deliveryDeadline, setDeliveryDeadline] = useState('A combinar');
  const [warranty, setWarranty] = useState('90 dias');
  const [notes, setNotes] = useState('');
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1', type: 'SERVICE' as any });
  const [expandedQuoteId, setExpandedQuoteId] = useState<string | null>(null);

  const addItem = (product: Product) => {
    setItems(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type as any }];
    });
  };

  const updateQty = (id: string, delta: number) => {
    setItems(prev => prev.map(item => {
      if (item.productId === id) return { ...item, quantity: Math.max(1, item.quantity + delta) };
      return item;
    }));
  };

  const addManualItem = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha a descrição e o valor.");
    setItems(prev => [...prev, {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: manualItem.type
    }]);
    setManualItem({ name: '', price: '', qty: '1', type: 'SERVICE' });
  };

  const generatePDFAndShare = (quote: Quote) => {
    const customer = customers.find(c => c.id === quote.customerId);
    const customerName = quote.customerName;
    const customerPhone = (quote as any).guestPhone || customer?.phone || '---';
    const customerCpfCnpj = (quote as any).guestCpfCnpj || customer?.cpfCnpj || '---';

    const printWindow = window.open('', '_blank');
    if (printWindow) {
      const date = quote.createdAt?.toDate ? quote.createdAt.toDate().toLocaleDateString('pt-BR') : new Date().toLocaleDateString('pt-BR');
      const html = `
        <html>
        <head>
          <title>Orçamento #${quote.id.substring(0,8).toUpperCase()}</title>
          <style>
            body { font-family: 'Segoe UI', sans-serif; padding: 40px; color: #333; line-height: 1.4; font-size: 11px; }
            .header { display: flex; justify-content: space-between; border-bottom: 2px solid #ff8000; padding-bottom: 20px; margin-bottom: 30px; }
            .company-info h1 { margin: 0; color: #ff8000; font-size: 24px; text-transform: uppercase; }
            .company-details { font-size: 10px; color: #666; margin-top: 5px; }
            .doc-info { text-align: right; }
            .doc-title { font-size: 18px; font-weight: 900; color: #000; }
            .section { margin-bottom: 20px; }
            .section-title { background: #fdf2f2; border-left: 4px solid #ff8000; padding: 6px 12px; font-weight: bold; text-transform: uppercase; margin-bottom: 10px; font-size: 10px; }
            .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
            table { width: 100%; border-collapse: collapse; margin-top: 10px; }
            table th { background: #f8fafc; padding: 10px; text-align: left; border-bottom: 2px solid #eee; font-size: 10px; text-transform: uppercase; color: #666; }
            table td { padding: 10px; border-bottom: 1px solid #eee; font-size: 11px; }
            .totals { margin-top: 20px; text-align: right; padding: 20px; background: #fffaf5; border-radius: 8px; border: 1px solid #ffe8cc; }
            .total-value { font-size: 20px; font-weight: 900; color: #ff8000; }
            .notes { margin-top: 20px; font-size: 10px; color: #666; padding: 10px; background: #f9f9f9; border-radius: 5px; }
            .signatures { display: grid; grid-template-columns: 1fr 1fr; gap: 50px; margin-top: 60px; text-align: center; }
            .sig-line { border-top: 1px solid #333; padding-top: 5px; }
            @media print { .no-print { display: none; } }
          </style>
        </head>
        <body onload="window.print()">
          <div class="header">
            <div class="company-info">
              <h1>${profile.officeName}</h1>
              <div class="company-details">
                CNPJ: ${profile.cnpj || '---'}<br>
                Tel: ${profile.phone || '---'} | Email: ${profile.email}<br>
                End: ${profile.address || '---'}
              </div>
            </div>
            <div class="doc-info">
              <div class="doc-title">ORÇAMENTO #${quote.id.substring(0,8).toUpperCase()}</div>
              <div>Data: ${date}</div>
              <div>Vencimento: ${new Date(quote.validUntil).toLocaleDateString('pt-BR')}</div>
            </div>
          </div>

          <div class="section">
            <div class="section-title">Dados do Cliente</div>
            <div class="grid-2">
              <div><strong>Nome:</strong> ${customerName}</div>
              <div><strong>CPF/CNPJ:</strong> ${customerCpfCnpj}</div>
              <div><strong>Telefone:</strong> ${customerPhone}</div>
            </div>
          </div>

          <div class="section">
            <div class="section-title">Itens e Serviços</div>
            <table>
              <thead>
                <tr>
                  <th>Descrição</th>
                  <th>Qtd</th>
                  <th>Vl. Unitário</th>
                  <th>Total</th>
                </tr>
              </thead>
              <tbody>
                ${quote.items.map(i => `
                  <tr>
                    <td><strong>${i.nameAtTime}</strong><br><small>${i.type}</small></td>
                    <td>${i.quantity}</td>
                    <td>R$ ${i.priceAtTime.toFixed(2)}</td>
                    <td>R$ ${(i.priceAtTime * i.quantity).toFixed(2)}</td>
                  </tr>
                `).join('')}
              </tbody>
            </table>
          </div>

          <div class="grid-2">
            <div class="section">
              <div class="section-title">Condições Gerais</div>
              <div style="font-size: 10px;">
                <p><strong>Forma de Pagamento:</strong> ${quote.paymentMethod || 'A combinar'} (${quote.installments || 1}x)</p>
                <p><strong>Prazo de Entrega:</strong> ${quote.deliveryDeadline || 'A combinar'}</p>
                <p><strong>Garantia:</strong> ${quote.warranty || 'Consultar'}</p>
              </div>
            </div>
            <div class="totals">
              <div style="font-size: 10px; color: #666; text-transform: uppercase;">Valor Total</div>
              <div class="total-value">R$ ${quote.total.toFixed(2)}</div>
            </div>
          </div>

          ${quote.notes ? `<div class="notes"><strong>Observações:</strong><br>${quote.notes}</div>` : ''}

          <div class="signatures">
            <div>
              <div class="sig-line">Responsável: ${profile.officeName}</div>
            </div>
            <div>
              <div class="sig-line">Aceite do Cliente</div>
            </div>
          </div>

          <div style="text-align: center; margin-top: 40px; font-size: 8px; color: #ccc;">
            Gerado via Radiant OS 3.1 - ${new Date().toLocaleString()}
          </div>
        </body>
        </html>
      `;
      printWindow.document.write(html);
      printWindow.document.close();
    }
  };

  const sendWhatsAppQuote = (quote: Quote) => {
    const customer = customers.find(c => c.id === quote.customerId);
    const customerPhone = ((quote as any).guestPhone || customer?.phone || '').replace(/\D/g, '');
    if (!customerPhone) return alert("Telefone do cliente não encontrado.");

    let msg = `*📄 ORÇAMENTO - ${profile.officeName}*\n\n`;
    msg += `Olá *${quote.customerName}*! Segue proposta solicitada:\n\n`;
    quote.items.forEach(i => {
      msg += `• ${i.quantity}x ${i.nameAtTime} - R$ ${(i.priceAtTime * i.quantity).toFixed(2)}\n`;
    });
    msg += `\n💰 *TOTAL: R$ ${quote.total.toFixed(2)}*\n`;
    msg += `💳 *Pagamento:* ${quote.paymentMethod} (${quote.installments}x)\n`;
    msg += `🗓️ *Validade:* ${new Date(quote.validUntil).toLocaleDateString('pt-BR')}\n`;
    msg += `🚚 *Prazo:* ${quote.deliveryDeadline}\n\n`;
    msg += `_Ficamos à disposição para dúvidas!_`;

    window.open(`https://wa.me/55${customerPhone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const finalize = async () => {
    if (items.length === 0 || !validUntil) return alert('Selecione itens e validade.');
    if (!selectedCustomerId && !guestData.name) return alert('Identifique o cliente.');

    setIsProcessing(true);
    try {
      const total = items.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const customer = customers.find(c => c.id === selectedCustomerId);

      const quoteData: Partial<Quote> = {
        customerId: selectedCustomerId || 'GUEST',
        customerName: customer?.name || guestData.name.toUpperCase(),
        items,
        total,
        status: 'SENT',
        validUntil,
        notes,
        warranty,
        deliveryDeadline,
        paymentMethod,
        installments
      };

      // Adicionando dados de convidado para persistência
      (quoteData as any).guestName = guestData.name.toUpperCase();
      (quoteData as any).guestPhone = guestData.phone;
      (quoteData as any).guestCpfCnpj = guestData.cpfCnpj;

      await dbService.add('quotes', userId, quoteData);
      setIsCreating(false);
      resetForm();
    } catch (e) { alert('Erro ao salvar.'); } finally { setIsProcessing(false); }
  };

  const resetForm = () => {
    setItems([]);
    setSelectedCustomerId('');
    setGuestData({ name: '', phone: '', cpfCnpj: '' });
    setValidUntil('');
    setDeliveryDeadline('A combinar');
    setWarranty('90 dias');
    setNotes('');
    setPaymentMethod('PIX');
    setInstallments(1);
  };

  return (
    <div className="space-y-12 animate-fade-in pb-24">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-3xl lg:text-5xl font-black text-white italic tracking-tighter text-glow uppercase">Orçamentos</h2>
           <p className="text-slate-500 font-bold text-[10px] uppercase tracking-[0.4em] mt-4 opacity-70">Propostas Profissionais de Rede.</p>
        </div>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-orange px-8 py-4 rounded-2xl flex items-center gap-3 shadow-lg"><Plus /> NOVO ORÇAMENTO</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
          <div className="lg:col-span-2 space-y-6">
            <div className="nexus-card p-8 border-orange-500/20 bg-orange-500/5">
              <h4 className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-6 flex items-center gap-3"><User size={16}/> Identificação do Cliente</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                <input placeholder="Nome ou Razão Social..." value={guestData.name} onChange={e=>setGuestData({...guestData, name: e.target.value})} className="p-4 rounded-xl bg-black border border-white/5 text-white font-bold" />
                <input placeholder="CPF ou CNPJ..." value={guestData.cpfCnpj} onChange={e=>setGuestData({...guestData, cpfCnpj: e.target.value})} className="p-4 rounded-xl bg-black border border-white/5 text-white" />
              </div>
              <input placeholder="WhatsApp (DDD + Número)..." value={guestData.phone} onChange={e=>setGuestData({...guestData, phone: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/5 text-white mb-6" />

              <p className="text-[9px] text-slate-600 font-black mb-4 uppercase text-center">-- OU SELECIONE DA BASE --</p>
              <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full p-4 rounded-xl bg-black border border-white/5 text-white font-bold text-xs">
                  <option value="">Selecione um cliente cadastrado...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name.toUpperCase()}</option>)}
              </select>
            </div>

            <div className="nexus-card p-6 border-white/10">
              <div className="flex flex-wrap gap-4 mb-6">
                <input placeholder="Nome do Serviço ou Produto..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 min-w-[200px] p-4 rounded-xl bg-black border border-white/5 text-white" />
                <input placeholder="R$ 0,00" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-32 p-4 rounded-xl bg-black border border-white/5 text-white" />
                <button onClick={addManualItem} className="bg-orange-500 text-black px-8 rounded-xl font-black hover:bg-orange-400 transition-all"><Plus/></button>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4 max-h-[300px] overflow-y-auto custom-scrollbar">
                {products.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                  <button key={p.id} onClick={() => addItem(p)} className="nexus-card p-5 text-left border-white/5 hover:border-orange-500/50 transition-all">
                     <p className="font-black text-white truncate uppercase mb-1 text-[10px]">{p.name}</p>
                     <p className="text-orange-500 font-black text-sm">R$ {p.price.toFixed(2)}</p>
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="nexus-card p-8 h-fit border-orange-500/30">
            <div className="flex justify-between items-center mb-8 pb-4 border-b border-white/5">
              <h3 className="font-terminal font-black text-orange-500 uppercase tracking-tight">Checkout</h3>
              <button onClick={() => setIsCreating(false)} className="text-slate-500"><X /></button>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-500 uppercase">Validade</label>
                  <input type="date" value={validUntil} onChange={e => setValidUntil(e.target.value)} className="w-full p-4 rounded-xl bg-black border border-white/5 text-white text-xs" />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-500 uppercase">Prazo Entrega</label>
                  <input value={deliveryDeadline} onChange={e => setDeliveryDeadline(e.target.value)} className="w-full p-4 rounded-xl bg-black border border-white/5 text-white text-xs" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-500 uppercase">Garantia</label>
                  <input value={warranty} onChange={e => setWarranty(e.target.value)} className="w-full p-4 rounded-xl bg-black border border-white/5 text-white text-xs" />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-500 uppercase">Forma Pagto</label>
                  <select value={paymentMethod} onChange={e => setPaymentMethod(e.target.value)} className="w-full p-4 rounded-xl bg-black border border-white/5 text-white text-xs">
                    <option>PIX</option>
                    <option>Cartão Crédito</option>
                    <option>Dinheiro</option>
                    <option>Boleto</option>
                  </select>
                </div>
              </div>

              <div className="space-y-3 max-h-[250px] overflow-y-auto custom-scrollbar pr-2">
                {items.map((item, idx) => (
                  <div key={idx} className="bg-white/5 p-4 rounded-xl border border-white/5">
                    <div className="flex justify-between items-center mb-2">
                      <div className="text-[10px] font-black text-white uppercase truncate">{item.nameAtTime}</div>
                      <button onClick={() => setItems(prev => prev.filter((_, i) => i !== idx))} className="text-rose-500"><Trash2 size={12}/></button>
                    </div>
                    <div className="flex justify-between items-center">
                       <div className="flex items-center gap-2">
                          <button onClick={() => updateQty(item.productId, -1)} className="p-1 bg-white/5 rounded text-white"><Minus size={10}/></button>
                          <span className="text-orange-500 font-black text-xs">{item.quantity}</span>
                          <button onClick={() => updateQty(item.productId, 1)} className="p-1 bg-white/5 rounded text-white"><Plus size={10}/></button>
                       </div>
                       <div className="text-white font-black text-xs">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="pt-6 border-t border-white/10">
                <div className="flex justify-between items-end mb-6">
                   <span className="text-slate-500 text-[10px] font-black uppercase">Subtotal</span>
                   <span className="text-3xl font-black text-white italic text-glow">R$ {items.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || items.length === 0} onClick={finalize} className="btn-orange w-full py-5 rounded-2xl flex items-center justify-center gap-3">
                  {isProcessing ? <Loader2 className="animate-spin"/> : <Zap size={18}/>} SALVAR PROPOSTA
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
           {quotes.map(q => {
             const isExpanded = expandedQuoteId === q.id;
             return (
               <div key={q.id} className="nexus-card overflow-hidden border-white/5 hover:border-orange-500/20 transition-all">
                  <div onClick={() => setExpandedQuoteId(isExpanded ? null : q.id)} className="p-8 flex justify-between items-center cursor-pointer hover:bg-white/5 transition-all">
                    <div>
                      <p className="text-[8px] font-mono text-slate-500 uppercase tracking-widest mb-1">PROPOSTA #{q.id.substring(0,8).toUpperCase()}</p>
                      <h4 className="font-black text-white text-2xl uppercase tracking-tight italic">{q.customerName}</h4>
                      <p className="text-[9px] text-slate-600 font-bold uppercase mt-1">Validade: {new Date(q.validUntil).toLocaleDateString('pt-BR')}</p>
                    </div>
                    <div className="flex items-center gap-6">
                       <p className="text-3xl font-black text-orange-500 italic text-glow">R$ {q.total.toFixed(2)}</p>
                       {isExpanded ? <ChevronUp className="text-slate-500"/> : <ChevronDown className="text-slate-500"/>}
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="p-10 bg-black/40 border-t border-white/5 animate-fade-in space-y-10">
                       <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                          <div className="space-y-6">
                             <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                                <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-4 flex items-center gap-2"><User size={14}/> Cliente</h5>
                                <p className="text-white font-black text-lg uppercase">{q.customerName}</p>
                                <p className="text-[10px] text-slate-500 font-bold mt-1">{(q as any).guestPhone || '---'}</p>
                                <p className="text-[9px] text-slate-600 uppercase mt-1">CPF/CNPJ: {(q as any).guestCpfCnpj || '---'}</p>
                             </div>

                             <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                                <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-4 flex items-center gap-2"><ShoppingCart size={14}/> Itens Selecionados</h5>
                                <div className="space-y-3">
                                   {q.items.map((item, idx) => (
                                     <div key={idx} className="flex justify-between text-[11px] p-2 bg-black/20 rounded-lg">
                                        <span className="text-white font-bold">{item.quantity}x {item.nameAtTime}</span>
                                        <span className="text-orange-500 font-black">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</span>
                                     </div>
                                   ))}
                                </div>
                             </div>
                          </div>

                          <div className="space-y-6">
                             <div className="bg-white/5 p-6 rounded-2xl border border-white/10 space-y-4">
                                <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest flex items-center gap-2"><CreditCard size={14}/> Condições</h5>
                                <div className="grid grid-cols-2 gap-4">
                                   <div><p className="text-[9px] text-slate-500 uppercase">Pagamento</p><p className="text-white font-bold text-xs">{q.paymentMethod || 'PIX'}</p></div>
                                   <div><p className="text-[9px] text-slate-500 uppercase">Parcelas</p><p className="text-white font-bold text-xs">{q.installments || 1}x</p></div>
                                   <div><p className="text-[9px] text-slate-500 uppercase">Prazo</p><p className="text-white font-bold text-xs">{q.deliveryDeadline || 'A combinar'}</p></div>
                                   <div><p className="text-[9px] text-slate-500 uppercase">Garantia</p><p className="text-white font-bold text-xs">{q.warranty || '90 dias'}</p></div>
                                </div>
                             </div>
                             <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                                <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest flex items-center gap-2"><ShieldCheck size={14}/> Notas Internas</h5>
                                <p className="text-[11px] text-slate-400 italic leading-relaxed">{q.notes || 'Nenhuma observação extra.'}</p>
                             </div>
                          </div>

                          <div className="flex flex-col justify-end gap-3">
                             <button onClick={() => sendWhatsAppQuote(q)} className="w-full flex items-center justify-center gap-3 bg-emerald-500 text-black p-5 rounded-2xl font-black uppercase text-xs hover:bg-emerald-400 transition-all shadow-lg">
                                <MessageCircle size={20}/> Enviar via WhatsApp
                             </button>
                             <button onClick={() => generatePDFAndShare(q)} className="w-full flex items-center justify-center gap-3 bg-white/5 text-white border border-white/10 p-5 rounded-2xl font-black uppercase text-xs hover:bg-white/10 transition-all">
                                <Download size={20}/> Baixar Proposta PDF
                             </button>
