interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [guestData, setGuestData] = useState({ name: '', phone: '', cpfCnpj: '', address: '' });
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [discount, setDiscount] = useState(0);
  const [entryAmount, setEntryAmount] = useState(0);
  const [notes, setNotes] = useState('');
  const [warranty, setWarranty] = useState('90 dias');
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1' });
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);

  useEffect(() => {
    if (selectedCustomerId) {
      const c = customers.find(cust => cust.id === selectedCustomerId);
      if (c) setGuestData({ 
        name: c.name, 
        phone: c.phone || '', 
        cpfCnpj: c.cpfCnpj || '', 
        address: c.address || '' 
      });
    } else {
      setGuestData({ name: '', phone: '', cpfCnpj: '', address: '' });
    }
  }, [selectedCustomerId, customers]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type as any }];
    });
  };

  const addManualToCart = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha dados do item.");
    setCart(prev => [...prev, {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: 'PRODUCT'
    }]);
    setManualItem({ name: '', price: '', qty: '1' });
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Carrinho vazio.');
    setIsProcessing(true);
    try {
      const subtotal = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const total = subtotal - discount;
      const amountToFinance = total - entryAmount;

      const installmentDetails: Installment[] = Array.from({ length: installments }).map((_, idx) => {
        const dueDate = new Date();
        dueDate.setMonth(dueDate.getMonth() + idx + 1);
        return {
          id: `inst-${Date.now()}-${idx}`,
          value: amountToFinance / installments,
          status: 'PENDING',
          dueDate: Timestamp.fromDate(dueDate)
        };
      });

      const orderData: any = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        discount,
        entryAmount,
        status: 'PAID',
        paymentMethod,
        installments,
        installmentDetails,
        guestName: guestData.name.toUpperCase() || 'VENDA RÁPIDA',
        guestPhone: guestData.phone,
        guestCpfCnpj: guestData.cpfCnpj,
        guestAddress: guestData.address,
        notes,
        warranty
      };

      await dbService.add('orders', userId, orderData);
      setCart([]);
      setIsCreating(false);
      resetSaleForm();
    } catch (e) { alert('Falha ao processar.'); } finally { setIsProcessing(false); }
  };

  const resetSaleForm = () => {
    setSelectedCustomerId('');
    setGuestData({ name: '', phone: '', cpfCnpj: '', address: '' });
    setInstallments(1);
    setDiscount(0);
    setEntryAmount(0);
    setNotes('');
    setWarranty('90 dias');
