                ${(order.installmentDetails || []).map((inst, idx) => `
                  <tr>
                    <td>Parcela ${idx + 1}</td>
                    <td>${inst.dueDate?.toDate ? inst.dueDate.toDate().toLocaleDateString('pt-BR') : '---'}</td>
                    <td>R$ ${inst.value.toFixed(2)}</td>
                    <td>${inst.status === 'PAID' ? '✅ Pago' : '⏳ Pendente'}</td>
                  </tr>
                `).join('')}
                ${(order.installmentDetails || []).length === 0 ? '<tr><td colspan="4" style="text-align:center">Pagamento à Vista</td></tr>' : ''}
              </tbody>
            </table>
          </div>

          <div class="totals-box">
             <div class="total-item"><span class="label">Valor Bruto</span><strong>R$ ${(order.total + (order.discount || 0)).toFixed(2)}</strong></div>
             <div class="total-item"><span class="label">Desconto</span><strong>R$ ${(order.discount || 0).toFixed(2)}</strong></div>
             <div class="total-item highlight"><span class="label">Total Geral</span><strong>R$ ${order.total.toFixed(2)}</strong></div>
             <div class="total-item"><span class="label">Entrada</span><strong>R$ ${(order.entryAmount || 0).toFixed(2)}</strong></div>
             <div class="total-item"><span class="label">Total Pago</span><strong>R$ ${paidValue.toFixed(2)}</strong></div>
             <div class="total-item"><span class="label">Saldo em Aberto</span><strong>R$ ${openValue.toFixed(2)}</strong></div>
          </div>

          <div class="section" style="margin-top: 20px;">
            <div class="section-title">Observações e Garantia</div>
            <div style="padding: 12px; font-size: 10px;">
              <p><strong>Garantia:</strong> ${order.warranty || '90 dias'}</p>
              <p>${order.notes || 'Nenhuma observação extra.'}</p>
            </div>
          </div>

          <div style="margin-top: 40px; display: grid; grid-template-columns: 1fr 1fr; gap: 50px; text-align: center;">
            <div style="border-top: 1px solid #000; padding-top: 5px;">Assinatura do Cliente</div>
            <div style="border-top: 1px solid #000; padding-top: 5px;">Carimbo / Assinatura Vendedor</div>
          </div>

          <div class="footer">Gerado via Profissional OS 3.1 - ${new Date().toLocaleString()}</div>
        </body>
        </html>
      `;
      printWindow.document.write(html);
      printWindow.document.close();
    }
  };

  const sendInstallmentReminder = (order: Order, inst: Installment, index: number) => {
    const phone = order.guestPhone?.replace(/\D/g, '');
    if (!phone) return alert("Telefone do cliente não encontrado.");

    const dueDate = inst.dueDate?.toDate ? inst.dueDate.toDate().toLocaleDateString('pt-BR') : 'A combinar';
    const msg = encodeURIComponent(
      `Olá *${order.guestName}*! 👋\n\n` +
      `Lembrando da sua parcela nº *${index + 1}* referente à sua compra conosco.\n\n` +
      `💰 *Valor:* R$ ${inst.value.toFixed(2)}\n` +
      `📅 *Vencimento:* ${dueDate}\n\n` +
      `Qualquer dúvida, estamos à disposição no ${profile.officeName}.\n` +
      `_Sincronizado via Profissional OS_`
    );
    window.open(`https://wa.me/55${phone}?text=${msg}`, '_blank');
  };

  const updateInstallment = async (order: Order, instId: string, updates: Partial<Installment>) => {
    const newDetails = order.installmentDetails?.map(inst => 
      inst.id === instId ? { ...inst, ...updates } : inst
    );
    await dbService.update('orders', order.id, { installmentDetails: newDetails });
  };

  const removeInstallment = async (order: Order, instId: string) => {
    if(!confirm("Deseja excluir esta parcela? O valor total da nota não será alterado automaticamente.")) return;
    const newDetails = order.installmentDetails?.filter(inst => inst.id !== instId);
    await dbService.update('orders', order.id, { installmentDetails: newDetails });
  };

  const currentTotal = cart.reduce((s,i) => s + (i.priceAtTime * i.quantity), 0);
  const finalTotal = currentTotal - discount;
  const balanceToPay = finalTotal - entryAmount;

  return (
    <div className="space-y-8 animate-fade-in pb-20 px-2 lg:px-0">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl lg:text-4xl font-black text-slate-900 italic tracking-tighter uppercase">Vendas e Notas</h2>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Terminal de Saídas Profissional</p>
        </div>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-primary px-8 py-4 rounded-xl flex items-center gap-2"><Plus size={20}/> NOVA VENDA</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="nexus-card p-6 bg-slate-50 border-slate-200">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><ShoppingCart size={14}/> Carrinho de Itens</h4>
              <div className="flex gap-2 mb-6">
                <input placeholder="Produto ou Serviço..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 p-4 rounded-xl border border-slate-200 text-sm font-bold" />
                <input placeholder="R$" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-24 p-4 rounded-xl border border-slate-200 text-sm font-bold" />
                <button onClick={addManualToCart} className="bg-slate-900 text-white px-6 rounded-xl font-bold"><Plus/></button>
              </div>
              <div className="bg-white p-3 rounded-xl border border-slate-100 flex items-center gap-3 mb-6">
                <Search className="text-slate-300" size={18}/>
                <input placeholder="Procurar no catálogo..." className="bg-transparent flex-1 outline-none text-slate-900 font-bold text-sm" value={search} onChange={e => setSearch(e.target.value)} />
              </div>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3 max-h-[350px] overflow-y-auto pr-1 custom-scrollbar">
                {products.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                  <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-4 rounded-xl border border-slate-100 text-left hover:border-orange-500 transition-all shadow-sm">
                     <p className="font-bold text-slate-900 text-[10px] truncate uppercase">{p.name}</p>
                     <p className="text-orange-600 font-black text-xs mt-1">R$ {p.price.toFixed(2)}</p>
                  </button>
                ))}
              </div>
            </div>

            <div className="nexus-card p-6 border-slate-200">
               <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><User size={14}/> Dados do Cliente para a Nota</h4>
               <div className="space-y-4">
                  <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold uppercase bg-slate-50">
                    <option value="">-- SELECIONAR CLIENTE CADASTRADO --</option>
                    {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input placeholder="NOME COMPLETO" value={guestData.name} onChange={e => setGuestData({...guestData, name: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold uppercase" />
                    <input placeholder="CPF / CNPJ" value={guestData.cpfCnpj} onChange={e => setGuestData({...guestData, cpfCnpj: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold uppercase" />
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input placeholder="WHATSAPP (COM DDD)" value={guestData.phone} onChange={e => setGuestData({...guestData, phone: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold" />
                    <input placeholder="ENDEREÇO COMPLETO" value={guestData.address} onChange={e => setGuestData({...guestData, address: e.target.value})} className="w-full p-4 rounded-xl border border-slate-200 text-xs font-bold uppercase" />
                  </div>
               </div>
            </div>
          </div>

          <div className="space-y-6">
            <div className="nexus-card p-6 border-slate-900 bg-slate-900 text-white">
              <h3 className="text-xs font-black uppercase tracking-widest mb-6 flex justify-between items-center">Resumo Financeiro <X className="cursor-pointer opacity-50" onClick={()=>setIsCreating(false)}/></h3>
              <div className="space-y-4">
                 <div className="flex justify-between text-[10px] font-bold uppercase text-slate-400"><span>Subtotal Bruto</span><span>R$ {currentTotal.toFixed(2)}</span></div>
                 <div className="space-y-1">
                   <label className="text-[8px] font-black uppercase text-slate-500">Desconto R$</label>
                   <input type="number" value={discount} onChange={e => setDiscount(parseFloat(e.target.value || '0'))} className="w-full p-3 rounded-lg bg-white/10 border border-white/10 text-white font-bold" />
                 </div>
                 <div className="space-y-1">
                   <label className="text-[8px] font-black uppercase text-slate-500">Entrada R$</label>
                   <input type="number" value={entryAmount} onChange={e => setEntryAmount(parseFloat(e.target.value || '0'))} className="w-full p-3 rounded-lg bg-white/10 border border-white/10 text-white font-bold" />
                 </div>
                 <div className="pt-4 border-t border-white/10 flex justify-between items-center">
                    <span className="text-xs font-black uppercase tracking-widest">Total Líquido</span>
                    <span className="text-2xl font-black text-orange-500 italic">R$ {finalTotal.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between text-[10px] font-bold uppercase text-slate-400"><span>Saldo Restante</span><span>R$ {balanceToPay.toFixed(2)}</span></div>
              </div>
            </div>

            <div className="nexus-card p-6 border-slate-200 space-y-4">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Condições e Parcelas</h4>
              <div className="grid grid-cols-2 gap-2">
                <div className="space-y-1">
                  <label className="text-[8px] font-black text-slate-500 uppercase">Pagamento</label>
                  <select value={paymentMethod} onChange={e => setPaymentMethod(e.target.value as any)} className="w-full p-3 rounded-xl text-xs font-bold border border-slate-200 bg-slate-50">
                    <option value="PIX">PIX</option>
                    <option value="CREDIT_CARD">CARTÃO CRÉDITO</option>
                    <option value="CASH">DINHEIRO</option>
                    <option value="DEFERRED">CREDIÁRIO / PARCELADO</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[8px] font-black text-slate-500 uppercase">Qtd Parcelas</label>
                  <select value={installments} onChange={e => setInstallments(parseInt(e.target.value))} className="w-full p-3 rounded-xl text-xs font-bold border border-slate-200 bg-slate-50">
                    {[1,2,3,4,5,6,10,12,24,36].map(n => <option key={n} value={n}>{n}x</option>)}
                  </select>
                </div>
              </div>
              <input placeholder="GARANTIA (EX: 90 DIAS)" value={warranty} onChange={e=>setWarranty(e.target.value)} className="w-full p-3 rounded-xl border border-slate-200 text-[10px] font-bold uppercase" />
              <textarea placeholder="OBSERVAÇÕES DA NOTA..." value={notes} onChange={e=>setNotes(e.target.value)} className="w-full p-3 rounded-xl border border-slate-200 text-[10px] font-bold uppercase h-20 resize-none" />

              <button disabled={isProcessing || cart.length === 0} onClick={finalize} className="btn-primary w-full py-5 rounded-xl font-bold flex items-center justify-center gap-3 mt-4">
                {isProcessing ? <Loader2 className="animate-spin"/> : <Zap size={18}/>} CONCLUIR E GERAR NOTA
              </button>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
           {orders.map(o => {
             const isExpanded = expandedOrderId === o.id;
             const totalPaid = (o.entryAmount || 0) + (o.installmentDetails?.filter(i => i.status === 'PAID').reduce((s, i) => s + i.value, 0) || 0);
             const openValue = o.total - totalPaid;
             const hasOverdue = o.installmentDetails?.some(i => i.status === 'PENDING' && i.dueDate?.toDate() < new Date());

             return (
               <div key={o.id} className="nexus-card overflow-hidden border-slate-100 group">
                  <div onClick={() => setExpandedOrderId(isExpanded ? null : o.id)} className="p-6 flex justify-between items-center cursor-pointer hover:bg-slate-50 transition-colors">
                    <div>
                      <p className="text-[8px] font-mono text-slate-400 uppercase tracking-widest">NOTA #{o.id.substring(0,8).toUpperCase()} • {o.createdAt?.toDate ? o.createdAt.toDate().toLocaleDateString('pt-BR') : 'Agora'}</p>
                      <div className="flex items-center gap-4 mt-1">
                        <h4 className="text-xl font-bold text-slate-900 uppercase tracking-tight">{o.guestName}</h4>
                        {hasOverdue && <span className="bg-rose-50 text-rose-500 px-2 py-0.5 rounded text-[8px] font-black uppercase">Vencida</span>}
                      </div>
                    </div>
                    <div className="flex items-center gap-8">
                       <div className="text-right">
                          <p className="text-[8px] font-black text-slate-400 uppercase">Valor Líquido</p>
                          <p className="text-2xl font-black text-slate-900 italic">R$ {o.total.toFixed(2)}</p>
                       </div>
                       {isExpanded ? <ChevronUp className="text-slate-300"/> : <ChevronDown className="text-slate-300"/>}
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="p-8 bg-slate-50 border-t border-slate-200 animate-fade-in space-y-8">
                       <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                          <div className="bg-white p-5 rounded-2xl border border-slate-200 text-center">
                             <p className="text-[8px] font-black text-slate-400 uppercase">Total Nota</p>
                             <p className="text-xl font-black text-slate-900">R$ {o.total.toFixed(2)}</p>
                          </div>
                          <div className="bg-white p-5 rounded-2xl border border-slate-200 text-center">
                             <p className="text-[8px] font-black text-emerald-500 uppercase">Total Pago</p>
                             <p className="text-xl font-black text-emerald-600">R$ {totalPaid.toFixed(2)}</p>
                          </div>
                          <div className="bg-white p-5 rounded-2xl border border-slate-200 text-center">
                             <p className="text-[8px] font-black text-orange-500 uppercase">Em Aberto</p>
                             <p className="text-xl font-black text-orange-600">R$ {openValue.toFixed(2)}</p>
                          </div>
                          <div className="flex gap-2">
                             <button onClick={() => generateReceipt(o)} className="flex-1 bg-slate-900 text-white rounded-2xl font-bold flex flex-col items-center justify-center gap-2 hover:bg-slate-800 transition-all"><Printer size={20}/> <span className="text-[8px] uppercase">Imprimir Nota</span></button>
                             <button onClick={() => { if(confirm('Deseja excluir permanentemente este registro de venda?')) dbService.del('orders', o.id); }} className="p-5 bg-rose-50 text-rose-500 rounded-2xl border border-rose-100 hover:bg-rose-500 hover:text-white transition-all"><Trash2 size={20}/></button>
                          </div>
                       </div>

                       <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                          <div className="space-y-4">
                             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><CreditCard size={14}/> Controle de Recebimentos</h4>
                             <div className="space-y-3">
                                {(o.installmentDetails || []).map((inst, idx) => (
                                  <div key={inst.id} className="bg-white p-4 rounded-xl border border-slate-200 flex items-center justify-between">
                                     <div>
                                        <p className="text-[9px] font-black text-slate-500 uppercase">Parcela {idx + 1} • {inst.dueDate?.toDate ? inst.dueDate.toDate().toLocaleDateString('pt-BR') : '---'}</p>
                                        <p className="text-lg font-black text-slate-900">R$ {inst.value.toFixed(2)}</p>
                                     </div>
                                     <div className="flex gap-2">
                                        <button onClick={() => sendInstallmentReminder(o, inst, idx)} className="p-2.5 bg-emerald-50 text-emerald-600 rounded-lg hover:bg-emerald-600 hover:text-white transition-all" title="Cobrar WhatsApp"><MessageCircle size={16}/></button>
                                        <button onClick={() => updateInstallment(o, inst.id, { status: inst.status === 'PAID' ? 'PENDING' : 'PAID' })} className={`p-2.5 rounded-lg border font-bold text-[10px] uppercase transition-all ${inst.status === 'PAID' ? 'bg-emerald-500 text-white border-emerald-500' : 'bg-slate-100 text-slate-400 border-slate-200'}`}>
                                          {inst.status === 'PAID' ? 'PAGO' : 'PENDENTE'}
                                        </button>
                                        <button onClick={() => removeInstallment(o, inst.id)} className="p-2.5 text-slate-300 hover:text-rose-500 transition-all"><Trash2 size={16}/></button>
                                     </div>
                                  </div>
                                ))}
                                {(o.installmentDetails || []).length === 0 && <p className="text-center text-[10px] font-bold text-slate-300 uppercase py-6 border-2 border-dashed border-slate-200 rounded-xl">Venda finalizada à vista.</p>}
                             </div>
                          </div>

                          <div className="space-y-6">
                             <div className="bg-white p-6 rounded-2xl border border-slate-200">
                                <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><FileText size={14}/> Detalhes da Operação</h5>
                                <div className="space-y-3">
                                   {o.items.map((item, idx) => (
                                     <div key={idx} className="flex justify-between text-xs font-bold border-b border-slate-50 pb-2">
                                        <span className="text-slate-900">{item.quantity}x {item.nameAtTime}</span>
                                        <span className="text-slate-400">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</span>
                                     </div>
                                   ))}
                                </div>
                                <div className="mt-4 pt-4 border-t border-slate-100 space-y-2">
                                   <p className="text-[10px] text-slate-500 uppercase"><strong>Garantia:</strong> {o.warranty || '90 dias'}</p>
                                   <p className="text-[10px] text-slate-500 uppercase"><strong>Notas:</strong> {o.notes || '---'}</p>
                                </div>
                             </div>
                             <div className="bg-orange-50 p-6 rounded-2xl border border-orange-100 flex items-center gap-6">
                                <div className="w-12 h-12 bg-orange-500 rounded-xl flex items-center justify-center text-white"><Wallet size={24}/></div>
                                <div>
                                   <p className="text-[10px] font-black text-orange-600 uppercase">Histórico Financeiro</p>
                                   <p className="text-xs text-orange-800 leading-tight mt-1 font-bold">Venda realizada via {o.paymentMethod}. Entrada de R$ {(o.entryAmount || 0).toFixed(2)} e desconto de R$ {(o.discount || 0).toFixed(2)} aplicado.</p>
                                </div>
                             </div>
                          </div>
                       </div>
                    </div>
                  )}
               </div>
             );
           })}
        </div>
      )}
    </div>
  );
};

