                    <option value="pt-BR">Português (Brasil)</option>
                    <option value="en">English (US)</option>
                    <option value="es">Español</option>
                  </select>
                </div>

                <div className="space-y-4">
                  <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2"><Zap size={14}/> Tema Visual</h4>
                  <div className="flex gap-2">
                    <button onClick={()=>setPrefData({...prefData, theme: 'light'})} className={`flex-1 p-4 rounded-xl border font-bold text-xs uppercase ${prefData.theme === 'light' ? 'bg-orange-500 text-white border-orange-500' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>Claro</button>
                    <button onClick={()=>setPrefData({...prefData, theme: 'dark'})} className={`flex-1 p-4 rounded-xl border font-bold text-xs uppercase ${prefData.theme === 'dark' ? 'bg-slate-900 text-white border-slate-900' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>Escuro</button>
                  </div>
                </div>
              </div>

              <div className="pt-8 border-t border-slate-100 space-y-6">
                <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2"><Bell size={14}/> Central de Notificações</h4>
                <div className="space-y-4">
                  {[
                    { key: 'notifEmail', label: 'Alertas por E-mail' },
                    { key: 'notifWA', label: 'Relatórios por WhatsApp' },
                    { key: 'notifSys', label: 'Push no Terminal' }
                  ].map(n => (
                    <div key={n.key} className="flex justify-between items-center p-4 bg-slate-50 rounded-xl border border-slate-100">
                      <span className="text-[10px] font-bold text-slate-700 uppercase tracking-widest">{n.label}</span>
                      <div 
                        onClick={() => setPrefData({...prefData, [n.key]: !((prefData as any)[n.key])})}
                        className={`w-12 h-6 rounded-full p-1 cursor-pointer transition-all ${((prefData as any)[n.key]) ? 'bg-emerald-500' : 'bg-slate-300'}`}
                      >
                         <div className={`w-4 h-4 bg-white rounded-full transition-all ${((prefData as any)[n.key]) ? 'ml-6' : 'ml-0'}`} />
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <button disabled={isSaving} onClick={() => handleUpdateProfile({ settings: prefData })} className="btn-orange px-8 py-4 rounded-xl font-bold text-xs flex items-center gap-3">
                {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />} SALVAR PREFERÊNCIAS
              </button>
            </div>
          )}

          {activeTab === 'DOCUMENTS' && (
            <div className="nexus-card p-8 space-y-8">
              <div className="flex justify-between items-center">
                <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2"><FileText size={14}/> Gestão de Documentos</h4>
                <label className="bg-slate-900 text-white px-6 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest cursor-pointer hover:bg-slate-800 flex items-center gap-2">
                  <FileUp size={14}/> Upload Arquivo
                  <input type="file" className="hidden" onChange={(e) => handleFileUpload(e, 'DOC')} />
                </label>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {(profile.documents || []).map(doc => (
                  <div key={doc.id} className="p-4 bg-slate-50 border border-slate-100 rounded-xl flex items-center justify-between group">
                    <div className="flex items-center gap-4">
                      <div className="p-2.5 bg-white border border-slate-100 rounded-lg text-orange-500"><FileText size={20}/></div>
                      <div>
                        <p className="text-xs font-bold text-slate-900 truncate w-32 md:w-48">{doc.name}</p>
                        <p className="text-[9px] text-slate-400 font-bold uppercase mt-0.5">{doc.type.split('/')[1] || 'DOC'}</p>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <a href={doc.url} download={doc.name} className="p-2 text-slate-300 hover:text-slate-900 transition-all"><ExternalLink size={16}/></a>
                      <button onClick={() => {
                        const docs = profile.documents?.filter(d => d.id !== doc.id);
                        dbService.updateProfile(profile.uid, { documents: docs });
                      }} className="p-2 text-slate-300 hover:text-rose-500 transition-all"><Trash2 size={16}/></button>
                    </div>
                  </div>
                ))}
                {(profile.documents || []).length === 0 && (
                  <div className="col-span-full py-12 text-center border-2 border-dashed border-slate-100 rounded-2xl">
                    <p className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">Nenhum contrato ou relatório arquivado.</p>
                  </div>
                )}
              </div>
            </div>
          )}

          {activeTab === 'HISTORY' && (
            <div className="nexus-card p-8 space-y-6">
              <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2"><History size={14}/> Logs de Atividade</h4>
              <div className="space-y-3">
                {(profile.activityLogs || []).map(log => (
                  <div key={log.id} className="flex justify-between items-center p-4 bg-slate-50 border border-slate-100 rounded-xl">
                    <div>
                      <p className="text-xs font-bold text-slate-900">{log.action}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">{log.details || 'Sem detalhes'}</p>
                    </div>
                    <p className="text-[9px] font-bold text-slate-400 uppercase">{log.timestamp?.toDate ? log.timestamp.toDate().toLocaleString('pt-BR') : new Date(log.timestamp).toLocaleString()}</p>
                  </div>
                ))}
                {(profile.activityLogs || []).length === 0 && <p className="text-center py-10 text-[10px] font-bold text-slate-300 uppercase tracking-widest">Nenhuma atividade registrada.</p>}
              </div>
            </div>
          )}
        </div>

        <aside className="space-y-6">
          <div className="nexus-card p-6 border-orange-100 bg-orange-50/50">
            <h5 className="text-[10px] font-black text-orange-600 uppercase tracking-widest mb-4 flex items-center gap-2"><ShieldCheck size={14}/> Status de Acesso</h5>
            <div className="space-y-3">
               <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase"><span>Status</span><span className="text-emerald-500">OPERACIONAL</span></div>
               <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase"><span>Assinatura</span><span className="text-slate-900">{profile.subscriptionStatus}</span></div>
               <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase"><span>Expira</span><span className="text-slate-900">{profile.subscriptionExpiresAt?.toDate().toLocaleDateString('pt-BR')}</span></div>
            </div>
          </div>

          <div className="nexus-card p-6 border-slate-900 bg-slate-900 text-white">
             <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><Cpu size={14}/> Terminal Core</h5>
             <p className="text-[9px] text-slate-500 leading-relaxed font-bold uppercase tracking-wider mb-4">Sincronização Cloud com Profissional OS v3.1 ativa em tempo real.</p>
             <button onClick={() => auth.signOut()} className="w-full py-4 rounded-xl border border-white/10 text-[10px] font-bold uppercase tracking-widest hover:bg-white/5 transition-all">Sair do Terminal</button>
          </div>

          {message.text && (
            <div className={`p-4 rounded-xl text-[9px] font-black uppercase text-center border animate-fade ${message.type === 'error' ? 'bg-red-50 text-red-500 border-red-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>
              {message.text}
            </div>
          )}
        </aside>
      </main>
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect } from 'react';
import { dbService, Timestamp } from '../services/firebase';
import { UserProfile } from '../types';
import { 
  Building2, Ban, Trash2, Search, DollarSign, Clock, ShieldAlert, Eraser, 
  Loader2, Zap, CheckCircle, MessageCircle, ChevronRight, Users, Star
} from 'lucide-react';

interface OfficeManagementProps {
  superAdminProfile: UserProfile;
}

const OfficeManagement: React.FC<OfficeManagementProps> = ({ superAdminProfile }) => {
  const [offices, setOffices] = useState<UserProfile[]>([]);
  const [selectedOffice, setSelectedOffice] = useState<UserProfile | null>(null);
  const [isWiping, setIsWiping] = useState(false);

  useEffect(() => {
    const unsub = dbService.watchNetwork((data) => {
      setOffices(data as UserProfile[]);
    });
    return () => unsub();
  }, []);

  const getL1 = () => offices.filter(o => o.lineage?.l1 === superAdminProfile.uid);
  const getL2 = (l1Id: string) => offices.filter(o => o.lineage?.l2 === superAdminProfile.uid && o.referredBy === l1Id);
  const getL3 = (l2Id: string) => offices.filter(o => o.lineage?.l3 === superAdminProfile.uid && o.referredBy === l2Id);

  const handleConfirmPayment = async (uid: string) => {
    const nextExpiry = new Date();
    nextExpiry.setDate(nextExpiry.getDate() + 30);
    await dbService.update('users', uid, { 
      subscriptionStatus: 'PAID',
      status: 'active',
      subscriptionExpiresAt: Timestamp.fromDate(nextExpiry)
    });
    alert("Terminal Renovado!");
  };

  const handleToggleBlock = async (uid: string, currentStatus: string) => {
    const nextStatus = currentStatus === 'active' ? 'blocked' : 'active';
    await dbService.update('users', uid, { status: nextStatus });
  };

  const handleSendReminder = (office: UserProfile) => {
    const phone = office.phone?.replace(/\D/g, '');
    if (!phone) return alert("WhatsApp não cadastrado.");
    const msg = encodeURIComponent(`Olá ${office.officeName}! Seu terminal Nexus OS está próximo do vencimento. Regularize via PIX: ${superAdminProfile.pixKey || superAdminProfile.email}`);
    window.open(`https://wa.me/55${phone}?text=${msg}`, '_blank');
  };

  const OfficeNode = ({ office, label, sublabel, size = "md" }: { office: UserProfile, label: string, sublabel: string, size?: "lg" | "md" | "sm" }) => (
    <div className="flex flex-col items-center group animate-fade-in relative z-10">
      <div 
        onClick={() => setSelectedOffice(office)}
        className={`cursor-pointer transition-all duration-300 hover:scale-110 flex flex-col items-center ${size === 'lg' ? 'scale-110' : size === 'sm' ? 'scale-90' : ''}`}
      >
        <div className={`rounded-xl shadow-2xl flex items-center justify-center border-2 border-white/20 bg-gradient-to-b from-blue-400 to-blue-600 p-4 mb-2 ${size === 'lg' ? 'w-24 h-24' : 'w-16 h-16'}`}>
          <Building2 size={size === 'lg' ? 48 : 32} className="text-white drop-shadow-lg" />
        </div>
        <div className="bg-gradient-to-r from-amber-300 via-amber-400 to-amber-500 px-4 py-1 rounded-md shadow-lg border border-amber-200 min-w-[120px] text-center">
           <p className="text-[10px] font-black text-blue-900 uppercase truncate leading-tight">{label}</p>
        </div>
        <div className="mt-1 bg-blue-800/80 backdrop-blur-sm px-3 py-0.5 rounded border border-blue-400/30">
           <p className="text-[8px] font-bold text-blue-100 uppercase tracking-tighter whitespace-nowrap">{sublabel}</p>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#003399] rounded-[2.5rem] overflow-hidden shadow-2xl relative">
      {/* Background Decorativo Estilo Imagem */}
      <div className="absolute inset-0 bg-gradient-to-b from-blue-500/20 via-transparent to-blue-900/40 pointer-events-none"></div>
      <div className="absolute bottom-0 left-0 right-0 h-64 bg-gradient-to-t from-[#001a4d] to-transparent opacity-50 pointer-events-none"></div>

      <header className="relative z-20 p-10 text-center">
        <div className="flex items-center justify-center gap-4 mb-2">
          <div className="h-px w-20 bg-white/20"></div>
          <h2 className="text-5xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">Nosso Time</h2>
          <div className="h-px w-20 bg-white/20"></div>
        </div>
        <p className="text-blue-200 font-bold text-xs uppercase tracking-[0.4em] opacity-80">Estrutura Global de Terminais Nexus</p>
      </header>

      <main className="relative z-20 pb-40 px-4 overflow-x-auto custom-scrollbar">
        <div className="min-w-[1000px] flex flex-col items-center">

          {/* ROOT: Super Admin (Escritório Líder) */}
          <section className="mb-20">
            <OfficeNode 
              office={superAdminProfile} 
              label="Escritório Líder" 
              sublabel="VOCÊ (MASTER)" 
              size="lg" 
            />
          </section>

          {/* NÍVEL 1: Indicados Diretos */}
          <div className="relative w-full flex justify-center gap-24 mb-20">
            {/* Linhas Conectoras L1 */}
            <div className="absolute top-[-40px] left-1/2 -translate-x-1/2 w-4/5 h-10 border-t-2 border-x-2 border-white/30 rounded-t-[3rem]"></div>

            {getL1().length > 0 ? getL1().map(l1 => (
              <div key={l1.uid} className="flex flex-col items-center relative">
                <div className="absolute top-[-40px] left-1/2 -translate-x-1/2 w-px h-10 bg-white/30"></div>
                <OfficeNode office={l1} label={l1.officeName} sublabel="SEU INDICADO DIRETO" />

                {/* NÍVEL 2: Sob cada L1 */}
                <div className="flex gap-8 mt-16 relative">
                   {getL2(l1.uid).length > 0 && (
                     <>
                        <div className="absolute top-[-32px] left-0 right-0 h-8 border-t-2 border-white/20"></div>
                        {getL2(l1.uid).map(l2 => (
                          <div key={l2.uid} className="flex flex-col items-center relative">
                            <div className="absolute top-[-32px] left-1/2 -translate-x-1/2 w-px h-8 bg-white/20"></div>
                            <OfficeNode office={l2} label={l2.officeName} sublabel="NÍVEL 2" size="sm" />

                            {/* NÍVEL 3: Sob cada L2 */}
                            <div className="flex gap-4 mt-12 relative">
                               {getL3(l2.uid).map(l3 => (
                                 <div key={l3.uid} className="flex flex-col items-center relative">
                                   <div className="absolute top-[-24px] left-1/2 -translate-x-1/2 w-px h-6 bg-white/10"></div>
                                   <OfficeNode office={l3} label={l3.officeName} sublabel="NÍVEL 3" size="sm" />
                                 </div>
                               ))}
                            </div>
                          </div>
                        ))}
                     </>
                   )}
                </div>
              </div>
            )) : (
              <div className="py-10 text-white/40 font-black uppercase text-[10px] tracking-widest bg-white/5 px-10 rounded-2xl border border-white/5">Aguardando Expansão de Rede</div>
            )}
          </div>
        </div>
      </main>

      {/* Painel de Controle Flutuante ao Selecionar */}
      {selectedOffice && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-50 w-full max-w-4xl px-4 animate-fade-in-up">
           <div className="bg-white rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.5)] p-8 border-t-4 border-amber-400">
              <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                 <div className="flex items-center gap-6">
                    <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center border border-blue-100">
                       <Building2 size={32}/>
                    </div>
                    <div>
                       <h4 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">{selectedOffice.officeName}</h4>
                       <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{selectedOffice.email}</p>
                       <div className="flex items-center gap-3 mt-1">
                          <span className={`px-3 py-0.5 rounded text-[8px] font-black uppercase ${selectedOffice.subscriptionStatus === 'PAID' ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-black'}`}>
                             {selectedOffice.subscriptionStatus}
                          </span>
                          <p className="text-[9px] font-bold text-blue-600">Expira: {selectedOffice.subscriptionExpiresAt?.toDate().toLocaleDateString('pt-BR')}</p>
                       </div>
                    </div>
                 </div>

                 <div className="flex flex-wrap justify-center gap-2">
                    <button onClick={() => handleSendReminder(selectedOffice)} className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl hover:bg-emerald-500 hover:text-white transition-all shadow-sm" title="WhatsApp"><MessageCircle size={20}/></button>
                    <button onClick={() => handleConfirmPayment(selectedOffice.uid)} className="px-6 py-4 bg-emerald-500 text-white rounded-2xl font-black text-[10px] uppercase shadow-lg hover:bg-emerald-400 transition-all flex items-center gap-2"><CheckCircle size={16}/> Renovar 30D</button>
                    <button onClick={() => handleToggleBlock(selectedOffice.uid, selectedOffice.status)} className={`px-6 py-4 rounded-2xl font-black text-[10px] uppercase transition-all ${selectedOffice.status === 'active' ? 'bg-amber-100 text-amber-600 hover:bg-amber-600 hover:text-white' : 'bg-blue-600 text-white hover:bg-blue-500'}`}>{selectedOffice.status === 'active' ? 'Bloquear' : 'Desbloquear'}</button>
                    <button onClick={() => { if(confirm('Excluir definitivo?')) dbService.del('users', selectedOffice.uid); setSelectedOffice(null); }} className="p-4 bg-rose-50 text-rose-500 rounded-2xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 size={20}/></button>
                    <button onClick={() => setSelectedOffice(null)} className="p-4 bg-slate-100 text-slate-400 rounded-2xl hover:bg-slate-200 transition-all"><X size={20}/></button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Widget de Busca e Limpeza */}
      <div className="fixed top-10 right-10 z-40 flex gap-4">
          <div className="bg-white/10 backdrop-blur-md p-2 rounded-full border border-white/20 flex items-center px-6">
            <Search size={18} className="text-white/50" />
            <input 
              placeholder="Buscar escritório..." 
              className="bg-transparent border-0 outline-none p-2 text-white font-bold text-xs w-40 placeholder:text-white/30 uppercase"
              onChange={(e) => {
                const found = offices.find(o => o.officeName.toLowerCase().includes(e.target.value.toLowerCase()));
                if(found && e.target.value.length > 2) setSelectedOffice(found);
              }}
            />
          </div>
          <button 
            onClick={async () => {
              if(confirm('Limpar todos os terminais em TRIAL agora?')) {
                setIsWiping(true);
                const trials = offices.filter(o => o.subscriptionStatus === 'TRIAL' && o.email !== superAdminProfile.email);
                await Promise.all(trials.map(t => dbService.del('users', t.uid)));
                setIsWiping(false);
              }
            }}
            className="w-12 h-12 bg-rose-500 text-white rounded-full flex items-center justify-center shadow-xl hover:rotate-12 transition-all"
            title="Limpar Trials"
          >
            {isWiping ? <Loader2 className="animate-spin" size={20}/> : <Eraser size={20}/>}
          </button>
      </div>
    </div>
  );
};

