  items: OrderItem[];
  total: number;
  subtotal: number;
  discount: number;
  status: 'PAID' | 'PENDING' | 'CANCELLED';
  paymentMethod: 'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED' | 'BOLETO';
  installments?: number;
  installmentDetails?: Installment[];
  guestName: string;
  guestPhone?: string;
  guestCpfCnpj?: string;
  guestAddress?: string;
  entryAmount?: number;
  notes?: string;
  warranty?: string;
  createdAt: any;
}

export interface Customer {
  id: string;
  userId: string;
  name: string;
  email?: string;
  phone?: string;
  whatsapp?: string;
  address?: string;
  cpfCnpj?: string;
  rg?: string;
  birthDate?: string;
  maritalStatus?: string;
  street?: string;
  number?: string;
  neighborhood?: string;
  city?: string;
  state?: string;
  zip?: string;
  complement?: string;
  profession?: string;
  company?: string;
  role?: string;
  income?: string;
  clientType?: 'PF' | 'PJ';
  registrationDate?: any;
  assignedRep?: string;
  preferredPayment?: string;
  preferredTime?: string;
  preferredChannel?: string;
  notes?: string;
  lgpdConsent?: boolean;
}

export interface Quote {
  id: string;
  userId: string;
  customerId: string;
  customerName: string;
  items: OrderItem[];
  total: number;
  discount?: number;
  status: 'DRAFT' | 'SENT' | 'APPROVED' | 'REJECTED';
  validUntil: string;
  notes?: string;
  warranty?: string;
  deliveryDeadline?: string;
  estimatedStart?: string;
  estimatedCompletion?: string;
  paymentMethod?: string;
  installments?: number;
  createdAt: any;
}

export interface Expense {
  id: string;
  userId: string;
