                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => handleExtendTrial(user)} className="p-3 bg-emerald-500/10 text-emerald-500 rounded-xl hover:bg-emerald-500 hover:text-black transition-all" title="Estender Acesso"><RefreshCw size={18} /></button>
                      <button onClick={() => handleToggleBlock(user)} className={`p-3 rounded-xl transition-all ${user.status === 'blocked' ? 'bg-cyan-500/10 text-cyan-500 hover:bg-cyan-500 hover:text-black' : 'bg-rose-500/10 text-rose-500 hover:bg-rose-50 hover:text-white'}`} title="Bloquear/Desbloquear">{user.status === 'blocked' ? <UserCheck size={18} /> : <Ban size={18} />}</button>
