    e.preventDefault();
    setIsSaving(true);
    try {
      const data = { ...formData, registrationDate: editingCustomer?.registrationDate || new Date() };
      if (editingCustomer && !editingCustomer.id.startsWith('venda-')) {
        await dbService.update('customers', editingCustomer.id, data);
      } else {
        await dbService.add('customers', userId, data);
