                   <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tight">O cliente consente com o tratamento de seus dados pessoais nos termos da LGPD para fins de cadastro e atendimento.</p>
                </div>
              </div>

              <button disabled={isSaving} type="submit" className="btn-orange w-full py-6 rounded-2xl flex items-center justify-center gap-4 text-lg">
                {isSaving ? <Loader2 className="animate-spin" /> : <UserCheck size={28}/>} SALVAR FICHA CADASTRAL
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

