            <div className="flex justify-between items-center mb-8 pb-4 border-b border-white/5">
               <h3 className="text-2xl font-black italic uppercase text-orange-500 flex items-center gap-4"><FileText /> Abertura de Ordem de Serviço</h3>
               <button onClick={()=>setIsModalOpen(false)} className="p-2 hover:bg-white/5 rounded-full text-slate-500"><X size={24}/></button>
            </div>

            <form onSubmit={handleSave} className="space-y-8">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 {/* Seção Cliente */}
                 <div className="space-y-4">
