                   <select value={formData.customerId} onChange={e=>setFormData({...formData, customerId: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold text-sm" required>
                      <option value="">Selecione o Cliente...</option>
