                      </div>
                      <div className="space-y-4">
                        <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest">Peças e Pagamento</h5>
                        <div className="bg-white/5 p-4 rounded-xl space-y-2">
                           <p className="text-white text-xs"><strong>Peças:</strong> {o.partsUsed || '---'}</p>
                           <p className="text-white text-xs"><strong>Pagamento:</strong> {o.paymentMethod || 'PIX'} {o.installments ? `(${o.installments}x)` : ''}</p>
                           <p className="text-white text-xs"><strong>Garantia:</strong> {o.warranty || '90 dias'}</p>
                        </div>
                      </div>
                      <div className="flex flex-col justify-end gap-3">
                        <button onClick={()=>updateStatus(o.id, 'DONE')} className={`w-full py-4 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-3 transition-all ${o.status==='DONE'?'bg-emerald-500 text-black':'bg-white/5 text-emerald-500 border border-emerald-500/20'}`}>
                           <CheckCircle size={16}/> Finalizar O.S.
                        </button>
                        <button onClick={()=>updateStatus(o.id, 'IN_PROGRESS')} className={`w-full py-4 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-3 transition-all ${o.status==='IN_PROGRESS'?'bg-blue-500 text-white':'bg-white/5 text-blue-400 border border-blue-400/20'}`}>
                           <Clock size={16}/> Iniciar Manutenção
                        </button>
                        <button onClick={()=>dbService.del('service_orders', o.id)} className="w-full py-4 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-3 bg-red-500/10 text-red-500 border border-red-500/20">
                           <Trash2 size={16}/> Excluir Registro
                        </button>
                      </div>
                   </div>
                </div>
              )}
            </div>
          );
        })}
