                              <input placeholder="WHATSAPP" value={formData.manualCustomerPhone} onChange={e=>setFormData({...formData, manualCustomerPhone: e.target.value})} className="w-full p-4 pl-10 rounded-xl bg-white/5 border border-white/10 text-white font-bold text-xs" required={!formData.customerId} />
                           </div>
                           <input placeholder="CPF / CNPJ" value={formData.manualCustomerCpf} onChange={e=>setFormData({...formData, manualCustomerCpf: e.target.value})} className="w-full p-4 rounded-xl bg-white/5 border border-white/10 text-white font-bold text-xs" />
                        </div>
                     </div>
                   )}

                   <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-600 uppercase ml-2">Prazo de Entrega</label>
                        <input type="text" value={formData.deliveryDeadline} onChange={e=>setFormData({...formData, deliveryDeadline: e.target.value})} className="w-full p-3 rounded-xl bg-black border border-white/10 text-white text-xs" placeholder="Ex: 48 horas" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-600 uppercase ml-2">Garantia</label>
                        <input type="text" value={formData.warranty} onChange={e=>setFormData({...formData, warranty: e.target.value})} className="w-full p-3 rounded-xl bg-black border border-white/10 text-white text-xs" placeholder="Ex: 90 dias" />
                      </div>
                   </div>
                 </div>

                 {/* Seção Equipamento */}
                 <div className="space-y-4">
                    <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest">Equipamento / Produto</h5>
                    <input placeholder="Nome do Equipamento (Ex: iPhone 13)" value={formData.equipment} onChange={e=>setFormData({...formData, equipment: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold text-sm" required />
                    <div className="grid grid-cols-3 gap-2">
                       <input placeholder="Marca" value={formData.equipmentBrand} onChange={e=>setFormData({...formData, equipmentBrand: e.target.value})} className="p-3 rounded-xl bg-black border border-white/10 text-white text-xs" />
                       <input placeholder="Modelo" value={formData.equipmentModel} onChange={e=>setFormData({...formData, equipmentModel: e.target.value})} className="p-3 rounded-xl bg-black border border-white/10 text-white text-xs" />
                       <input placeholder="Série/IMEI" value={formData.equipmentSerial} onChange={e=>setFormData({...formData, equipmentSerial: e.target.value})} className="p-3 rounded-xl bg-black border border-white/10 text-white text-xs" />
                    </div>
                 </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 {/* Seção Defeito/Diagnóstico */}
                 <div className="space-y-4">
                    <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest">Descrição Técnica</h5>
                    <textarea placeholder="Defeito Informado pelo Cliente..." value={formData.informedDefect} onChange={e=>setFormData({...formData, informedDefect: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white text-sm h-20 resize-none" />
                    <textarea placeholder="Diagnóstico Preliminar do Técnico..." value={formData.technicalDiagnosis} onChange={e=>setFormData({...formData, technicalDiagnosis: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white text-sm h-20 resize-none" />
                 </div>

                 {/* Seção Execução/Financeiro */}
                 <div className="space-y-4">
                    <h5 className="text-[10px] font-black text-orange-500 uppercase tracking-widest">Execução e Valores</h5>
                    <textarea placeholder="Descrição dos Serviços e Peças..." value={formData.description} onChange={e=>setFormData({...formData, description: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white text-sm h-20 resize-none" required />
                    <div className="grid grid-cols-3 gap-2">
                       <div className="space-y-1">
                          <label className="text-[8px] font-black text-slate-600 uppercase ml-2">Valor Previsto R$</label>
                          <input type="number" step="0.01" value={formData.cost} onChange={e=>setFormData({...formData, cost: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-black text-lg" required />
                       </div>
                       <div className="space-y-1">
                          <label className="text-[8px] font-black text-slate-600 uppercase ml-2">Forma</label>
                          <select value={formData.paymentMethod} onChange={e=>setFormData({...formData, paymentMethod: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white font-bold text-xs">
                             <option value="PIX">PIX</option>
                             <option value="DINHEIRO">DINHEIRO</option>
                             <option value="CARTÃO CRÉDITO">CARTÃO</option>
                             <option value="DEFERRED">CREDIÁRIO</option>
                          </select>
                       </div>
                       <div className="space-y-1">
                          <label className="text-[8px] font-black text-slate-600 uppercase ml-2">Parcelas</label>
                          <input type="number" min="1" value={formData.installments} onChange={e=>setFormData({...formData, installments: e.target.value})} className="w-full p-4 rounded-xl bg-black border border-white/10 text-white text-xs font-bold" />
                       </div>
                    </div>
                 </div>
               </div>

               <div className="flex items-center gap-4 bg-orange-500/10 p-4 rounded-2xl border border-orange-500/20">
                  <div className="flex items-center gap-3">
                    <input 
                      type="checkbox" 
                      id="sendWhatsApp" 
                      checked={sendWhatsApp} 
                      onChange={(e) => setSendWhatsApp(e.target.checked)}
                      className="w-5 h-5 accent-orange-500"
                    />
                    <label htmlFor="sendWhatsApp" className="text-white font-black text-[10px] uppercase tracking-widest flex items-center gap-2 cursor-pointer">
                       <Zap size={14} className="text-orange-500"/> Envio Automático via WhatsApp ao Salvar
                    </label>
                  </div>
                  <p className="text-slate-500 text-[8px] font-bold uppercase ml-auto">* Toda O.S. fica salva para consulta futura</p>
               </div>

               <button disabled={isSaving} type="submit" className="btn-orange w-full py-6 rounded-2xl flex items-center justify-center gap-3 text-lg">
                 {isSaving ? <Loader2 className="animate-spin" /> : <Wrench size={24}/>} GERAR E SALVAR ORDEM DE SERVIÇO
               </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceOrdersView;

import React, { useState, useEffect } from 'react';
import { dbService } from '../services/firebase';
import { Customer, ServiceOrder, UserProfile } from '../types';
import { Plus, Search, Trash2, Wrench, Clock, CheckCircle, X, Loader2, User, Printer, FileText, ChevronDown, ChevronUp, MessageCircle, CreditCard, Zap, Smartphone, Download } from 'lucide-react';

interface ServiceOrdersViewProps {
  userId: string;
  customers: Customer[];
  profile: UserProfile;
}

const ServiceOrdersView: React.FC<ServiceOrdersViewProps> = ({ userId, customers, profile }) => {
  const [orders, setOrders] = useState<ServiceOrder[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [search, setSearch] = useState('');
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);
  const [sendWhatsApp, setSendWhatsApp] = useState(true);

  const [formData, setFormData] = useState({
    customerId: '',
    manualCustomerName: '',
    manualCustomerPhone: '',
    manualCustomerCpf: '',
    equipment: '',
    equipmentBrand: '',
    equipmentModel: '',
    equipmentSerial: '',
    description: '',
    informedDefect: '',
    technicalDiagnosis: '',
    executedService: '',
    partsUsed: '',
    cost: '',
    paymentMethod: 'PIX',
    installments: '1',
    deliveryDeadline: '',
    warranty: '90 dias',
    notes: '',
    status: 'OPEN' as any
  });

  useEffect(() => {
    return dbService.sync('service_orders', userId, (data) => setOrders(data as ServiceOrder[]));
  }, [userId]);

  const sendWhatsAppOS = (order: ServiceOrder) => {
    const customerPhone = (order.customerPhone || '').replace(/\D/g, '');
    if (!customerPhone) return alert("Telefone não encontrado para esta O.S.");

    let msg = `*🛠️ ORDEM DE SERVIÇO - ${profile.officeName.toUpperCase()}*\n\n`;
    msg += `Olá *${order.customerName}*! Sua O.S. foi gerada com sucesso.\n\n`;
    msg += `📑 *Nº Controle:* #${order.id.substring(0,8).toUpperCase()}\n`;
    msg += `📱 *Equipamento:* ${order.equipment}\n`;
    msg += `📝 *Descrição:* ${order.description}\n`;
    msg += `💰 *Valor:* R$ ${order.cost.toFixed(2)}\n`;
    msg += `💳 *Forma Pagto:* ${order.paymentMethod} ${order.installments ? `(${order.installments}x)` : ''}\n`;
    msg += `📦 *Entrega:* ${order.deliveryDeadline || 'A combinar'}\n`;
    msg += `🛡️ *Garantia:* ${order.warranty || '90 dias'}\n\n`;
    msg += `_Pode contar conosco! Para mais detalhes, responda esta mensagem._`;

    window.open(`https://wa.me/55${customerPhone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    const customer = customers.find(c => c.id === formData.customerId);

    try {
      const orderData = {
        customerId: formData.customerId || 'GUEST',
        customerName: customer?.name || formData.manualCustomerName.toUpperCase() || 'CLIENTE AVULSO',
        customerCpfCnpj: customer?.cpfCnpj || formData.manualCustomerCpf || '',
        customerPhone: customer?.phone || formData.manualCustomerPhone || '',
        customerAddress: customer?.address || '',
        equipment: formData.equipment.toUpperCase(),
        equipmentBrand: formData.equipmentBrand.toUpperCase(),
        equipmentModel: formData.equipmentModel.toUpperCase(),
        equipmentSerial: formData.equipmentSerial.toUpperCase(),
        description: formData.description,
        informedDefect: formData.informedDefect,
        technicalDiagnosis: formData.technicalDiagnosis,
        executedService: formData.executedService,
        partsUsed: formData.partsUsed,
        cost: parseFloat(formData.cost || '0'),
        paymentMethod: formData.paymentMethod,
        installments: parseInt(formData.installments || '1'),
        deliveryDeadline: formData.deliveryDeadline,
        warranty: formData.warranty,
        notes: formData.notes,
        status: formData.status
      };

      const docRef = await dbService.add('service_orders', userId, orderData);

      if (sendWhatsApp && orderData.customerPhone) {
        sendWhatsAppOS({ id: docRef.id, ...orderData } as any);
      }

      setIsModalOpen(false);
      resetForm();
    } catch (err) { 
      console.error(err);
      alert("Erro ao salvar O.S."); 
    } finally { 
      setIsSaving(false); 
    }
  };

  const resetForm = () => {
    setFormData({
      customerId: '',
      manualCustomerName: '',
      manualCustomerPhone: '',
      manualCustomerCpf: '',
      equipment: '',
      equipmentBrand: '',
      equipmentModel: '',
      equipmentSerial: '',
      description: '',
      informedDefect: '',
      technicalDiagnosis: '',
      executedService: '',
      partsUsed: '',
      cost: '',
      paymentMethod: 'PIX',
      installments: '1',
      deliveryDeadline: '',
      warranty: '90 dias',
      notes: '',
      status: 'OPEN'
    });
  };

  const updateStatus = (id: string, nextStatus: any) => {
    dbService.update('service_orders', id, { status: nextStatus });
  };

  const getOSHtml = (order: ServiceOrder) => {
    const date = order.createdAt?.toDate ? order.createdAt.toDate().toLocaleDateString('pt-BR') : new Date().toLocaleDateString('pt-BR');
    return `
