import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { ViewState, UserProfile, Order, Product, Customer, Expense, Quote } from './types';
import { Timestamp } from 'firebase/firestore';
import { 
  LayoutDashboard, Users, LogOut, Zap, Building2, Grid3X3, 
  ShoppingCart, Lock, FileText, Calendar, Package, Wrench, Wallet, UserCircle, Gift
} from 'lucide-react';

import LoginView from './views/LoginView';
import MasterDashboard from './views/MasterDashboard';
import OfficeManagement from './views/OfficeManagement';
import NexusHub from './views/NexusHub';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import SettingsView from './views/SettingsView';
import ReferralView from './views/ReferralView';
import QuotesView from './views/QuotesView';
import CalendarView from './views/CalendarView';
import ServiceOrdersView from './views/ServiceOrdersView';
import AdminDashboard from './views/AdminDashboard';
import AIInsightsView from './views/AIInsightsView';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [loading, setLoading] = useState(true);

  const [orders, setOrders] = useState<Order[]>([]);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');

        const isMaster = u.email === "giufarlosdias@hotmail.com";
        if (isMaster) {
           const infiniteDate = new Date(2099, 11, 31);
           await dbService.update('users', u.uid, { 
             role: 'super-admin',
             subscriptionStatus: 'PAID',
             status: 'active',
             subscriptionExpiresAt: Timestamp.fromDate(infiniteDate)
           });
           p.role = 'super-admin';
           p.subscriptionStatus = 'PAID';
           p.status = 'active';
        }

        if (p.status === 'blocked') { alert("Acesso Bloqueado."); await signOut(auth); return; }

        setProfile(p as UserProfile);
        setUser(u);
        setView('DASHBOARD');

        if (p.role === 'admin' || p.role === 'super-admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('quotes', u.uid, (data) => setQuotes(data as Quote[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null); setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-white">
      <div className="relative">
        <div className="w-12 h-12 border-2 border-slate-100 rounded-full"></div>
        <div className="absolute top-0 left-0 w-12 h-12 border-t-2 border-orange-500 rounded-full animate-spin"></div>
      </div>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';
  const salesCount = orders.filter(o => o.status === 'PAID').length;
  const needsPayment = !isSuper && salesCount >= 3 && profile?.subscriptionStatus !== 'PAID';

  const NavContent = () => (
    <div className="flex flex-row lg:flex-col items-center justify-around lg:justify-start w-full gap-1 px-2 lg:px-0">
      <button onClick={()=>setView('DASHBOARD')} title="Painel" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full flex items-center justify-center ${view==='DASHBOARD'?'active':''}`}><LayoutDashboard size={20}/></button>
      <button onClick={()=>setView('SALES')} title="Vendas" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full flex items-center justify-center ${view==='SALES'?'active':''}`}><ShoppingCart size={20}/></button>
      <button onClick={()=>setView('FINANCIAL')} title="Financeiro" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full flex items-center justify-center ${view==='FINANCIAL'?'active':''}`}><Wallet size={20}/></button>
      {isSuper && <button onClick={()=>setView('OFFICES')} title="Gestão" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full flex items-center justify-center ${view==='OFFICES'?'active':''}`}><Building2 size={20}/></button>}
      <button onClick={()=>setView('PROFILE')} title="Configurações" className={`nav-btn p-3 lg:p-4 flex-1 lg:w-full flex items-center justify-center ${view==='PROFILE'?'active':''}`}><UserCircle size={20}/></button>
      <button onClick={() => signOut(auth)} title="Sair" className="nav-btn p-3 lg:p-4 flex-1 lg:w-full flex items-center justify-center text-slate-400 hover:text-red-500"><LogOut size={20}/></button>
    </div>
  );

  const renderView = () => {
    if (needsPayment && view !== 'PROFILE') {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-6 p-6 text-center animate-fade">
          <div className="w-16 h-16 bg-orange-50 border border-orange-100 rounded-2xl flex items-center justify-center shadow-sm"><Lock size={28} className="text-orange-600"/></div>
          <h2 className="text-2xl font-bold text-slate-900 tracking-tight">Assinatura Necessária</h2>
          <p className="text-slate-500 text-sm max-w-xs leading-relaxed">Seu período de avaliação atingiu o limite de operações. Regularize seu acesso para continuar.</p>
          <button onClick={() => setView('PROFILE')} className="px-8 py-3 bg-orange-500 text-white rounded-xl font-semibold text-sm hover:bg-orange-600 transition-all">Ver Planos de Acesso</button>
        </div>
      );
    }

    switch(view) {
      case 'DASHBOARD': 
        return <NexusHub setView={setView} profile={profile!} orders={orders} expenses={expenses} products={products} />;
      case 'OFFICES': 
        return isSuper ? <OfficeManagement superAdminProfile={profile!} /> : <NexusHub setView={setView} profile={profile!} orders={orders} expenses={expenses} products={products} />;
      case 'STOCK': return <ProductsView userId={user.uid} />;
      case 'SALES': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'SERVICE_ORDERS': return <ServiceOrdersView userId={user.uid} customers={customers} profile={profile!} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} orders={orders} userId={user.uid} />;
      case 'QUOTES': return <QuotesView quotes={quotes} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'FINANCIAL': return <ExpensesView expenses={expenses} userId={user.uid} profile={profile!} />;
      case 'AGENDA': return <CalendarView profile={profile!} userId={user.uid} />;
      case 'REFERRALS': return <ReferralView profile={profile!} />;
      case 'PROFILE': return <SettingsView profile={profile!} />;
      case 'AI_ASSISTANT': return <AIInsightsView orders={orders} products={products} profile={profile!} userId={user.uid} />;
      default: return <NexusHub setView={setView} profile={profile!} orders={orders} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen bg-white overflow-hidden text-slate-900">
      <aside className="hidden lg:flex w-20 border-r border-slate-100 bg-white flex-col p-4 z-20 items-center justify-between shadow-sm">
        <div className="w-10 h-10 bg-orange-500 rounded-xl flex items-center justify-center shadow-sm mb-8">
           <Zap size={20} className="text-white fill-current"/>
        </div>
        <NavContent />
        <div className="h-10"></div>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-8 relative z-10 custom-scrollbar pb-24 lg:pb-8 bg-slate-50/30">
        <div className="max-w-6xl mx-auto">
          {renderView()}
        </div>
      </main>

      <nav className="lg:hidden fixed bottom-0 left-0 right-0 h-16 bg-white border-t border-slate-100 flex items-center z-50 px-2 shadow-lg">
        <NavContent />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Users, ShoppingCart, Package, Wallet, 
  FileText, Gift, Zap, Clock, Wrench, Building2, UserCircle, 
  ArrowUpRight, ChevronRight, AlertCircle, Calendar, Bot, Sparkles, Loader2, BrainCircuit
} from 'lucide-react';
import { ViewState, UserProfile, Order, Expense, Product, FinRecord } from '../types';
import { getFinancialConsultancy } from '../services/gemini';
import { dbService } from '../services/firebase';

interface NexusHubProps {
  setView: (v: ViewState) => void;
  profile: UserProfile;
  orders: Order[];
  expenses: Expense[];
  products: Product[];
}

const NexusHub: React.FC<NexusHubProps> = ({ setView, profile, orders, expenses, products }) => {
  const [insights, setInsights] = useState<string>('');
  const [isLoadingInsights, setIsLoadingInsights] = useState(false);
  const [finances, setFinances] = useState<FinRecord[]>([]);

  const isSuper = profile.role === 'super-admin';
  const today = new Date().toLocaleDateString('pt-BR');

  const todayOrders = orders.filter(o => {
    const d = o.createdAt?.toDate ? o.createdAt.toDate().toLocaleDateString('pt-BR') : '';
    return d === today;
  });

  const totalRevenue = orders.filter(o => o.status === 'PAID').reduce((s, o) => s + o.total, 0);
  // Usaremos os registros da nova coleção para o saldo
  const totalFinExpenses = finances.filter(f => f.status === 'PAID').reduce((s, e) => s + e.amount, 0);
  const balance = totalRevenue - totalFinExpenses;

  useEffect(() => {
    const unsub = dbService.sync('finances', profile.uid, (data) => {
      setFinances(data as FinRecord[]);
    });
    return () => unsub();
  }, [profile.uid]);

  useEffect(() => {
    const generateInitialInsights = async () => {
      if (orders.length >= 0 && !insights && !isLoadingInsights) {
        setIsLoadingInsights(true);
        try {
          const result = await getFinancialConsultancy(orders, products, finances, profile);
          setInsights(result);
        } catch (error) {
          console.error("Home AI Load Failed:", error);
        } finally {
          setIsLoadingInsights(false);
        }
      }
    };
    generateInitialInsights();
  }, [orders.length, finances.length, products.length]);

  const Module = ({ icon, label, onClick }: any) => (
    <button onClick={onClick} className="flex flex-col items-center gap-2 group transition-all animate-fade">
      <div className="circle-btn shadow-sm group-hover:bg-slate-900 group-hover:text-white group-hover:border-slate-900 transition-colors">{icon}</div>
      <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500 group-hover:text-slate-900">{label}</span>
    </button>
  );

  return (
    <div className="space-y-8 pb-10">
      <header className="flex justify-between items-start">
        <div>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Visão Geral</p>
          <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">{profile.officeName}</h2>
        </div>
        <div className="bg-slate-100 px-4 py-2 rounded-full flex items-center gap-2 border border-slate-200">
           <div className="w-1.5 h-1.5 bg-slate-400 rounded-full"></div>
           <span className="text-[10px] font-bold text-slate-600 uppercase tracking-widest">v3.1 Profissional</span>
        </div>
      </header>

      {/* IA PULSE WIDGET INTEGRADO */}
      <section className="nexus-card overflow-hidden bg-slate-900 text-white border-slate-800 shadow-2xl">
        <div className="p-8 border-b border-white/5 bg-gradient-to-r from-slate-900 to-slate-800 flex items-center justify-between">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-orange-500 rounded-xl flex items-center justify-center shadow-lg shadow-orange-500/20">
                <BrainCircuit size={24} className="text-white" />
              </div>
              <div>
                <h3 className="text-lg font-black uppercase italic tracking-tight flex items-center gap-2">
                  FACINDEMAIS AI Advisor <Sparkles size={16} className="text-orange-400" />
                </h3>
                <p className="text-[8px] text-slate-500 font-black uppercase tracking-[0.2em]">Consultoria Estratégica em Tempo Real</p>
              </div>
           </div>
           <button onClick={() => setView('AI_ASSISTANT')} className="text-[10px] font-black text-slate-400 hover:text-white flex items-center gap-2 uppercase transition-all">
              Painel Completo <ChevronRight size={14}/>
           </button>
        </div>

        <div className="p-8 max-h-[400px] overflow-y-auto custom-scrollbar bg-slate-900/50">
           {isLoadingInsights ? (
             <div className="flex flex-col items-center justify-center py-20 space-y-4">
                <Loader2 className="animate-spin text-orange-500" size={32} />
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest animate-pulse">Processando telemetria financeira...</p>
             </div>
           ) : (
             <div className="prose prose-invert prose-sm max-w-none">
                <div className="text-slate-300 font-medium leading-relaxed whitespace-pre-line text-xs">
                   {insights || "Inicie suas operações para que a IA possa analisar seu fluxo de caixa e estoque."}
                </div>
             </div>
           )}
        </div>

        {!isLoadingInsights && insights && (
          <div className="px-8 py-4 bg-orange-500/10 border-t border-white/5 flex items-center gap-3">
             <div className="w-2 h-2 bg-emerald-500 rounded-full animate-ping"></div>
             <span className="text-[8px] font-black text-orange-400 uppercase tracking-widest">Análise baseada em {orders.length} vendas e {finances.length} registros financeiros</span>
          </div>
        )}
      </section>

      <section className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="nexus-card p-6 bg-white">
          <div className="flex justify-between items-center mb-2">
            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Receita do Dia</p>
            <div className="p-1.5 bg-slate-50 text-slate-400 rounded-lg"><ArrowUpRight size={14}/></div>
          </div>
          <p className="text-2xl font-bold text-slate-900">R$ {todayOrders.reduce((s,o)=>s+o.total,0).toFixed(2)}</p>
          <div className="flex items-center gap-1.5 mt-2 text-[10px] font-semibold text-slate-400">
             <ShoppingCart size={10}/> {todayOrders.length} vendas hoje
          </div>
