import { GoogleGenAI } from "@google/genai";
import { Order, Product, FinRecord, UserProfile } from "../types";

export async function getFinancialConsultancy(
  orders: Order[], 
  products: Product[], 
  finances: FinRecord[], 
  profile: UserProfile
) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const today = new Date().toLocaleDateString('pt-BR');

  const prompt = `
    Aja como o FACINDEMAIS FINANCIAL ADVISOR 4.0, um consultor financeiro digital de elite.
    Analise os dados do escritório: "${profile.officeName}" (Segmento: ${profile.segment || 'Geral'}).

    DATA DA ANÁLISE: ${today}

    MÉTRICAS BRUTAS PARA PROCESSAMENTO:
    - Vendas Totais: ${orders.length}
    - Faturamento Bruto: R$ ${orders.reduce((s, o) => s + o.total, 0).toFixed(2)}
    - Registros Financeiros (Entradas/Saídas/Fixas): ${finances.length}
    - Itens em Estoque: ${products.length}

    DETALHAMENTO DE DADOS (JSON):
    Vendas Recentes: ${JSON.stringify(orders.slice(0, 15))}
    Fluxo Financeiro: ${JSON.stringify(finances.slice(0, 15))}
    Inventário Atual: ${JSON.stringify(products.map(p => ({ n: p.name, s: p.stock, m: p.minStock, c: p.priceCost, v: p.price })))}

    ESTRUTURA OBRIGATÓRIA DO RELATÓRIO (Use Markdown de Alta Qualidade):
    1. 🤖 **Status do Núcleo**: Resumo diário do lucro líquido e saúde financeira.
    2. 🔍 **Análise Inteligente**: Identificar margens por produto e pontos de desperdício/prejuízo.
    3. 🎯 **Recomendações Estratégicas**: Onde cortar gastos, produtos para priorizar e ajustes de preços necessários.
    4. 🔮 **Projeção Mensal**: Previsão de faturamento baseado no histórico atual.
    5. 🚀 **Ticket Médio**: Como aumentar a rentabilidade por cliente.

    Linguagem: Profissional, direta, técnica porém simples para o tomador de decisão.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error: any) {
    console.error("AI Assistant Failure:", error);
    if (error?.status === "RESOURCE_EXHAUSTED" || error?.code === 429) {
      return "### Limite de Cota Atingido\nO consultor digital atingiu o limite de requisições. Por favor, aguarde alguns instantes ou verifique seu plano do Google Cloud.";
    }
    return "### Falha na Conexão Neural\nO consultor digital está temporariamente indisponível. Tente novamente em alguns instantes.";
  }
}

import React, { useState, useEffect } from 'react';
import { dbService, Timestamp } from '../services/firebase';
import { UserProfile } from '../types';
import { 
  Building2, Ban, Trash2, Search, DollarSign, Clock, ShieldAlert, Eraser, 
  Loader2, Zap, CheckCircle, MessageCircle, ChevronRight, Users, Star, X, Plus
} from 'lucide-react';

interface OfficeManagementProps {
  superAdminProfile: UserProfile;
}

const OfficeManagement: React.FC<OfficeManagementProps> = ({ superAdminProfile }) => {
  const [offices, setOffices] = useState<UserProfile[]>([]);
  const [selectedOfficeId, setSelectedOfficeId] = useState<string | null>(null);
  const [isWiping, setIsWiping] = useState(false);
  const [isModalCreateOpen, setIsModalCreateOpen] = useState(false);
  const [isCreating, setIsCreating] = useState(false);

  const [newOffice, setNewOffice] = useState({
    email: '',
    officeName: '',
    phone: '',
    subscriptionStatus: 'TRIAL' as 'TRIAL' | 'PAID'
  });

  const currentOffice = offices.find(o => o.uid === selectedOfficeId);

  useEffect(() => {
    const unsub = dbService.watchNetwork((data) => {
      setOffices(data as UserProfile[]);
    });
    return () => unsub();
  }, []);

  const getL1 = () => offices.filter(o => o.lineage?.l1 === superAdminProfile.uid);
  const getL2 = (l1Id: string) => offices.filter(o => o.lineage?.l2 === superAdminProfile.uid && o.referredBy === l1Id);
  const getL3 = (l2Id: string) => offices.filter(o => o.lineage?.l3 === superAdminProfile.uid && o.referredBy === l2Id);

  const handleCreateOffice = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newOffice.email || !newOffice.officeName) return;
    setIsCreating(true);
    try {
      const tempId = `off-${Date.now()}`;
      const nextExpiry = new Date();
      nextExpiry.setDate(nextExpiry.getDate() + (newOffice.subscriptionStatus === 'PAID' ? 30 : 7));

      const profileData = {
        uid: tempId,
        email: newOffice.email.toLowerCase(),
        officeName: newOffice.officeName.toUpperCase(),
        phone: newOffice.phone,
        role: 'admin',
        status: 'active',
        subscriptionStatus: newOffice.subscriptionStatus,
        subscriptionExpiresAt: Timestamp.fromDate(nextExpiry),
        createdAt: Timestamp.now(),
        referralCode: tempId.substring(0, 6).toUpperCase(),
        referredBy: superAdminProfile.uid,
        lineage: {
          l1: superAdminProfile.uid,
          l2: '',
          l3: ''
        }
      };

      // Simula a criação de um documento no Firestore users
      await dbService.updateProfile(tempId, profileData);

      setIsModalCreateOpen(false);
      setNewOffice({ email: '', officeName: '', phone: '', subscriptionStatus: 'TRIAL' });
      alert("Escritório cadastrado com sucesso!");
    } catch (err) {
      alert("Erro ao criar escritório.");
    } finally {
      setIsCreating(false);
    }
  };

  const handleConfirmPayment = async (uid: string) => {
    const nextExpiry = new Date();
    nextExpiry.setDate(nextExpiry.getDate() + 30);
    await dbService.update('users', uid, { 
      subscriptionStatus: 'PAID',
      status: 'active',
      subscriptionExpiresAt: Timestamp.fromDate(nextExpiry)
    });
  };

  const handleToggleBlock = async (uid: string, currentStatus: string) => {
    const nextStatus = currentStatus === 'active' ? 'blocked' : 'active';
    await dbService.update('users', uid, { status: nextStatus });
  };

  const handleSendReminder = (office: UserProfile) => {
    const phone = office.phone?.replace(/\D/g, '');
    if (!phone) return alert("WhatsApp não cadastrado.");
    const msg = encodeURIComponent(`Olá ${office.officeName}! Seu terminal FACINDEMAIS OS está próximo do vencimento. Regularize via PIX: ${superAdminProfile.pixKey || superAdminProfile.email}`);
    window.open(`https://wa.me/55${phone}?text=${msg}`, '_blank');
