        className={`cursor-pointer transition-all duration-300 hover:scale-110 flex flex-col items-center ${size === 'lg' ? 'scale-110' : size === 'sm' ? 'scale-90' : ''}`}
      >
        <div className={`rounded-xl shadow-2xl flex items-center justify-center border-2 border-white/20 bg-gradient-to-b from-blue-400 to-blue-600 p-4 mb-2 ${size === 'lg' ? 'w-24 h-24' : 'w-16 h-16'}`}>
          <Building2 size={size === 'lg' ? 48 : 32} className="text-white drop-shadow-lg" />
        </div>
