                       <input type="text" value={newOffice.phone} onChange={e=>setNewOffice({...newOffice, phone: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" placeholder="11999999999" />
