              <div className={`h-2 w-full ${getStatusInfo(currentOffice).color}`}></div>

              <div className="p-8 lg:p-10 grid grid-cols-1 lg:grid-cols-3 gap-10">
                 {/* Coluna 1: Info Base */}
                 <div className="space-y-6">
                    <div className="flex items-center gap-6">
                       <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center border border-blue-100 shadow-inner">
