                    <div className="flex flex-wrap gap-2">
                       <button onClick={() => handleSendReminder(currentOffice)} className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl hover:bg-emerald-500 hover:text-white transition-all shadow-sm" title="WhatsApp"><MessageCircle size={20}/></button>
                       <button onClick={() => handleConfirmPayment(currentOffice.uid)} className="px-6 py-4 bg-emerald-500 text-white rounded-2xl font-black text-[10px] uppercase shadow-lg hover:bg-emerald-400 transition-all flex items-center gap-2"><CheckCircle size={16}/> Renovar 30D</button>
                       <button onClick={() => handleToggleBlock(currentOffice.uid, currentOffice.status)} className={`px-6 py-4 rounded-2xl font-black text-[10px] uppercase transition-all ${currentOffice.status === 'active' ? 'bg-amber-100 text-amber-600 hover:bg-amber-600 hover:text-white' : 'bg-blue-600 text-white hover:bg-blue-500'}`}>{currentOffice.status === 'active' ? 'Bloquear' : 'Desbloquear'}</button>
                    </div>
                 </div>

                 {/* Coluna 2: Performance de Rede */}
                 <div className="space-y-6 lg:border-x border-slate-100 lg:px-10">
                    <div className="flex items-center justify-between">
                       <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2"><TrendingUp size={14} className="text-orange-500"/> Performance MMN</h5>
                       <div className="bg-orange-50 px-3 py-1 rounded-full text-[9px] font-black text-orange-600 uppercase">Total: R$ {calculateOfficeGains(currentOffice.uid).toFixed(2)}</div>
                    </div>

                    <div className="grid grid-cols-3 gap-4">
                       <div className="bg-slate-50 p-4 rounded-2xl text-center border border-slate-100">
                          <p className="text-[8px] font-black text-slate-400 uppercase mb-1">G1 (R$1)</p>
                          <p className="text-xl font-black text-slate-900">{offices.filter(u => u.lineage?.l1 === currentOffice.uid && u.subscriptionStatus === 'PAID').length}</p>
                       </div>
                       <div className="bg-slate-50 p-4 rounded-2xl text-center border border-slate-100">
                          <p className="text-[8px] font-black text-slate-400 uppercase mb-1">G2 (50¢)</p>
                          <p className="text-xl font-black text-slate-900">{offices.filter(u => u.lineage?.l2 === currentOffice.uid && u.subscriptionStatus === 'PAID').length}</p>
                       </div>
                       <div className="bg-slate-50 p-4 rounded-2xl text-center border border-slate-100">
                          <p className="text-[8px] font-black text-slate-400 uppercase mb-1">G3 (25¢)</p>
                          <p className="text-xl font-black text-slate-900">{offices.filter(u => u.lineage?.l3 === currentOffice.uid && u.subscriptionStatus === 'PAID').length}</p>
                       </div>
                    </div>

                    <div className="bg-blue-900 text-white p-6 rounded-[2rem] shadow-xl relative overflow-hidden">
                       <div className="absolute top-0 right-0 p-4 opacity-10"><Wallet size={40}/></div>
                       <p className="text-[9px] font-black text-blue-300 uppercase tracking-widest mb-1">Renda Recorrente do Escritório</p>
                       <p className="text-3xl font-black italic tracking-tighter">R$ {calculateOfficeGains(currentOffice.uid).toFixed(2)}</p>
                       <p className="text-[8px] text-blue-400 font-bold uppercase mt-2">Estimativa Mensal de Residual</p>
                    </div>
                 </div>

                 {/* Coluna 3: Lista de Indicados */}
                 <div className="space-y-6">
                    <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2"><Users size={14} className="text-blue-500"/> Indicados Diretos (Nível 1)</h5>
                    <div className="max-h-60 overflow-y-auto custom-scrollbar pr-2 space-y-2">
                       {getL1(currentOffice.uid).length > 0 ? getL1(currentOffice.uid).map(ind => (
                         <div key={ind.uid} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                            <div className="flex items-center gap-3">
                               <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-[10px] ${getStatusInfo(ind).color} ${getStatusInfo(ind).text}`}>
                                  {ind.officeName.charAt(0)}
                               </div>
                               <div>
                                  <p className="text-[10px] font-black text-slate-900 uppercase truncate w-32">{ind.officeName}</p>
                                  <p className="text-[8px] font-bold text-slate-400 uppercase">{ind.subscriptionStatus === 'PAID' ? 'Ativo' : 'Pendente'}</p>
                               </div>
                            </div>
                            <span className={`px-2 py-0.5 rounded text-[7px] font-black ${ind.subscriptionStatus === 'PAID' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                               {ind.subscriptionStatus === 'PAID' ? '+ R$ 1,00' : 'R$ 0,00'}
                            </span>
                         </div>
                       )) : (
                         <div className="py-10 text-center border-2 border-dashed border-slate-100 rounded-2xl">
                            <p className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">Nenhuma indicação direta.</p>
                         </div>
                       )}
                    </div>
                    <div className="pt-4 flex justify-between gap-4">
                       <button onClick={() => { if(confirm('Excluir definitivo?')) { dbService.del('users', currentOffice.uid); setSelectedOfficeId(null); } }} className="flex-1 py-4 bg-rose-50 text-rose-500 rounded-xl font-black text-[10px] uppercase hover:bg-rose-500 hover:text-white transition-all flex items-center justify-center gap-2"><Trash2 size={16}/> Excluir Ficha</button>
                       <button onClick={() => setSelectedOfficeId(null)} className="p-4 bg-slate-100 text-slate-400 rounded-xl hover:bg-slate-200 transition-all"><X size={20}/></button>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}

      <div className="fixed top-10 right-10 z-40 flex gap-4">
          <div className="bg-white/10 backdrop-blur-md p-2 rounded-full border border-white/20 flex items-center px-6 shadow-2xl">
            <Search size={18} className="text-white/50" />
            <input 
              placeholder="Buscar escritório..." 
              className="bg-transparent border-0 outline-none p-2 text-white font-bold text-xs w-40 placeholder:text-white/30 uppercase"
              onChange={(e) => {
                const found = offices.find(o => o.officeName.toLowerCase().includes(e.target.value.toLowerCase()));
                if(found && e.target.value.length > 2) setSelectedOfficeId(found.uid);
              }}
            />
          </div>
          <button 
            onClick={async () => {
              if(confirm('Limpar todos os terminais em TRIAL agora?')) {
                setIsWiping(true);
                const trials = offices.filter(o => o.subscriptionStatus === 'TRIAL' && o.email !== superAdminProfile.email);
                await Promise.all(trials.map(t => dbService.del('users', t.uid)));
                setIsWiping(false);
              }
            }}
            className="w-12 h-12 bg-rose-500 text-white rounded-full flex items-center justify-center shadow-2xl hover:rotate-12 transition-all border-2 border-white/10"
            title="Limpar Trials"
          >
            {isWiping ? <Loader2 className="animate-spin" size={20}/> : <Eraser size={20}/>}
          </button>
      </div>
    </div>
  );
};

export default OfficeManagement;

import React, { useState, useEffect } from 'react';
import { dbService, Timestamp } from '../services/firebase';
import { UserProfile } from '../types';
import { 
  Building2, Ban, Trash2, Search, DollarSign, Clock, ShieldAlert, Eraser, 
  Loader2, Zap, CheckCircle, MessageCircle, ChevronRight, Users, Star, X, Plus, Wallet, TrendingUp, UserCheck
} from 'lucide-react';

interface OfficeManagementProps {
  superAdminProfile: UserProfile;
}

const OfficeManagement: React.FC<OfficeManagementProps> = ({ superAdminProfile }) => {
  const [offices, setOffices] = useState<UserProfile[]>([]);
  const [selectedOfficeId, setSelectedOfficeId] = useState<string | null>(null);
  const [isWiping, setIsWiping] = useState(false);
  const [isModalCreateOpen, setIsModalCreateOpen] = useState(false);
  const [isCreating, setIsCreating] = useState(false);

  const [newOffice, setNewOffice] = useState({
    email: '',
    officeName: '',
    phone: '',
    subscriptionStatus: 'TRIAL' as 'TRIAL' | 'PAID'
  });

  const currentOffice = offices.find(o => o.uid === selectedOfficeId);

  useEffect(() => {
    const unsub = dbService.watchNetwork((data) => {
      setOffices(data as UserProfile[]);
    });
    return () => unsub();
  }, []);

  const getL1Referrals = (officeUid: string) => offices.filter(o => o.referredBy === officeUid);

  const calculateOfficeGains = (officeUid: string) => {
    // Ganhos baseados na rede DESSE escritório
    const l1Count = offices.filter(u => u.lineage?.l1 === officeUid && u.subscriptionStatus === 'PAID').length;
    const l2Count = offices.filter(u => u.lineage?.l2 === officeUid && u.subscriptionStatus === 'PAID').length;
    const l3Count = offices.filter(u => u.lineage?.l3 === officeUid && u.subscriptionStatus === 'PAID').length;
    return (l1Count * 1.00) + (l2Count * 0.50) + (l3Count * 0.25);
  };

  const handleCreateOffice = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newOffice.email || !newOffice.officeName) return;
    setIsCreating(true);
    try {
      const tempId = `off-${Date.now()}`;
      const nextExpiry = new Date();
      nextExpiry.setDate(nextExpiry.getDate() + (newOffice.subscriptionStatus === 'PAID' ? 30 : 3));

      const profileData = {
        uid: tempId,
        email: newOffice.email.toLowerCase(),
        officeName: newOffice.officeName.toUpperCase(),
        phone: newOffice.phone,
        role: 'admin',
        status: 'active',
        subscriptionStatus: newOffice.subscriptionStatus,
        subscriptionExpiresAt: Timestamp.fromDate(nextExpiry),
        createdAt: Timestamp.now(),
        referralCode: tempId.substring(0, 6).toUpperCase(),
        referredBy: superAdminProfile.uid,
        lineage: {
          l1: superAdminProfile.uid,
          l2: '',
          l3: ''
        }
      };

      await dbService.updateProfile(tempId, profileData);
      setIsModalCreateOpen(false);
      setNewOffice({ email: '', officeName: '', phone: '', subscriptionStatus: 'TRIAL' });
      alert("Escritório cadastrado com sucesso!");
    } catch (err) {
      alert("Erro ao criar escritório.");
    } finally {
      setIsCreating(false);
    }
  };

  const handleConfirmPayment = async (uid: string) => {
    if(!confirm('Deseja renovar este escritório por mais 30 dias?')) return;
    const nextExpiry = new Date();
    nextExpiry.setDate(nextExpiry.getDate() + 30);
    await dbService.update('users', uid, { 
      subscriptionStatus: 'PAID',
      status: 'active',
      subscriptionExpiresAt: Timestamp.fromDate(nextExpiry)
    });
    alert('Escritório renovado com sucesso!');
  };

  const handleToggleBlock = async (uid: string, currentStatus: string) => {
    const nextStatus = currentStatus === 'active' ? 'blocked' : 'active';
    if(!confirm(`Deseja ${nextStatus === 'blocked' ? 'BLOQUEAR' : 'DESBLOQUEAR'} este escritório?`)) return;
    await dbService.update('users', uid, { status: nextStatus });
  };

  const handleSendReminder = (office: UserProfile) => {
    const phone = office.phone?.replace(/\D/g, '');
    if (!phone) return alert("WhatsApp não cadastrado.");
    const msg = encodeURIComponent(`Olá ${office.officeName}! Seu terminal FACINDEMAIS OS está próximo do vencimento. Regularize seu acesso para continuar operando.`);
    window.open(`https://wa.me/55${phone}?text=${msg}`, '_blank');
  };

  const getStatusInfo = (office: UserProfile) => {
    const isExpired = office.subscriptionExpiresAt?.toDate() < new Date();
    if (office.status === 'blocked') return { label: 'BLOQUEADO', color: 'bg-rose-600', text: 'text-white' };
    if (office.subscriptionStatus === 'PAID' && !isExpired) return { label: 'PAGO', color: 'bg-emerald-500', text: 'text-white' };
    if (office.subscriptionStatus === 'TRIAL' && !isExpired) return { label: 'TRIAL', color: 'bg-amber-400', text: 'text-black' };
    return { label: 'INADIMPLENTE', color: 'bg-rose-500', text: 'text-white' };
  };

  const OfficeNode = ({ office, label, sublabel, size = "md" }: { office: UserProfile, label: string, sublabel: string, size?: "lg" | "md" | "sm" }) => {
    const status = getStatusInfo(office);
    return (
      <div className="flex flex-col items-center group animate-fade relative z-10">
        <div 
          onClick={() => setSelectedOfficeId(office.uid)}
          className={`cursor-pointer transition-all duration-300 hover:scale-110 flex flex-col items-center ${size === 'lg' ? 'scale-110' : size === 'sm' ? 'scale-90' : ''}`}
        >
          <div className={`rounded-xl shadow-2xl flex items-center justify-center border-2 border-white/20 bg-gradient-to-b from-blue-400 to-blue-600 p-4 mb-2 ${size === 'lg' ? 'w-24 h-24' : 'w-16 h-16'}`}>
            <Building2 size={size === 'lg' ? 48 : 32} className="text-white drop-shadow-lg" />
          </div>
          <div className={`px-4 py-1 rounded-md shadow-lg border border-white/10 min-w-[120px] text-center ${status.color}`}>
             <p className={`text-[10px] font-black uppercase truncate leading-tight ${status.text}`}>{label}</p>
          </div>
          <div className="mt-1 bg-blue-800/80 backdrop-blur-sm px-3 py-0.5 rounded border border-blue-400/30">
             <p className="text-[8px] font-bold text-blue-100 uppercase tracking-tighter whitespace-nowrap">{sublabel}</p>
          </div>
        </div>
      </div>
    );
  };

  const getL1 = () => offices.filter(o => o.lineage?.l1 === superAdminProfile.uid);
  const getL2 = (l1Id: string) => offices.filter(o => o.lineage?.l2 === superAdminProfile.uid && o.referredBy === l1Id);
  const getL3 = (l2Id: string) => offices.filter(o => o.lineage?.l3 === superAdminProfile.uid && o.referredBy === l2Id);

  return (
    <div className="min-h-screen bg-[#003399] rounded-[2.5rem] overflow-hidden shadow-2xl relative">
      <div className="absolute inset-0 bg-gradient-to-b from-blue-500/20 via-transparent to-blue-900/40 pointer-events-none"></div>

      <header className="relative z-20 p-10 flex flex-col items-center">
        <div className="flex items-center justify-center gap-4 mb-2">
          <h2 className="text-4xl lg:text-5xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">Gestão de Terminais</h2>
        </div>
        <p className="text-blue-200 font-bold text-[10px] uppercase tracking-[0.4em] opacity-80 mb-6">Controle Central de Escritórios Digitais</p>

        <button 
          onClick={() => setIsModalCreateOpen(true)}
          className="bg-orange-500 hover:bg-orange-600 text-white px-8 py-3 rounded-xl font-black text-[10px] uppercase flex items-center gap-2 shadow-2xl transform hover:scale-105 transition-all"
        >
          <Plus size={16}/> NOVO TERMINAL
        </button>
      </header>

      <main className="relative z-20 pb-40 px-4 overflow-x-auto custom-scrollbar">
        <div className="min-w-[1200px] flex flex-col items-center">
          <section className="mb-24">
            <OfficeNode 
              office={superAdminProfile} 
              label="Admin Root" 
              sublabel="VOCÊ (MASTER)" 
              size="lg" 
            />
          </section>

          <div className="relative w-full flex justify-center gap-32 mb-20">
            <div className="absolute top-[-50px] left-1/2 -translate-x-1/2 w-[90%] h-12 border-t-2 border-x-2 border-white/20 rounded-t-[4rem]"></div>

            {getL1().map(l1 => (
              <div key={l1.uid} className="flex flex-col items-center relative">
                <div className="absolute top-[-50px] left-1/2 -translate-x-1/2 w-px h-12 bg-white/20"></div>
                <OfficeNode office={l1} label={l1.officeName} sublabel="NÍVEL 1" />

                <div className="flex gap-10 mt-20 relative">
                   {getL2(l1.uid).map(l2 => (
                     <div key={l2.uid} className="flex flex-col items-center relative">
                       <div className="absolute top-[-30px] left-1/2 -translate-x-1/2 w-px h-8 bg-white/20"></div>
                       <OfficeNode office={l2} label={l2.officeName} sublabel="NÍVEL 2" size="sm" />

                       <div className="flex gap-4 mt-14 relative">
                          {getL3(l2.uid).map(l3 => (
                            <div key={l3.uid} className="flex flex-col items-center relative">
                              <div className="absolute top-[-20px] left-1/2 -translate-x-1/2 w-px h-6 bg-white/10"></div>
                              <OfficeNode office={l3} label={l3.officeName} sublabel="NÍVEL 3" size="sm" />
                            </div>
                          ))}
                       </div>
                     </div>
                   ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      {/* MODAL DETALHES DO ESCRITÓRIO SELECIONADO */}
      {currentOffice && (
