          </button>
      </div>
    </div>
  );
};

export default OfficeManagement;

import React, { useState, useEffect } from 'react';
import { dbService, Timestamp } from '../services/firebase';
import { UserProfile } from '../types';
import { 
  Building2, Trash2, Search, DollarSign, Clock, ShieldAlert, Eraser, 
  Loader2, Zap, CheckCircle, MessageCircle, ChevronRight, Users, X, Plus, Wallet, TrendingUp, UserCheck, Lock, Unlock
} from 'lucide-react';

interface OfficeManagementProps {
  superAdminProfile: UserProfile;
}

// Completed the truncated OfficeManagement component and added default export
const OfficeManagement: React.FC<OfficeManagementProps> = ({ superAdminProfile }) => {
  const [offices, setOffices] = useState<UserProfile[]>([]);
  const [selectedOfficeId, setSelectedOfficeId] = useState<string | null>(null);
  const [isModalCreateOpen, setIsModalCreateOpen] = useState(false);
  const [isCreating, setIsCreating] = useState(false);

  const [newOffice, setNewOffice] = useState({
    email: '',
    officeName: '',
    phone: '',
    subscriptionStatus: 'TRIAL' as 'TRIAL' | 'PAID'
  });

  const currentOffice = offices.find(o => o.uid === selectedOfficeId);

  useEffect(() => {
    const unsub = dbService.watchNetwork((data) => {
      setOffices(data as UserProfile[]);
    });
    return () => unsub();
  }, []);

  const handleCreateOffice = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newOffice.email || !newOffice.officeName) return;
    setIsCreating(true);
    try {
      const tempId = `off-${Date.now()}`;
      const nextExpiry = new Date();
      nextExpiry.setDate(nextExpiry.getDate() + (newOffice.subscriptionStatus === 'PAID' ? 30 : 3));

      const profileData = {
        uid: tempId,
        email: newOffice.email.toLowerCase(),
        officeName: newOffice.officeName.toUpperCase(),
        phone: newOffice.phone,
        role: 'admin',
        status: 'active',
        subscriptionStatus: newOffice.subscriptionStatus,
        subscriptionExpiresAt: Timestamp.fromDate(nextExpiry),
        createdAt: Timestamp.now(),
        referralCode: tempId.substring(0, 6).toUpperCase(),
        referredBy: superAdminProfile.uid,
        lineage: {
          l1: superAdminProfile.uid,
          l2: '',
          l3: ''
        }
      };

      await dbService.updateProfile(tempId, profileData);
      setIsModalCreateOpen(false);
      setNewOffice({ email: '', officeName: '', phone: '', subscriptionStatus: 'TRIAL' });
      alert("Escritório cadastrado com sucesso!");
    } catch (err) {
      alert("Erro ao criar escritório.");
    } finally {
      setIsCreating(false);
    }
  };

  const handleConfirmPayment = async (uid: string) => {
    if(!confirm('Deseja renovar este escritório por mais 30 dias?')) return;
    const nextExpiry = new Date();
    nextExpiry.setDate(nextExpiry.getDate() + 30);
    await dbService.update('users', uid, { 
      subscriptionStatus: 'PAID',
      status: 'active',
      subscriptionExpiresAt: Timestamp.fromDate(nextExpiry)
    });
    alert('Escritório renovado com sucesso!');
  };

  const handleToggleBlock = async (uid: string, currentStatus: string) => {
    const nextStatus = currentStatus === 'active' ? 'blocked' : 'active';
    if(!confirm(`Deseja ${nextStatus === 'blocked' ? 'BLOQUEAR' : 'DESBLOQUEAR'} este escritório?`)) return;
    await dbService.update('users', uid, { status: nextStatus });
  };

  const getStatusInfo = (office: UserProfile) => {
    const isExpired = office.subscriptionExpiresAt?.toDate() < new Date();
    if (office.status === 'blocked') return { label: 'BLOQUEADO', color: 'bg-slate-900', text: 'text-white' };
    if (office.subscriptionStatus === 'PAID' && !isExpired) return { label: 'PAGO', color: 'bg-emerald-500', text: 'text-white' };
    if (office.subscriptionStatus === 'TRIAL' && !isExpired) return { label: 'TRIAL (3 DIAS)', color: 'bg-amber-400', text: 'text-black' };
    return { label: 'INADIMPLENTE', color: 'bg-rose-500', text: 'text-white' };
  };

  const OfficeNode = ({ office, label, sublabel, size = "md" }: { office: UserProfile, label: string, sublabel: string, size?: "lg" | "md" | "sm" }) => {
    const status = getStatusInfo(office);
    return (
      <div className="flex flex-col items-center group animate-fade relative z-10">
        <div 
          onClick={() => setSelectedOfficeId(office.uid)}
          className={`cursor-pointer transition-all duration-300 hover:scale-110 flex flex-col items-center ${size === 'lg' ? 'scale-110' : size === 'sm' ? 'scale-90' : ''}`}
        >
          <div className={`rounded-xl shadow-2xl flex items-center justify-center border-2 border-white/20 bg-gradient-to-b from-blue-400 to-blue-600 p-4 mb-2 ${size === 'lg' ? 'w-24 h-24' : 'w-16 h-16'}`}>
            <Building2 size={size === 'lg' ? 48 : 32} className="text-white drop-shadow-lg" />
          </div>
          <div className={`px-4 py-1 rounded-md shadow-lg border border-white/10 min-w-[120px] text-center ${status.color}`}>
             <p className={`text-[10px] font-black uppercase truncate leading-tight ${status.text}`}>{label}</p>
          </div>
          <div className="mt-1 bg-blue-800/80 backdrop-blur-sm px-3 py-0.5 rounded border border-blue-400/30">
             <p className="text-[8px] font-bold text-blue-100 uppercase tracking-tighter whitespace-nowrap">{sublabel}</p>
          </div>
        </div>
      </div>
    );
  };

  const l1Offices = offices.filter(o => o.lineage?.l1 === superAdminProfile.uid);

  return (
    <div className="min-h-screen bg-[#003399] rounded-[2.5rem] overflow-hidden shadow-2xl relative p-8">
      <div className="absolute inset-0 bg-gradient-to-b from-blue-500/20 via-transparent to-blue-900/40 pointer-events-none"></div>

      <header className="relative z-20 flex flex-col items-center mb-12">
        <h2 className="text-4xl lg:text-5xl font-black text-white italic tracking-tighter uppercase mb-2">Gestão de Terminais</h2>
        <p className="text-blue-200 font-bold text-[10px] uppercase tracking-[0.4em] opacity-80 mb-6">Controle Central de Escritórios Digitais</p>

        <button 
          onClick={() => setIsModalCreateOpen(true)}
          className="bg-orange-500 hover:bg-orange-600 text-white px-8 py-3 rounded-xl font-black text-[10px] uppercase flex items-center gap-2 shadow-2xl transform hover:scale-105 transition-all"
        >
          <Plus size={16}/> NOVO TERMINAL
        </button>
      </header>

      <main className="relative z-20 space-y-12">
        <section className="flex flex-col items-center">
          <OfficeNode 
            office={superAdminProfile} 
            label="Admin Root" 
            sublabel="VOCÊ (MASTER)" 
            size="lg" 
          />
        </section>

        <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {l1Offices.map(office => (
            <div key={office.uid} className="bg-white/5 backdrop-blur-md p-6 rounded-3xl border border-white/10 hover:border-white/30 transition-all group">
              <div className="flex justify-between items-start mb-6">
                 <OfficeNode office={office} label={office.officeName} sublabel={office.email} />
                 <div className="flex flex-col gap-2">
                    <button onClick={() => handleConfirmPayment(office.uid)} className="p-2 bg-emerald-500 text-black rounded-lg hover:scale-110 transition-transform" title="Renovar Assinatura"><DollarSign size={16}/></button>
                    <button onClick={() => handleToggleBlock(office.uid, office.status)} className={`p-2 rounded-lg hover:scale-110 transition-transform ${office.status==='blocked'?'bg-rose-500 text-white':'bg-white/20 text-white'}`} title="Bloquear/Desbloquear">{office.status==='blocked'?<Unlock size={16}/>:<Lock size={16}/>}</button>
                 </div>
              </div>

              <div className="space-y-3 pt-4 border-t border-white/5">
                 <div className="flex justify-between text-[9px] font-black text-blue-200 uppercase">
                    <span>Expiração</span>
                    <span>{office.subscriptionExpiresAt?.toDate().toLocaleDateString('pt-BR')}</span>
                 </div>
                 <div className="flex justify-between text-[9px] font-black text-blue-200 uppercase">
                    <span>Status</span>
                    <span className={getStatusInfo(office).text}>{getStatusInfo(office).label}</span>
                 </div>
              </div>
            </div>
          ))}
        </section>
      </main>

      {isModalCreateOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
          <div className="bg-white rounded-3xl p-10 w-full max-w-md shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-black text-slate-900 uppercase italic">Novo Escritório</h3>
              <button onClick={() => setIsModalCreateOpen(false)} className="text-slate-400 hover:text-rose-500"><X size={28}/></button>
            </div>

            <form onSubmit={handleCreateOffice} className="space-y-6">
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-500 uppercase ml-2">E-mail Operacional</label>
                <input required type="email" value={newOffice.email} onChange={e=>setNewOffice({...newOffice, email: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-500 uppercase ml-2">Nome do Escritório</label>
                <input required value={newOffice.officeName} onChange={e=>setNewOffice({...newOffice, officeName: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold uppercase" />
              </div>
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-500 uppercase ml-2">WhatsApp</label>
                <input value={newOffice.phone} onChange={e=>setNewOffice({...newOffice, phone: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-500 uppercase ml-2">Plano Inicial</label>
                <select value={newOffice.subscriptionStatus} onChange={e=>setNewOffice({...newOffice, subscriptionStatus: e.target.value as any})} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold">
                  <option value="TRIAL">TRIAL (3 DIAS)</option>
                  <option value="PAID">PAGO (30 DIAS)</option>
                </select>
              </div>
              <button disabled={isCreating} className="w-full bg-orange-500 text-white py-5 rounded-2xl font-black text-sm uppercase shadow-xl hover:bg-orange-600 transition-all">
                {isCreating ? <Loader2 className="animate-spin mx-auto"/> : 'ATIVAR TERMINAL'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

